    const j = pose.joints, f = pose.face, horizontal = Math.hypot(f[0], f[2]) || 1;
    const front = [f[0] / horizontal, 0, f[2] / horizontal];
    const length = Math.hypot(...j.head.map((v, i) => v - j.neck[i]));
