  /* A UI reminder only. Show documents and autosave retain their existing contract. */
  function createStorageBand() {
    const band = document.getElementById("stage-storage-band");
    const native = window.STAGE_RUNTIME.isMac();
    if (!band || native || STUDY_READ_ONLY) return null;
    const DAY = 86400000;
    const safari = /WebKit/.test(navigator.userAgent) && !/Chrome|Chromium|Edg|CriOS|FxiOS|OPR/.test(navigator.userAgent);
    const firefox = /Firefox|FxiOS/.test(navigator.userAgent);
    const installed = () => window.matchMedia("(display-mode: standalone)").matches || navigator.standalone === true;
    const visitKey = "gamma:storage-band-last-open-v1:";
    const foldKey = "gamma:storage-band-folded-v1";
    const seen = new Set();
    let persisted = false, requested = false, lastSavedAt = state.lastSavedAt;
    let modalDays = null, modalProject = null, returnFocus = null;
    const byId = suffix => document.getElementById("stage-storage-" + suffix);
    const modal = byId("return-modal"), backdrop = byId("return-backdrop");
    const exportButton = byId("band-export"), fold = byId("band-fold");
    const age = stamp => {
      const ms = stamp ? Date.parse(stamp) : NaN;
      return Number.isFinite(ms) ? Math.max(0, Math.floor((Date.now() - ms) / DAY)) : null;
    };
    // A reload starts a new visible reminder even though sessionStorage survives it.
    try { sessionStorage.removeItem(foldKey); } catch (_) { /* optional UI memory */ }
    function close() {
      if (modal.hidden) return;
      modal.hidden = backdrop.hidden = true;
      returnFocus?.focus({ preventScroll:true });
    }
    function open(days) {
      modalDays = days; modalProject = state.project.id;
      returnFocus = document.activeElement;
      modal.hidden = backdrop.hidden = false;
      byId("return-title").textContent = tx("控えを書き出してください");
      byId("return-lead").textContent = tx("このショーは ○日間開かれていません。ブラウザ内の保存は消えることがあります。いま控えを書き出しておくと安全です。").replace("○", String(days));
      byId("return-export").textContent = tx("いま書き出す");
      byId("return-later").textContent = tx("あとで");
      byId("return-close").setAttribute("aria-label", tx("この知らせを閉じる"));
      byId("return-export").focus({ preventScroll:true });
    }
    async function refreshPersistence(request) {
      try {
        if (request && !requested && typeof navigator.storage?.persist === "function") {
          requested = true;
          await navigator.storage.persist();
        }
        persisted = typeof navigator.storage?.persisted === "function" && await navigator.storage.persisted() === true;
      } catch (_) { persisted = false; }
      update();
    }
    function update() {
      // Before session.js boots, the invitation hash already identifies the guest entrance.
      // Afterwards the session owns pending/cancelled/connected state, even if the hash remains.
      const session = window.SHOSAI_STAGE_SESSION_HOOKS;
      const guestView = typeof session?.guestView === "function" ? session.guestView()
        : guestSessionActive() || /^#session=[a-z0-9]{1,64}$/i.test(location.hash);
      if (guestView) { band.hidden = true; close(); return; }
      const id = state.project.id;
      if (!modal.hidden && modalProject !== id) close();
      if (!seen.has(id)) {
        seen.add(id);
        try {
          const previous = localStorage.getItem(visitKey + id);
          const days = age(previous);
          localStorage.setItem(visitKey + id, new Date().toISOString());
          if (days !== null && days >= 7) open(days);
        } catch (_) { /* No previous marker is normal on a first launch, not proof of loss. */ }
      }
      if (firefox && state.lastSavedAt && state.lastSavedAt !== lastSavedAt) {
        lastSavedAt = state.lastSavedAt;
        void refreshPersistence(true);
      }
      const days = age(state.lastExportAt);
      const stale = days === null || Date.now() - Date.parse(state.lastExportAt) > 7 * DAY;
      const protectedStorage = installed() && persisted;
      band.hidden = false;
      band.classList.toggle("is-protected", protectedStorage);
      band.classList.toggle("is-stale", stale);
      band.dataset.persistence = String(persisted);
      band.dataset.state = protectedStorage ? "protected" : safari && !installed() ? "safari" : days === null ? "unexported" : stale ? "stale" : "normal";
      const lead = protectedStorage
        ? "この端末の保存は保護されています（インストール済み）。それでも控えは取ってください。"
        : safari && !installed()
        ? "Safari は 7 日間このサイトを操作しないと保存データをすべて削除します。ホーム画面に追加するか、控えを書き出してください。普段は Mac 版をお使いください。"
        : "ブラウザ版のショーはこの端末のブラウザの中だけに保存されます。ブラウザの設定や長い未使用で消えることがあります。普段は Mac 版をお使いください。";
      byId("band-lead").textContent = tx(lead);
      byId("band-backup").textContent = days === null ? tx("控え: まだ一度も書き出していません") : tx("控え: 最終 ○日前").replace("○", String(days));
      fold.textContent = stale ? "!" : protectedStorage ? "✓" : "!";
      fold.setAttribute("aria-label", tx("この起動中だけ忠告帯を畳む"));
      exportButton.textContent = tx("いま書き出す");
      const install = byId("band-install"), download = byId("band-download");
      install.hidden = !safari || installed();
      install.textContent = install.title = tx("ホーム画面に追加の手順");
      download.textContent = download.title = tx("Mac 版を入手");
      // The authenticated Worker does not serve /download/. Keep its existing boundary.
      download.href = ["localhost", "127.0.0.1"].includes(location.hostname) || location.hostname.endsWith("github.io")
        ? "./download/?lang=" + encodeURIComponent(lang) : "https://aratama-ship-it.github.io/stage-sketch-gamma/download/?lang=" + encodeURIComponent(lang);
      const manualLang = lang === "ja" ? "ja" : "en";
      install.href = "./manual-gamma/?lang=" + manualLang + "#browser-storage";
      if (layoutLaneSaveUnconfirmed) {
        band.classList.remove("is-folded", "is-protected");
        byId("band-lead").textContent = tx("この端末へ保存できませんでした。ファイルへ書き出して残してください。");
        byId("band-backup").textContent = "";
      }
      if (!modal.hidden && modalDays !== null) {
        byId("return-lead").textContent = tx("このショーは ○日間開かれていません。ブラウザ内の保存は消えることがあります。いま控えを書き出しておくと安全です。").replace("○", String(modalDays));
      }
    }
    fold.addEventListener("click", () => {
      band.classList.add("is-folded");
      try { sessionStorage.setItem(foldKey, "1"); } catch (_) { /* optional */ }
      document.querySelector(".stage-sketch-head button")?.focus({ preventScroll:true });
      window.dispatchEvent(new Event("resize"));
    });
    exportButton.addEventListener("click", () => els.exportJson?.click());
    byId("return-export").addEventListener("click", () => { close(); els.exportJson?.click(); });
    ["return-close", "return-later", "return-backdrop"].forEach(name => byId(name).addEventListener("click", close));
    document.addEventListener("keydown", event => {
      if (modal.hidden) return;
      if (event.key === "Escape") { event.preventDefault(); event.stopImmediatePropagation(); close(); }
      if (event.key !== "Tab") return;
      const actions = [byId("return-close"), byId("return-export"), byId("return-later")];
      if (event.shiftKey && document.activeElement === actions[0]) { event.preventDefault(); actions[2].focus(); }
      else if (!event.shiftKey && document.activeElement === actions[2]) { event.preventDefault(); actions[0].focus(); }
    }, true);
    window.matchMedia("(display-mode: standalone)").addEventListener?.("change", update);
    window.addEventListener("stage-session-view-change", update);
    window.addEventListener("hashchange", update);
    new MutationObserver(update).observe(document.body, { attributes:true, attributeFilter:["class"] });
    update();
    void refreshPersistence(!firefox);
    return { update };
  }

  function headerTimestamp(value) {
    return window.STAGE_TIME_DOMAIN.dateText(value, document.documentElement.lang || "ja", {time:true});
  }

  // 時刻を進めるのは、保存・書き出しの成功を確認した後だけに限る。
  function syncSaveStamps() {
    storageBand?.update();
    syncBackupStatus();
    if (els.lastSaveTime) els.lastSaveTime.textContent = headerTimestamp(state && state.lastSavedAt);
    if (els.lastBackupTime) els.lastBackupTime.textContent = headerTimestamp(state && state.lastExportAt);
  }

  /* 操作結果の状態行は6秒で消す。視覚表示は既定OFF・環境設定で切替、読み上げは継続。
   * 「最後の控え: …」の常設ボタンは 2026-10-11 本人指示で箱ごと外した（控えの時刻はショー設定の「最終バックアップ」で見る）。
   * 一時表示が終わったら空に戻す＝#stage-live:empty で箱も消える。 */
  function syncBackupStatus() {
    if (STUDY_READ_ONLY || !els.live || els.live.dataset.transient === "true") return;
    if (els.live.firstChild) els.live.replaceChildren();
  }

  function syncShowTimecode(detail) {
    if (els.showElapsed) els.showElapsed.textContent = typeof detail?.timecodeText === "string" ? detail.timecodeText : "—";
  }
  window.addEventListener("stage-timeline-position-change", (event) => {
    syncShowTimecode(event && event.detail);
    const next = event?.detail?.transition || null;
    const changed = Boolean(next) !== Boolean(timelineTransitionPhase);
    timelineTransitionPhase = next;
    if (changed) requestTransitionBadgeRender();
  });

  let projectSettingsReturnFocus = null;

  function openBackgroundPanel() {
    const panel = panelEl("background");
    if (!panel || editionHidesPanel("background")) return;
    syncLowFogControl();
    setFeaturePreference("panelBackground", true);
    state.layout.collapsed.background = false;
    applyFeatureFlags();
    applyLayout();
    persistSoon();
    if (tabletUi) {
      openTabletGroup("look");
      return;
    }
    const heading = panel.querySelector(".stage-panel-head");
    panel.scrollIntoView({ block: "nearest", inline: "nearest" });
    heading?.focus({ preventScroll: true });
  }

  function openProjectSettings() {
    if (window.GAMMA_UI.layers.isOpen(els.projectSettingsModal)) return;
    if (!els.projectSettingsModal) return;
    projectSettingsReturnFocus = document.activeElement;
    if (els.projectTitle) els.projectTitle.value = state.project.title;
    if (els.versionLabel) els.versionLabel.value = state.project.versionLabel;
    els.projectSettingsModal.hidden = false;
    if (els.projectSettingsBackdrop) els.projectSettingsBackdrop.hidden = false;
    if (els.projectTitle) els.projectTitle.focus();
  }

  function closeProjectSettings() {
    if (els.projectSettingsModal) els.projectSettingsModal.hidden = true;
    if (els.projectSettingsBackdrop) els.projectSettingsBackdrop.hidden = true;
    const target = projectSettingsReturnFocus;
    projectSettingsReturnFocus = null;
    if (target && target.isConnected && typeof target.focus === "function") {
      target.focus({ preventScroll: true });
    }
  }

  function openShows() {
    if (typeof nativeProject !== "undefined" && nativeProject) { nativeProject.request("requestOpen"); return; }
    if (!els.showsModal) return;
    renderShows();
    const saveError = document.getElementById("stage-show-save-error");
    if (saveError) saveError.hidden = true;
    els.showsModal.hidden = false;
    els.showsBackdrop.hidden = false;
  }

  window.STAGE_PROJECT_LIBRARY?.configure({
    importPackage: read => importProjectPackage(read, {librarySample:true}), closeShows,
    isNative: () => Boolean(nativeProject), version:GAMMA_APP_VERSION.replace(/^v/, ""),
  });
  document.getElementById("stage-shows-samples-open")?.addEventListener("click", () => window.STAGE_PROJECT_LIBRARY?.open("samples"));
  document.getElementById("stage-project-samples-open")?.addEventListener("click", (event) => {
    // Safariのタップでも既存ライブラリが戻す焦点をこの入口にそろえる。
    event.currentTarget.focus({ preventScroll: true });
    window.STAGE_PROJECT_LIBRARY?.open("samples");
  });

  document.getElementById("stage-show-save-export")?.addEventListener("click", () => exportProject());

  function closeShows() {
    if (bundledDownload) cancelBundledDownload();
    if (els.showsModal) els.showsModal.hidden = true;
    if (els.showsBackdrop) els.showsBackdrop.hidden = true;
  }

  /* ---------- 段階0: ビート骨格テンプレート ----------
     適用先は常に別の新規ショー。いまのショーを棚へ残したうえで切り替えるので、
     既存シーンへの上書き・追記という危険な分岐を持たない。 */
  async function createShowFromBeatTemplate(templateId) {
    const template = BEAT_TEMPLATES.find((item) => item.id === templateId);
    const rows = beatTemplateRows(templateId);
    if (!template || template.available === false || !rows.length) return;
    const fresh = baseState(false);
    fresh.project.title = tx(template.name);
    fresh.project.scenes = rows.map((row) => {
      const role = tx(row.beat.role);
      const scene = newScene(role, false);
      scene.beat = normalizeBeat({ ...row.beat, role });
      return scene;
    });
    fresh.project.activeSceneId = fresh.project.scenes[0].id;
    fresh.layout = state.layout;
    if (!await applyLoadedState(normalizeState(fresh), sx(`「${template.name}」から新しいショーを作りました。前のショーは一覧に残っています。`, `Created a new show from “${tx(template.name)}”. The previous show is still in All shows.`))) return;
    closeBeatTemplates();
    renderShows();
  }

  function renderBeatTemplates() {
    if (!els.beatTemplateList) return;
    els.beatTemplateList.innerHTML = "";
    BEAT_TEMPLATES.forEach((template) => {
      const available = template.available !== false;
      const card = document.createElement("article");
      card.className = `stage-beat-template-card${available ? "" : " is-held"}`;

      const copy = document.createElement("div");
      copy.className = "stage-beat-template-copy";
      const heading = document.createElement("h3");
      heading.className = "stage-beat-template-heading";
      const number = document.createElement("span");
      number.className = "stage-beat-template-number";
      number.textContent = String(template.number).padStart(2, "0");
      const name = document.createElement("span");
      name.textContent = tx(template.name);
      heading.append(number, name);

      const count = document.createElement("p");
      count.className = "stage-beat-template-count";
      count.textContent = sx(`生成 ${template.roles.length}シーン・D2目安 ${template.range}`, `Creates ${template.roles.length} scenes · D2 guide ${tx(template.range)}`);
      const roles = document.createElement("p");
      roles.className = "stage-beat-template-roles";
      roles.textContent = template.roles.map((role) => tx(role)).join(" → ");
      copy.append(heading, count, roles);

      const side = document.createElement("div");
      side.className = "stage-beat-template-side";
      const apply = document.createElement("button");
      apply.type = "button";
      apply.className = "stage-beat-template-apply";
      apply.disabled = !available;
      apply.textContent = tx("この骨格で新しいショーを作る");
      apply.addEventListener("click", () => createShowFromBeatTemplate(template.id));
      side.append(apply);
      card.append(copy, side);
      els.beatTemplateList.append(card);
    });
  }

  function openBeatTemplates() {
    if (!els.beatTemplatesModal) return;
    renderBeatTemplates();
    els.beatTemplatesModal.hidden = false;
    if (els.beatTemplatesBackdrop) els.beatTemplatesBackdrop.hidden = false;
  }

  function closeBeatTemplates() {
    if (els.beatTemplatesModal) els.beatTemplatesModal.hidden = true;
    if (els.beatTemplatesBackdrop) els.beatTemplatesBackdrop.hidden = true;
  }

  /* ---------- 姿勢を選ぶ ----------
     名前だけでは「片膝立ち」と「しゃがむ」の違いが伝わらないので、
     実際の形を小さく描いて並べる。舞台の絵と同じ骨格・同じ塗りを通すので、
     見本と本番がずれない。 */

  /* 2026-09-23 本人指示: 階段・スロープ・自転車・一輪車・スラックライン・スケートボードは、
   * 真正面(0°)からだと形が読みにくいので、ターンテーブルの開始位置を90°回した状態にする。
   * 回転そのものは今までどおり続く。 */
  const TURNTABLE_START_FACING_OFFSET = {
    stairs: 90, stairs6: 90, slope: 90, bicycle: 90,
    unicycle: 90, slackline: 90, skateboard: 90,
    // 2026-09-23 本人指定: 真正面だと2足が重なって箱に見える。斜め45度から始める
    rollerskate: 45,
  };
  // 種類ごとの一覧プレビューの実測フィット（拡大率・位置）。中身が変わることはないので使い回す。
  const KIND_PREVIEW_FIT_CACHE = new Map();
  /* 種類の見本。正面から見た形（左右と高さ）だけを描き、奥行きは捨てる。
   * 舞台の道具は左右に広く奥行きが浅いので、正面図がいちばん特徴的な輪郭を見せる
   * （真横から起こすと、車も綱渡りもティーターボードも細い板に潰れて見分けがつかない）。
   * 舞台の絵と同じ部品（pieceParts）から起こすので、
   * 一覧の絵と実際に置かれる物が食い違わない。 */
  function drawKindPreview(canvas, kind, color, propShapeId = null, turntableFacing = 0) {
    const ctx2 = canvas.getContext("2d");
    const w = canvas.width;
    const h = canvas.height;
    ctx2.clearRect(0, 0, w, h);
    if (kind === "performer") {
      // 人だけは骨格を持っているので、立ち姿をそのまま使う
      drawPosePreview(canvas, "stand", color);
      return;
    }
    if (kind === "light") {
      ctx2.save();
      ctx2.strokeStyle = color;
      ctx2.lineWidth = 2;
      ctx2.beginPath();
      ctx2.moveTo(w * 0.5, h * 0.16);
      ctx2.lineTo(w * 0.22, h * 0.8);
      ctx2.lineTo(w * 0.78, h * 0.8);
      ctx2.closePath();
      ctx2.globalAlpha = 0.35;
      ctx2.fillStyle = color;
      ctx2.fill();
      ctx2.globalAlpha = 1;
      ctx2.stroke();
      ctx2.restore();
      return;
    }
    /* 2026-09-23 本人指摘: 台・箱／車／球など大道具のkindは、この分岐に入らず
     * bindKindPreviewSpin の既定（canvasをCSSで平面回転＝奥行き軸）へ落ちていた。
     * 小道具（prop/diabolo）だけ縦軸まわりの本物の回転台になっていて、
     * 見た目の軸が種類によって違って見えていたのはこれが原因。
     * seri・model は下の専用の簡略プレビュー（せりの点線枠／組んだセットの見本）を
     * そのまま使うのでここでは扱わない。それ以外は全部この経路へ寄せて軸を揃える。 */
    if (!["seri", "model"].includes(kind) && (kind !== "prop" || PROP_SHAPES[propShapeId])) {
      /* 一覧専用の簡略図ではなく、正面図で実際に使う描画経路をそのまま縮小する。
       * selectionBounds も本番と共通なので、長い梯子や背の低い家具でも枠内へ収まる。
       * 小道具の回転中は canvas 自体を平面で回さず、駒を上下軸で回す。
       * これで正面・側面・奥行きが同じ回転台の上で見える。 */
      const startFacing = (TURNTABLE_START_FACING_OFFSET[propShapeId] || 0) + turntableFacing;
      const previewPiece = normalizePiece({
        id: `stage-kind-preview-${propShapeId}`,
        type: kind,
        propShape: kind === "prop" ? propShapeId : null,
        u: 0.5,
        v: 0.62,
        size: 100,
        color,
        facing: startFacing,
        dims: kind === "prop" ? PROP_SHAPES[propShapeId].dims : normalizeDims(kind, {}),
      }, 0);
      const previewLayout = layout("front");
      refreshBases(previewLayout.size, [previewPiece]);
      /* ★2026-09-23 本人指摘: 回っている間に大きさが変わって見えていた。
       * 見えている枠(bounds)は向きによって幅が変わるので、その場その場で
       * 枠いっぱいに合わせて拡大率を計算し直すと、回転中ずっと拡大縮小して見える。
       * 向き0°・90°の2方向で測った外接枠のうち大きいほうを基準に、
       * 拡大率は回転中ずっと同じ値に固定する。 */
      const boundsAt = (facing) => selectionBounds({ ...previewPiece, facing }, previewLayout);
      const envelopes = Array.from({length: 24}, (_, i) => boundsAt(i * 15));
      const boundsX0 = Math.min(...envelopes.map(b => b.x));
      const boundsY0 = Math.min(...envelopes.map(b => b.y));
      const approxBounds = {
        x: boundsX0, y: boundsY0,
        w: Math.max(...envelopes.map(b => b.x + b.w)) - boundsX0,
        h: Math.max(...envelopes.map(b => b.y + b.h)) - boundsY0,
      };
      const pad = 10;
      const draw = (target, fit, facing = startFacing) => {
        target.save();
        target.setTransform(fit.scale, 0, 0, fit.scale, fit.offsetX, fit.offsetY);
        // 一覧は132pxへ縮めるため、立体の各面の境界線まで描くと横筋として重なる。
        // 本番の舞台図は既定どおり面線を残し、ここだけ輪郭と陰影を塗りで見せる。
        drawStagePiece(target, { ...previewPiece, facing }, previewLayout, () => 0, { showFaceEdges: false });
        target.restore();
      };
      const fitFrom = (bounds) => {
        const scale = Math.min(
          (w - pad * 2) / Math.max(1, bounds.w),
          (h - pad * 2) / Math.max(1, bounds.h),
        );
        return {
          scale,
          offsetX: pad - bounds.x * scale + (w - pad * 2 - bounds.w * scale) / 2,
          offsetY: pad - bounds.y * scale + (h - pad * 2 - bounds.h * scale) / 2,
        };
      };
      /* ★2026-09-23 本人指摘: マイク・グラス・電話・ディアボロ・シガーボックス・マスク等が
       * 一覧の枠内で中央に来ていなかった。selectionBounds の外接枠は「駒の平らな設置面
       * (pieceFootprint)の4隅」を正面図の遠近込みで投影して求めるが、実際に描かれる
       * 円柱・球の丸い断面や、奥行きのある立体の輪郭とは一致せず、特に見本のように
       * 小さく引いて見るとズレが目立った。ここでは近似の枠でいったん描いてから実際に
       * 塗られた画素の外接枠を測り直し、その実測値で中央に収め直す（種類ごとに1回だけ
       * 測ればよいので、同じ kind/propShapeId の間は使い回す）。 */
      const fitCacheKey = `${kind}:${propShapeId || ""}:${w}x${h}`;
      let fit = KIND_PREVIEW_FIT_CACHE.get(fitCacheKey);
      if (!fit) {
        const initialFit = fitFrom(approxBounds);
        const measureCanvas = document.createElement("canvas");
        measureCanvas.width = w * 2;
        measureCanvas.height = h * 2;
        const measureContext = measureCanvas.getContext("2d", { willReadFrequently: true });
        const measureFit = {
          ...initialFit,
          offsetX: initialFit.offsetX + (measureCanvas.width - w) / 2,
          offsetY: initialFit.offsetY + (measureCanvas.height - h) / 2,
        };
        const measuredFacings = [];
        const previewOffset = TURNTABLE_START_FACING_OFFSET[propShapeId] || 0;
        const measuredAngles = [...new Set([
          0, 90, 180, 270,
          ...Array.from({ length: 8 }, (_, index) => previewOffset + index * 45),
        ])];
        measuredAngles.forEach((facing) => {
          measureContext.clearRect(0, 0, measureCanvas.width, measureCanvas.height);
          draw(measureContext, measureFit, facing);
          const pixels = measureContext.getImageData(0, 0, measureCanvas.width, measureCanvas.height).data;
          let x0 = measureCanvas.width; let y0 = measureCanvas.height; let x1 = -1; let y1 = -1;
          for (let y = 0; y < measureCanvas.height; y += 1) {
            for (let x = 0; x < measureCanvas.width; x += 1) {
              if (pixels[(y * measureCanvas.width + x) * 4 + 3] <= 10) continue;
              x0 = Math.min(x0, x); y0 = Math.min(y0, y);
              x1 = Math.max(x1, x); y1 = Math.max(y1, y);
            }
          }
          if (x1 < x0 || y1 < y0) return;
          const actual = {
            x: (x0 - measureFit.offsetX) / measureFit.scale,
            y: (y0 - measureFit.offsetY) / measureFit.scale,
            w: (x1 - x0 + 1) / measureFit.scale,
            h: (y1 - y0 + 1) / measureFit.scale,
          };
          measuredFacings.push(actual);
        });
        let measured = null;
        let measuredCenter = null;
        let maxCenterShift = 0;
        if (measuredFacings.length) {
          const centersX = measuredFacings.map((bounds) => bounds.x + bounds.w / 2);
          const centersY = measuredFacings.map((bounds) => bounds.y + bounds.h / 2);
          const centerX = (Math.min(...centersX) + Math.max(...centersX)) / 2;
          const centerY = (Math.min(...centersY) + Math.max(...centersY)) / 2;
          measuredCenter = { x: centerX, y: centerY };
          maxCenterShift = Math.max(...measuredFacings.map((bounds) => Math.max(
            Math.abs(bounds.x + bounds.w / 2 - centerX),
            Math.abs(bounds.y + bounds.h / 2 - centerY),
          )));
          const extentX = Math.max(...measuredFacings.flatMap((bounds) => [
            centerX - bounds.x, bounds.x + bounds.w - centerX,
          ]));
          const extentY = Math.max(...measuredFacings.flatMap((bounds) => [
            centerY - bounds.y, bounds.y + bounds.h - centerY,
          ]));
          measured = { x: centerX - extentX, y: centerY - extentY, w: extentX * 2, h: extentY * 2 };
        }
        fit = fitFrom(measured || approxBounds);
        if (measuredCenter && maxCenterShift > 0 && maxCenterShift * fit.scale > 0.5) {
          fit.scale = 0.5 / maxCenterShift;
          fit.offsetX = w / 2 - measuredCenter.x * fit.scale;
          fit.offsetY = h / 2 - measuredCenter.y * fit.scale;
        }
        KIND_PREVIEW_FIT_CACHE.set(fitCacheKey, fit);
      }
      ctx2.clearRect(0, 0, w, h);
      draw(ctx2, fit);
      return;
    }
    const propShape = kind === "prop" && PROP_SHAPES[propShapeId] ? PROP_SHAPES[propShapeId] : null;
    const dims = propShape ? { ...propShape.dims } : normalizeDims(kind, {});
    if (kind === "sphere") {
      // 球は部品を持たない（円ひとつで決まる）ので、ここで描く
      const r = Math.min(w, h) * 0.32;
      ctx2.save();
      ctx2.fillStyle = color;
      ctx2.beginPath();
      ctx2.arc(w / 2, h * 0.62, r, 0, Math.PI * 2);
      ctx2.fill();
      ctx2.restore();
      return;
    }
    if (kind === "seri") {
      // 下がり切った既定状態。登録時の見本も床面の継ぎ目として見せる
      ctx2.save();
      ctx2.strokeStyle = color;
      ctx2.lineWidth = 1.5;
      ctx2.setLineDash([5, 4]);
      ctx2.strokeRect(w * 0.16, h * 0.42, w * 0.68, h * 0.34);
      ctx2.restore();
      return;
    }
    const modelPreview = kind === "model" && stageModelLibrary().models[0];
    const parts = modelPreview ? window.SHOSAI_STAGE_MODELS.modelBoxes(modelPreview)
      : pieceParts({ type: kind, dims, facing: 0, propShape: propShape ? propShapeId : null });
    if (!parts || !parts.length) return;
    /* トラピーズの吊りロープは、舞台では吊物の描画が引くので pieceParts に無い。
       見本ではバー一本になり、床に置いた板と見分けがつかないので、ここで足す。 */
    if (kind === "trapeze") {
      const half = (dims.w || 0.7) / 2;
      [-half, half].forEach((x) => parts.push({
        kind: "line", a: [x, 0.03, 0], b: [x, 0.62, 0], w: 0.018, tone: "gear",
      }));
    }
    // 幅と高さの範囲を測る
    let x0 = Infinity; let x1 = -Infinity; let y0 = Infinity; let y1 = -Infinity;
    const scan = (x, y) => { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); };
    parts.forEach((part) => {
      if (part.kind === "line") { scan(part.a[0], part.a[1]); scan(part.b[0], part.b[1]); return; }
      if (part.kind === "ring") { scan(part.c[0] - part.r, part.c[1] - part.r); scan(part.c[0] + part.r, part.c[1] + part.r); return; }
      // 円板は床と平行なので、見本では幅2rの薄い板として測る
      if (part.kind === "disc") {
        scan(part.c[0] - part.r, part.c[1]);
        scan(part.c[0] + part.r, part.c[1] + (part.h || 0));
        return;
      }
      if (part.kind === "cylinder") {
        scan(part.ox - part.r, part.lift);
        scan(part.ox + part.r, part.lift + part.h);
        return;
      }
      scan(part.ox - part.w / 2, part.lift); scan(part.ox + part.w / 2, part.lift + part.h);
    });
    const pad = 14;
    const bw = Math.max(0.01, x1 - x0);
    const bh = Math.max(0.01, y1 - y0);
    const k = Math.min((w - pad * 2) / bw, (h - pad * 2) / bh);
    const ox = (w - bw * k) / 2 - x0 * k;
    const oy = h - pad - (0 - y0) * k;          // 床（y=0）を下端に置く
    const px = (x) => ox + x * k;
    const py = (y) => oy - y * k;

    ctx2.save();
    ctx2.lineCap = "round";
    ctx2.lineJoin = "round";
    parts.forEach((part) => {
      if (part.kind === "line") {
        // 見本でも布・木・金属を描き分ける（実際の舞台上の見えと揃える）
        ctx2.strokeStyle = part.tone === "cloth" ? color
          : part.tone === "wood" ? "rgba(196,158,104,0.95)"
          : part.tone === "dark" ? "rgba(126,116,106,0.95)"
          : "rgba(214,220,226,0.9)";
        ctx2.lineWidth = Math.max(1.5, (part.w || 0.04) * k);
        ctx2.beginPath();
        ctx2.moveTo(px(part.a[0]), py(part.a[1]));
        ctx2.lineTo(px(part.b[0]), py(part.b[1]));
        ctx2.stroke();
        return;
      }
      if (part.kind === "ring") {
        ctx2.strokeStyle = part.tone === "dark" ? "rgba(60,54,48,0.95)" : "rgba(214,220,226,0.9)";
        ctx2.lineWidth = Math.max(1.5, (part.w || 0.04) * k);
        ctx2.beginPath();
        if (part.plane === "xz") {
          // 床と平行の輪。真横から見れば一本の横線になる（真円で描くと別物に見える）
          ctx2.moveTo(px(part.c[0] - part.r), py(part.c[1]));
          ctx2.lineTo(px(part.c[0] + part.r), py(part.c[1]));
        } else {
          ctx2.arc(px(part.c[0]), py(part.c[1]), part.r * k, 0, Math.PI * 2);
        }
        ctx2.stroke();
        return;
      }
      if (part.kind === "disc") {
        // 見本は正面から見た形なので、床と平行の円板は幅2rの薄い板として出す
        ctx2.fillStyle = part.tint >= 1 ? color : mixToward(color, 1 - (part.tint || 1));
        ctx2.fillRect(px(part.c[0] - part.r), py(part.c[1] + (part.h || 0)),
          Math.max(1.5, part.r * 2 * k), Math.max(1.5, (part.h || 0.03) * k));
        return;
      }
      if (part.kind === "cylinder") {
        ctx2.fillStyle = part.tint >= 1 ? color : mixToward(color, 1 - (part.tint || 1));
        ctx2.fillRect(px(part.ox - part.r), py(part.lift + part.h),
          Math.max(1.5, part.r * 2 * k), Math.max(1.5, part.h * k));
        return;
      }
      // 回転体・切り抜き板は正面から見た輪郭で（2026-09-29）
      if ((part.kind === "lathe" || part.kind === "flat") && part.spec && !(part.kind === "flat" && (part.spec.plane || part.spec.roll || part.spec.tilt))) {
        const spec = part.spec;
        ctx2.fillStyle = part.tint >= 1 ? color : mixToward(color, 1 - (part.tint || 1));
        ctx2.beginPath();
        if (part.kind === "lathe" && spec.axis === "z") {
          // 奥行き方向の軸（ローラー）は正面から丸に見える
          ctx2.arc(px(part.ox), py(part.lift + part.h / 2), Math.max(1.5, (part.h / 2) * k), 0, Math.PI * 2);
        } else if (part.kind === "lathe" && spec.axis === "x") {
          ctx2.rect(px(part.ox - part.w / 2), py(part.lift + part.h), Math.max(1.5, part.w * k), Math.max(1.5, part.h * k));
        } else if (part.kind === "lathe") {
          const tangents = roundProfileTangents(spec.profile);
          const t0 = spec.profile[0][0], total = spec.profile[spec.profile.length - 1][0] - t0;
          const n = 24;
          const side = (sign) => Array.from({ length: n + 1 }, (_, i) => {
            const t = t0 + (total * i) / n;
            const dia = i === 0 ? spec.profile[0][1] : i === n ? spec.profile[spec.profile.length - 1][1] : sampleRoundProfile(spec.profile, tangents, t)[0];
            return [(spec.x || 0) + sign * dia / 2, (spec.y || 0) + t];
          });
          side(1).concat(side(-1).reverse()).forEach(([x, y], i) => (i ? ctx2.lineTo(px(x), py(y)) : ctx2.moveTo(px(x), py(y))));
        } else {
          spec.pts.forEach(([x, y], i) => (i ? ctx2.lineTo(px((spec.x || 0) + x), py((spec.y || 0) + y)) : ctx2.moveTo(px((spec.x || 0) + x), py((spec.y || 0) + y))));
        }
        ctx2.closePath();
        ctx2.fill();
        return;
      }
      ctx2.fillStyle = part.tint >= 1 ? color : mixToward(color, 1 - (part.tint || 1));
      ctx2.fillRect(px(part.ox - part.w / 2), py(part.lift + part.h),
        Math.max(1.5, part.w * k), Math.max(1.5, part.h * k));
    });
    ctx2.restore();
  }

  function drawPosePreview(canvas, poseId, color, previewYaw = null) {
    const ctx = canvas.getContext("2d");
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    /* 見る角度は姿勢で変える。斜め前から見ると前後と左右の両方が読めるが、
     * 宙返りや寝姿のように「横から見る形」は、斜めから見ると
     * 手前と奥が重なって塊にしか見えない。そういう姿勢は真横から見せる。 */
    const pose = poseById(poseId);
    const yaw = Number.isFinite(previewYaw) ? previewYaw
      : pose && pose.sideView ? Math.PI * 0.5 : Math.PI * 0.24;

    // まず等倍で組んで、外に出る範囲を測る
    const probe = buildRig(poseId, 0, 0, 1, 1, yaw, 0, null);
    let x0 = Infinity; let x1 = -Infinity; let y0 = Infinity; let y1 = -Infinity;
    const scan = (q) => {
      x0 = Math.min(x0, q.x); x1 = Math.max(x1, q.x);
      y0 = Math.min(y0, q.y); y1 = Math.max(y1, q.y);
    };
    Object.keys(probe.P).forEach((k) => scan(probe.P[k]));
    // 胴は断面の中心から左右へ張り出すので、その分も入れて測る
    probe.rings.forEach((ring) => {
      const r = Math.hypot(ring.wx, ring.wy) + Math.hypot(ring.dx, ring.dy);
      scan({ x: ring.o.x - r, y: ring.o.y - r });
      scan({ x: ring.o.x + r, y: ring.o.y + r });
    });

    const pad = 14;
    const bw = Math.max(0.001, x1 - x0);
    const bh = Math.max(0.001, y1 - y0);
    const s = Math.min((w - pad * 2) / bw, (h - pad * 2) / bh);
    const ox = pad - x0 * s + ((w - pad * 2) - bw * s) / 2;
    const oy = pad - y0 * s + ((h - pad * 2) - bh * s) / 2;
    paintBody(ctx, buildRig(poseId, ox, oy, s, s, yaw, 0, null), color, null);
  }
  if (openArgs.has("feature-test")) {
    window.SHOSAI_STAGE_POSE_PREVIEW_TEST = Object.freeze({ draw: drawPosePreview });
  }

  // ディアボロは専用の向き・持たせる操作を保つため type は変えない。
  // 演者・舞台セットでは、小道具と同じ入口・一覧へ分類する。
  /* 2026-09-23 本人指示: スーツケースは大道具でなく小道具として扱う（分類のみ）。
   * 同日追記: 追加候補としては削除。ROSTER_PROP_KINDSには残し、既存に置いた駒は
   * 引き続き小道具として数える。新規に選べる入口（ROSTER_PROP_SPECIAL_KINDS）だけ外す。 */
  const ROSTER_PROP_KINDS = new Set(["prop", "diabolo", "suitcase"]);
const ROSTER_PROP_SPECIAL_KINDS = Object.freeze([
  { group: "サーカス道具", kind: "diabolo" },
]);
  /* R-1（2026-09-17 本人決定）: 盆・可動デッキ・幕・せり・水面は「大道具」ではなく舞台機構で、
   * 劇場に組み込まれているもの。だから足す場所も劇場設定モードの舞台機構パネル
   * （`[data-panel="machinery"]`）ひとつに寄せる。
   * R-2（同）: 「組んだセット」(model) も、ここから新規に足せないようにする。
   *   本人が求めているのは「組んだ配置に名前をつけて登録し、あとで呼び出す」仕組みで、
   *   それは別パネル（`[data-panel="rigs"]`＝セット登録）に既にある。
   *   一覧に「組んだセット」という種類が並んでいるのが紛らわしい、というのが元の指摘。
   * ★どちらも **kind の定義自体は消さない**。消すと既存ショーの駒が未知の型として
   *   演者に落ちる（`PIECE_TYPES` 付近の警告コメント参照）。閉じるのは追加の入口だけ。 */
  const ROSTER_MACHINERY_KINDS = new Set(["seri", "revolve", "deck", "curtain", "pool"]);
  const ROSTER_CLOSED_KINDS = new Set(["model"]);
  const ROSTER_KIND_LAYERS = Object.freeze({
    performer: Object.freeze(["performer"]),
    set: Object.freeze(SET_KIND_ORDER.filter((kind) => !ROSTER_PROP_KINDS.has(kind)
      && !ROSTER_MACHINERY_KINDS.has(kind) && !ROSTER_CLOSED_KINDS.has(kind))),
    prop: Object.freeze(["prop", "diabolo"]),
  });
  /* 「種類」に平積みしていた既定の大道具も、形で足す大道具と同じ見出しへ寄せる。
   * 既存の kind や保存形式には手を入れず、選ぶ入口だけを整理する。 */
  /* 2026-09-23 本人指示: 「台・家具」はPROP_SHAPE_GROUPSの「家具」(ソファ等)と
     見出し名を揃えて一枠へ合流させる。スーツケースは小道具側（ROSTER_PROP_SPECIAL_KINDS）
     へ移したのでここからは外す。 */
  const ROSTER_SET_KIND_GROUPS = Object.freeze([
    { ja: "家具", ids: ["block", "table", "chair", "bench", "stool"] },
    { ja: "建て込み", ids: ["wall"] },
    /* ★2026-09-23 本人指示: 「乗り物」の中身は乗り物だけ（球は外し、その他の大道具へ）。 */
    { ja: "乗り物", ids: ["car"] },
    /* 吊り点（rigpoint）: v0.2.34 で読み込みと描画を先に出し、2026-10-03 に追加の窓へ出した（D3と同じ順番。
       v0.2.33 以前は知らない駒の型を演者として読むため、読める版が行き渡るのを待った）。 */
    { ja: "空中・サーカス", ids: ["trapeze", "cyrwheel", "pole", "teeter", "tissue", "rigpoint", "wire", "trampoline", "cane"] },
  ]);
  let rosterKind = "performer";
  let rosterKindLayer = "performer";
  let rosterPose = "stand";
  let rosterPropShape = "box";
  let rosterColorTouched = false;

  function rosterDefaultColor() {
    return rosterKindLayer === "performer"
      ? nextPieceColor(state.project.cast.length)
      : defaultSetColor(rosterKind, rosterPropShape);
  }

  function syncRosterColorDefault() {
    if (els.rosterColor && !rosterColorTouched) els.rosterColor.value = rosterDefaultColor();
  }

  function rosterSelectedColor() {
    return validColor(els.rosterColor && els.rosterColor.value, rosterDefaultColor());
  }

  function rosterSearchKey(value) {
    return String(value || "").normalize("NFKC").toLocaleLowerCase();
  }

  function applyRosterSearch() {
    const words = rosterSearchKey(els.rosterSearch && els.rosterSearch.value)
      .trim().split(/\s+/).filter(Boolean);
    const host = rosterKindLayer === "performer" ? els.rosterPoseGrid
      : rosterKindLayer === "set" ? els.kindGrid : els.rosterPropGrid;
    if (!host) return;
    host.querySelectorAll("[data-roster-search]").forEach((tile) => {
      const haystack = rosterSearchKey(tile.dataset.rosterSearch);
      tile.hidden = !words.every((word) => haystack.includes(word));
    });
    // 空になった分類の見出しを隠す（姿勢も分類分けした＝D2・2026-09-26）
    host.querySelectorAll(".stage-prop-choice-group").forEach((section) => {
      section.hidden = !section.querySelector("[data-roster-search]:not([hidden])");
    });
    if (rosterKindLayer === "set" && els.modelPicker) {
      const modelTile = host.querySelector('[data-roster-kind-choice="model"]');
      els.modelPicker.hidden = rosterKind !== "model" || Boolean(modelTile && modelTile.hidden);
    }
  }

  function propShapeGroups(selected) {
    const grouped = new Set(PROP_SHAPE_GROUPS.flatMap((group) => group.ids));
    const rest = PROP_SHAPE_ORDER.filter((key) => !grouped.has(key));
    return PROP_SHAPE_GROUPS.concat(rest.length ? [{ ja: "その他の形", ids: rest }] : [])
      .map((group) => ({
        ...group,
        ids: group.ids.filter((key) => PROP_SHAPES[key]
          && (key !== "rigging_point_mark" || selected === key)
          && (RELEASE_FEATURES.propMask || key !== "mask" || selected === "mask")),
      }))
      .filter((group) => group.ids.length);
  }

  function renderPropShapeSelect(select, value) {
    if (!select) return;
    const selected = PROP_SHAPES[value] ? value : "box";
    select.innerHTML = "";
    propShapeGroups(selected).forEach((group) => {
      const optgroup = document.createElement("optgroup");
      optgroup.label = tx(group.ja);
      group.ids.forEach((key) => {
        const option = document.createElement("option");
        option.value = key;
        option.textContent = propShapeName(key);
        optgroup.append(option);
      });
      select.append(optgroup);
    });
    select.value = selected;
  }

  /* 道具の正面・側面を一覧で取り違えないためのゆっくりした一周。hover / focus /
   * 選択中だけ動かし、OS の「視差効果を減らす」指定では静止画のままにする。 */
  function bindKindPreviewSpin(tile, canvas, draw, options = {}) {
    if (!tile || !canvas || typeof draw !== "function") return;
    const turnMs = 9000;
    const turntable = options.turntable === true;
    let hovered = false;
    let frame = 0;
    let startedAt = 0;
    const reducedMotion = () => window.matchMedia
      && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const modalIsVisible = () => !els.kindModal || !els.kindModal.hidden;
    const shouldSpin = () => modalIsVisible() && !reducedMotion() && (hovered
      || document.activeElement === tile || tile.classList.contains("is-on"));
    const reset = () => {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      canvas.style.transform = "";
      if (turntable) draw(0);
    };
    const tick = (now) => {
      if (!tile.isConnected || !shouldSpin()) { reset(); return; }
      if (!startedAt) startedAt = now;
      const turntableFacing = ((now - startedAt) / turnMs) * 360;
      if (turntable) draw(turntableFacing);
      else canvas.style.transform = `rotate(${turntableFacing}deg)`;
      frame = requestAnimationFrame(tick);
    };
    const sync = () => {
      if (!shouldSpin()) { startedAt = 0; reset(); return; }
      if (!frame) frame = requestAnimationFrame(tick);
    };
    draw(0);
    tile.addEventListener("pointerenter", () => { hovered = true; sync(); });
    tile.addEventListener("pointerleave", () => { hovered = false; sync(); });
    tile.addEventListener("focus", sync);
    tile.addEventListener("blur", () => requestAnimationFrame(sync));
    tile.addEventListener("stage-kind-preview-selection", sync);
    sync();
  }

  function renderRosterPropChoices() {
    const host = els.rosterPropGrid;
    if (!host) return;
    host.innerHTML = "";
    propShapeGroups(rosterPropShape).map((group) => ({
      ...group,
      ids: group.ids.filter((shapeId) => rosterShapeIsAvailable(shapeId) && !ROSTER_SET_PROP_SHAPES.has(shapeId)),
    })).filter((group) => group.ids.length).forEach((group) => {
      const section = document.createElement("section");
      section.className = "stage-prop-choice-group";
      const heading = document.createElement("p");
      heading.className = "stage-kind-field-title";
      heading.textContent = tx(group.ja);
      const grid = document.createElement("div");
      grid.className = "stage-pose-grid stage-prop-choice-grid";
      group.ids.forEach((shapeId) => {
        const tile = document.createElement("button");
        tile.type = "button";
        tile.className = `stage-pose-tile${shapeId === rosterPropShape ? " is-on" : ""}`;
        tile.dataset.rosterPropShape = shapeId;
        tile.setAttribute("aria-pressed", String(shapeId === rosterPropShape));
        const canvas = document.createElement("canvas");
        canvas.width = 132;
        canvas.height = 132;
        const label = document.createElement("span");
        label.textContent = propShapeName(shapeId);
        tile.dataset.rosterSearch = `${label.textContent} ${shapeId} ${tx(group.ja)}`;
        tile.append(canvas, label);
        tile.addEventListener("click", () => {
          rosterKind = "prop";
          rosterPropShape = shapeId;
          syncRosterColorDefault();
          setRosterTileSelection(host, "[data-roster-prop-shape], [data-roster-prop-kind]", tile);
        });
        tile.addEventListener("dblclick", (event) => {
          event.preventDefault();
          rosterKind = "prop";
          rosterPropShape = shapeId;
          syncRosterColorDefault();
          setRosterTileSelection(host, "[data-roster-prop-shape], [data-roster-prop-kind]", tile);
          addFromRoster();
        });
        grid.append(tile);
        /* 選んで追加した直後に正面図へ出る色で見せる。形だけでなく、
           一覧と正面図の見え方を同じものにする。 */
        bindKindPreviewSpin(tile, canvas,
          (facing) => drawKindPreview(canvas, "prop", rosterSelectedColor(), shapeId, facing), { turntable: true });
      });
      ROSTER_PROP_SPECIAL_KINDS.filter((choice) => choice.group === group.ja).forEach((choice) => {
        const tile = document.createElement("button");
        tile.type = "button";
        tile.className = `stage-pose-tile${choice.kind === rosterKind ? " is-on" : ""}`;
        tile.dataset.rosterPropKind = choice.kind;
        tile.setAttribute("aria-pressed", String(choice.kind === rosterKind));
        const canvas = document.createElement("canvas");
        canvas.width = 132;
        canvas.height = 132;
        const label = document.createElement("span");
        label.textContent = setKindName(choice.kind);
        tile.dataset.rosterSearch = `${label.textContent} ${choice.kind} ${tx(group.ja)}`;
        tile.append(canvas, label);
        const choose = () => {
          rosterKind = choice.kind;
          syncRosterColorDefault();
          setRosterTileSelection(host, "[data-roster-prop-shape], [data-roster-prop-kind]", tile);
        };
        tile.addEventListener("click", choose);
        tile.addEventListener("dblclick", (event) => {
          event.preventDefault();
          choose();
          addFromRoster();
        });
        grid.append(tile);
        bindKindPreviewSpin(tile, canvas,
          (facing) => drawKindPreview(canvas, choice.kind, rosterSelectedColor(), null, facing), { turntable: true });
      });
      section.append(heading, grid);
      host.append(section);
    });
  }

  function refreshRosterPropPreviews() {
    const host = els.rosterPropGrid;
    if (!host || rosterKindLayer !== "prop") return;
    const color = rosterSelectedColor();
    host.querySelectorAll("[data-roster-prop-shape]").forEach((tile) => {
      const canvas = tile.querySelector("canvas");
      if (canvas) drawKindPreview(canvas, "prop", color, tile.dataset.rosterPropShape);
    });
    host.querySelectorAll("[data-roster-prop-kind]").forEach((tile) => {
      const canvas = tile.querySelector("canvas");
      if (canvas) drawKindPreview(canvas, tile.dataset.rosterPropKind, color);
    });
  }

  function setRosterTileSelection(host, selector, selected) {
    host.querySelectorAll(selector).forEach((tile) => {
      const isSelected = tile === selected;
      tile.classList.toggle("is-on", isSelected);
      tile.setAttribute("aria-pressed", String(isSelected));
      tile.dispatchEvent(new Event("stage-kind-preview-selection"));
    });
  }

  function renderModelPicker() {
    if (!els.modelPicker) return;
    const before = els.modelPicker.value;
    const models = stageModelLibrary().models;
    els.modelPicker.innerHTML = "";
    models.forEach((model) => {
      const option = document.createElement("option");
      option.value = model.id;
      option.textContent = model.name;
      els.modelPicker.append(option);
    });
    els.modelPicker.hidden = rosterKind !== "model";
    if (models.some((model) => model.id === before)) els.modelPicker.value = before;
    if (!models.length) {
      const option = document.createElement("option");
      option.value = "";
      option.textContent = tx("先にセットを組んでください");
      els.modelPicker.append(option);
    }
  }

  function renderRosterPoseChoices() {
    const grid = els.rosterPoseGrid;
    if (!grid) return;
    grid.innerHTML = "";
    /* R-19: 名簿から足すときはまだ何も持っていないので、物を伴う姿勢は出さない。
       D2（2026-09-26）: 姿勢の窓と同じ分類で見出しを付ける。検索は既存の欄（applyRosterSearch）が効く。 */
    groupedPoses(selectablePoses([])).forEach((group) => {
    const section = document.createElement("section");
    section.className = "stage-prop-choice-group";
    const heading = document.createElement("p");
    heading.className = "stage-kind-field-title";
    heading.textContent = tx(group.ja);
    const tiles = document.createElement("div");
    tiles.className = "stage-pose-grid stage-prop-choice-grid";
    section.append(heading, tiles);
    grid.append(section);
    group.poses.forEach((pose) => {
      const tile = document.createElement("button");
      tile.type = "button";
      tile.className = `stage-pose-tile${pose.id === rosterPose ? " is-on" : ""}`;
      tile.dataset.rosterPose = pose.id;
      tile.setAttribute("aria-pressed", String(pose.id === rosterPose));
      const canvas = document.createElement("canvas");
      canvas.width = 132;
      canvas.height = 148;
      const label = document.createElement("span");
      label.textContent = poseName(pose);
      tile.dataset.rosterSearch = poseSearchText(pose, group.ja);
      tile.append(canvas, label);
      tile.addEventListener("click", () => {
        rosterPose = pose.id;
        setRosterTileSelection(grid, "[data-roster-pose]", tile);
      });
      tile.addEventListener("dblclick", (event) => {
        event.preventDefault();
        rosterPose = pose.id;
        setRosterTileSelection(grid, "[data-roster-pose]", tile);
        addFromRoster();
      });
      tiles.append(tile);
      drawPosePreview(canvas, pose.id, nextPieceColor(state.project.cast.length));
    });
    });
  }

  function renderRosterSetChoices() {
    const grid = els.kindGrid;
    if (!grid) return;
    grid.innerHTML = "";
    const appendKindTile = (host, kind, groupName) => {
      const tile = document.createElement("button");
      tile.type = "button";
      tile.className = `stage-pose-tile${kind === rosterKind ? " is-on" : ""}`;
      tile.dataset.rosterKindChoice = kind;
      tile.setAttribute("aria-pressed", String(kind === rosterKind));
      const canvas = document.createElement("canvas");
      canvas.width = 132;
      canvas.height = 132;
      const label = document.createElement("span");
      label.textContent = setKindName(kind);
      const modelNames = kind === "model" ? stageModelLibrary().models.map((model) => model.name).join(" ") : "";
      tile.dataset.rosterSearch = `${label.textContent} ${kind} ${modelNames} ${tx(groupName)}`;
      tile.append(canvas, label);
      tile.addEventListener("click", () => {
        rosterKind = kind;
        syncRosterColorDefault();
        renderModelPicker();
        setRosterTileSelection(grid, "[data-roster-kind-choice]", tile);
      });
      tile.addEventListener("dblclick", (event) => {
        event.preventDefault();
        rosterKind = kind;
        syncRosterColorDefault();
        renderModelPicker();
        setRosterTileSelection(grid, "[data-roster-kind-choice]", tile);
        addFromRoster();
      });
      host.append(tile);
      bindKindPreviewSpin(tile, canvas,
        (facing) => drawKindPreview(canvas, kind, "#8b98a1", null, facing), { turntable: true });
    };
    const ungroupedKinds = new Set(ROSTER_KIND_LAYERS.set);
    /* 大道具では「空中・サーカス」と「サーカス道具」を一つの分類として
       見せる。保存される kind / propShape や、小道具側の分類は変えず、
       追加パネル内の表示だけをまとめる。 */
    const setGroupSections = new Map();
    ROSTER_SET_KIND_GROUPS.forEach((group) => {
      const ids = group.ids.filter((kind) => ungroupedKinds.delete(kind));
      if (!ids.length) return;
      const section = document.createElement("section");
      section.className = "stage-prop-choice-group stage-kind-prop-group";
      const heading = document.createElement("p");
      heading.className = "stage-kind-field-title";
      heading.textContent = tx(group.ja);
      const choices = document.createElement("div");
      choices.className = "stage-pose-grid stage-prop-choice-grid";
      ids.forEach((kind) => appendKindTile(choices, kind, group.ja));
      section.append(heading, choices);
      grid.append(section);
      setGroupSections.set(group.ja, { section, choices });
    });
    // 新しい既定 kind を追加して分類を忘れても、選べなくならないよう最後に受ける。
    if (ungroupedKinds.size) {
      const section = document.createElement("section");
      section.className = "stage-prop-choice-group stage-kind-prop-group";
      const heading = document.createElement("p");
      heading.className = "stage-kind-field-title";
      heading.textContent = tx("その他の大道具");
      const choices = document.createElement("div");
      choices.className = "stage-pose-grid stage-prop-choice-grid";
      [...ungroupedKinds].forEach((kind) => appendKindTile(choices, kind, "その他の大道具"));
      section.append(heading, choices);
      grid.append(section);
    }
    propShapeGroups(rosterPropShape).map((group) => ({
      ...group,
      ids: group.ids.filter((shapeId) => rosterShapeIsAvailable(shapeId) && ROSTER_SET_PROP_SHAPES.has(shapeId)),
    })).filter((group) => group.ids.length).forEach((group) => {
      const displayGroupName = group.ja === "サーカス道具" ? "空中・サーカス" : group.ja;
      let groupSection = setGroupSections.get(displayGroupName);
      if (!groupSection) {
        const section = document.createElement("section");
        section.className = "stage-prop-choice-group stage-kind-prop-group";
        const heading = document.createElement("p");
        heading.className = "stage-kind-field-title";
        heading.textContent = tx(displayGroupName);
        const choices = document.createElement("div");
        choices.className = "stage-pose-grid stage-prop-choice-grid";
        section.append(heading, choices);
        grid.append(section);
        groupSection = { section, choices };
        setGroupSections.set(displayGroupName, groupSection);
      }
      group.ids.forEach((shapeId) => {
        const tile = document.createElement("button");
        tile.type = "button";
        tile.className = `stage-pose-tile${rosterKind === "prop" && shapeId === rosterPropShape ? " is-on" : ""}`;
        tile.dataset.rosterPropShape = shapeId;
        tile.setAttribute("aria-pressed", String(rosterKind === "prop" && shapeId === rosterPropShape));
        const canvas = document.createElement("canvas");
        canvas.width = 132;
        canvas.height = 132;
        const label = document.createElement("span");
        label.textContent = propShapeName(shapeId);
        tile.dataset.rosterSearch = `${label.textContent} ${shapeId} ${tx(group.ja)}`;
        tile.append(canvas, label);
        const choose = () => {
          rosterKind = "prop";
          rosterPropShape = shapeId;
          syncRosterColorDefault();
          renderModelPicker();
          setRosterTileSelection(grid, "[data-roster-kind-choice], [data-roster-prop-shape]", tile);
        };
        tile.addEventListener("click", choose);
        tile.addEventListener("dblclick", (event) => {
          event.preventDefault();
          choose();
          addFromRoster();
        });
        groupSection.choices.append(tile);
        bindKindPreviewSpin(tile, canvas,
          (facing) => drawKindPreview(canvas, "prop", "#8b98a1", shapeId, facing), { turntable: true });
      });
    });
  }

  function renderRosterKindLayer() {
    if (els.kindTitle) {
      const labels = { performer: "演者", set: "大道具", prop: "小道具" };
      els.kindTitle.textContent = tx(labels[rosterKindLayer] || "種類を選ぶ");
    }
    if (els.kindPerformerFields) els.kindPerformerFields.hidden = rosterKindLayer !== "performer";
    if (els.kindSetFields) els.kindSetFields.hidden = rosterKindLayer !== "set";
    if (els.kindPropFields) els.kindPropFields.hidden = rosterKindLayer !== "prop";
    if (els.kindModelOpen) els.kindModelOpen.hidden = rosterKindLayer !== "set";
    if (rosterKindLayer === "performer") renderRosterPoseChoices();
    if (rosterKindLayer === "set") renderRosterSetChoices();
    if (rosterKindLayer === "prop") renderRosterPropChoices();
    renderModelPicker();
    applyRosterSearch();
  }

  function openKindModal(layer) {
    if (!els.kindModal || !ROSTER_KIND_LAYERS[layer]) return;
    rosterKindLayer = layer;
    if (layer === "performer") {
      rosterKind = "performer";
      rosterPose = "stand";
    } else if (layer === "prop") {
      rosterKind = "prop";
    } else if (!ROSTER_KIND_LAYERS.set.includes(rosterKind)) {
      rosterKind = ROSTER_KIND_LAYERS.set[0];
    }
    rosterColorTouched = false;
    syncRosterColorDefault();
    if (els.rosterSearch) els.rosterSearch.value = "";
    renderRosterKindLayer();
    els.kindModal.hidden = false;
    els.kindBackdrop.hidden = false;
    els.kindModal.querySelectorAll("[data-roster-kind-choice], [data-roster-prop-shape], [data-roster-prop-kind]")
      .forEach((tile) => tile.dispatchEvent(new Event("stage-kind-preview-selection")));
    if (els.rosterName) {
      updateDuplicateCastNotice(els.rosterName, null, rosterKind === "performer");
      els.rosterName.focus();
    }
  }

  function closeKindModal() {
    if (!els.kindModal) return;
    els.kindModal.hidden = true;
    els.kindBackdrop.hidden = true;
  }

  function openPoseModal(options) {
    // クリックの受け手としても呼ばれるので、引数はイベントのこともある
    const focusSearch = Boolean(options && options.focusSearch === true);
    const performers = selectedPerformerPieces();
    const piece = selectedPiece();
    if (!piece || !performers.length || performers.some((item) => poseLockedByMount(item)) || !els.poseModal) return;
    const grid = els.poseGrid;
    grid.innerHTML = "";
    /* R-19: 選んでいる演者が持っている物に合う姿勢だけを出す。
       D2（2026-09-26）: 分類ごとに見出しを付けて並べる（小道具の窓と同じ部品）。 */
    groupedPoses(selectablePoses(performers)).forEach((group) => {
      const section = document.createElement("section");
      section.className = "stage-prop-choice-group";
      const heading = document.createElement("p");
      heading.className = "stage-kind-field-title";
      heading.textContent = tx(group.ja);
      const tiles = document.createElement("div");
      tiles.className = "stage-pose-grid stage-prop-choice-grid";
      section.append(heading, tiles);
      grid.append(section);
      group.poses.forEach((pose) => {
      const shared = performers.every((item) => poseTileIsOn(item, pose));
      const tile = document.createElement("button");
      tile.type = "button";
      tile.className = `stage-pose-tile${shared ? " is-on" : ""}`;
      tile.setAttribute("aria-pressed", String(shared));
      const canvas = document.createElement("canvas");
      canvas.width = 132;
      canvas.height = 148;
      const label = document.createElement("span");
      label.textContent = poseName(pose);
      tile.dataset.poseSearch = poseSearchText(pose, group.ja);
      tile.append(canvas, label);
      tiles.append(tile);
      drawPosePreview(canvas, pose.id, piece.color);
      tile.addEventListener("click", () => {
        applyPoseToSelection(pose);
        closePoseModal();
      });
      });
    });
    if (els.poseSearch) {
      els.poseSearch.value = "";
      els.poseSearch.placeholder = tx("姿勢の名前・分類");
    }
    if (els.poseSearchEmpty) els.poseSearchEmpty.textContent = tx("当てはまる姿勢がありません。");
    applyPoseSearch();
    els.poseModal.hidden = false;
    els.poseBackdrop.hidden = false;
    if (focusSearch && els.poseSearch) els.poseSearch.focus();
  }

  function applyPoseSearch() {
    if (!els.poseGrid) return;
    const words = rosterSearchKey(els.poseSearch && els.poseSearch.value).trim().split(/\s+/).filter(Boolean);
    els.poseGrid.querySelectorAll("[data-pose-search]").forEach((tile) => {
      const haystack = rosterSearchKey(tile.dataset.poseSearch);
      tile.hidden = !words.every((word) => haystack.includes(word));
    });
    els.poseGrid.querySelectorAll(".stage-prop-choice-group").forEach((section) => {
      section.hidden = !section.querySelector("[data-pose-search]:not([hidden])");
    });
    if (els.poseSearchEmpty) {
      els.poseSearchEmpty.hidden = Boolean(els.poseGrid.querySelector("[data-pose-search]:not([hidden])"));
    }
  }

  function closePoseModal() {
    if (els.poseModal) els.poseModal.hidden = true;
    if (els.poseBackdrop) els.poseBackdrop.hidden = true;
  }

  /* ---------- 舞台機構 ---------- */

  const curtainKindName = (kind) => tm("curtainKind", kind, ({
    front: "前幕・引き割り", traveler: "中割り幕", drop: "振り落とし・上下する幕",
    leg: "袖幕", cyc: "ホリゾント幕", scrim: "紗幕",
  })[kind] || kind);

  function machineryDefaults(kind, curtainKind) {
    if (kind === "revolve") return { spin: 0 };
    if (kind === "deck") return { tilt: 0, deckH: 0 };
    /* ★透けは紗幕だけが持つ。他の幕にも付けると、効かない値が全ショーの保存データへ増える。 */
    if (kind === "curtain") return curtainKind === "scrim"
      ? { curtainKind, open: 0, sheer: 0 }
      : { curtainKind, open: 0 };
    if (kind === "pool") return { water: .9, poolH: -3 };
    if (kind === "seri") return { seriH: 0 };
    return {};
  }

  function addMachinery(kind) {
    if (kind !== "seri" || !editionAllows("machinery")) return; // Other machinery remains retired.

    if (!["revolve", "deck", "curtain", "pool", "seri"].includes(kind)) return;
    if (!canAddSets() || !canAddScenePieces(sc())) return;
    checkpoint();
    const curtainKind = kind === "curtain" && els.machineryCurtainKind
      ? els.machineryCurtainKind.value : "front";
    const name = kind === "curtain" ? curtainKindName(curtainKind) : setKindName(kind);
    const dims = normalizeDims(kind, { size: 100, ...(kind === "seri" ? { dims: { w: 2, d: 2 } } : {}) });
    // 幕の既定幅は、いま選んでいる劇場の間口いっぱい。
    if (kind === "curtain" && dims) dims.w = venueSize().width;
    const item = {
      id: rid("set"), kind, name, color: kind === "pool" ? "#477f92" : kind === "curtain" ? "#784047" : "#8b98a1",
      modelId: null, dims, note: "", locked: false, flown: false, wires: 2, framed: false,
      curtainKind: kind === "curtain" ? curtainKind : undefined, lightKind: "hang",
    };
    state.project.sets.push(item);
    const piece = normalizePiece({
      id: nextId(), type: kind, setId: item.id, u: .5, v: .5, size: 100,
      color: item.color, facing: 0, ...machineryDefaults(kind, curtainKind),
    }, 0);
    sc().pieces.push(piece);
    selectedId = piece.id;
    renderSets(); renderScenes(); updateInspector(); render(); persistSoon();
    announce(`${name}を舞台へ置きました。`);
  }

  document.querySelectorAll("[data-machinery-kind]").forEach((button) => {
    button.addEventListener("click", () => addMachinery(button.dataset.machineryKind));
  });

  /* ---------- 前紗幕（本人決定 2026-10-09） ----------
     劇場設定と舞台タブの「舞台機構」から、紗幕を舞台の一番手前（v .94）へ
     透け30%で置く（せりも追加できる。盆・デッキ・水面の新規追加は引退のまま）。
     ★登録（sets）は名前「前紗幕」の紗幕を再利用し、同じシーンに前寄り（v≥.85）の紗幕があれば足さずに選ぶ
       （同じ操作で重複追加しない・2026-09-28 本人方針）。
     ★置いたあとの出し入れは舞台タブ左列「舞台機構」一覧の ON/OFF（toggleSetOnStage）。OFF で控え（stash）に
       位置と透けが残るので、ON で同じ手前の位置へ戻る。
     ★保存形式は増やさない（既存の curtainKind・sheer だけ）。置いたら舞台タブへ戻して結果を見せる。 */
  const FRONT_SCRIM_V = .94;
  const FRONT_SCRIM_SHEER = 30;
  const frontScrimName = () => tx("前紗幕");

  function isFrontScrimPiece(piece) {
    if (!piece || piece.type !== "curtain") return false;
    const owner = pieceSet(piece);
    const kind = piece.curtainKind || (owner && owner.curtainKind) || "front";
    return kind === "scrim" && finite(piece.v, 0) >= .85;
  }

  function frontScrimSet() {
    const names = new Set(["前紗幕", frontScrimName()]);
    return (state.project.sets || []).find((item) =>
      item && item.kind === "curtain" && item.curtainKind === "scrim" && names.has(item.name)) || null;
  }

  function addFrontScrim() {
    const scene = sc();
    const existing = (scene.pieces || []).find(isFrontScrimPiece);
    if (existing) {
      selectedId = existing.id;
      updateInspector(); render();
      announce(`${frontScrimName()}を選びました。`);
      returnToStageAfterFrontScrim();
      return existing;
    }
    if (!canAddScenePieces(scene)) return null;
    let item = frontScrimSet();
    if (!item && !canAddSets()) return null;
    checkpoint();
    if (!item) {
      const dims = normalizeDims("curtain", { size: 100 });
      if (dims) dims.w = venueSize().width;   // 幕の既定幅は間口いっぱい（addMachinery と同じ）
      item = {
        id: rid("set"), kind: "curtain", name: frontScrimName(), color: "#784047",
        modelId: null, dims, note: "", locked: false, flown: false, wires: 2, framed: false,
        curtainKind: "scrim", lightKind: "hang",
      };
      state.project.sets.push(item);
    }
    const piece = normalizePiece({
      id: nextId(), type: "curtain", setId: item.id, u: .5, v: FRONT_SCRIM_V, size: 100,
      color: item.color, facing: 0, curtainKind: "scrim", open: 0, sheer: FRONT_SCRIM_SHEER,
    }, 0);
    scene.pieces.push(piece);
    selectedId = piece.id;
    renderSets(); renderScenes(); updateInspector(); render(); persistSoon();
    announce(`${frontScrimName()}を舞台へ置きました。`);
    returnToStageAfterFrontScrim();
    return piece;
  }

  // 劇場設定モードで押したときは舞台タブへ戻して、置いた紗幕をそのまま見せる（初回の劇場設定ゲート中は戻らない）
  function returnToStageAfterFrontScrim() {
    if (document.body.dataset.gammaWorkspace !== "venue-setup") return;
    if (state.project && state.project.venueSetupPending) return;
    window.GAMMA_WORKSPACE?.normal?.();
  }

  document.querySelectorAll("[data-machinery-quick=\"front-scrim\"]").forEach((button) => {
    button.addEventListener("click", () => addFrontScrim());
  });

  /* ---------- セット登録（画面の名前。コード上は rig） ----------
     舞台装置の並びに名前をつけて残し、別のシーンで呼び出す。
     残すのは演者以外。演者はシーンごとに出入りするものなので、装置と一緒に
     持ち回すと「前のシーンの人がそのまま立っている」ことになる。 */

  const isRigPiece = (piece) => piece.type !== "performer";

  // 型に入れる／型から出すときの写し。id は必ず作り直す（同じシーンに二重で置けるように）
  function copyPiece(piece) {
    const clone = JSON.parse(JSON.stringify(piece));
    clone.id = nextId();
    clone.base = 0;
    clone.supportId = null;
    clone.heldBy = null;
    if (clone.type === "performer") { clone.mountOn = null; delete clone.mountWith; }
    return clone;
  }

  function renderRigs() { return preserveStagePanelScroll(renderRigsContent); }
  function renderRigsContent() {
    if (!els.rigList) return;
    const rigs = state.project.rigs || [];
    els.rigList.innerHTML = "";
    if (!rigs.length) {
      const empty = document.createElement("p");
      empty.className = "stage-cast-empty";
      /* 小道具を登録しに来て、この欄で迷った実例がある（2026-08-20）。
         ここは「組んだ立体」を残す欄で、一つずつの登録は「演者・舞台セット」の仕事。
         その分かれ道を、空のときだけ一行で示す。 */
      empty.textContent = tx("まだ残していません。並べ終えたら名前をつけて残してください。小道具や家具を一つずつ登録するのは、大道具・小道具の欄からです。");
      els.rigList.append(empty);
      return;
    }
    rigs.forEach((rig) => {
      const row = document.createElement("div");
      row.className = "stage-set-row";

      const head = document.createElement("div");
      head.className = "stage-set-head stage-rig-head";
      const name = document.createElement("input");
      name.type = "text";
      name.className = "stage-cast-name-input";
      name.value = rig.name;
      name.maxLength = 24;
      name.autocomplete = "off";
      name.setAttribute("data-1p-ignore", "true");
      name.setAttribute("aria-label", tx("大道具の並びの名前"));
      name.addEventListener("input", () => {
        rig.name = name.value.slice(0, 24);
        persistSoon();
      });
      head.append(name);

      const foot = document.createElement("div");
      foot.className = "stage-set-foot stage-rig-foot";
      const count = document.createElement("span");
      count.className = "stage-set-dims";
      count.textContent = `${rig.pieces.length}点`;

      const swap = document.createElement("button");
      swap.type = "button";
      swap.className = "stage-cast-status is-off";
      swap.textContent = "置き換え";
      swap.title = "いまのシーンの装置を、この型にそっくり入れ替えます";
      swap.addEventListener("click", () => applyRig(rig.id, "replace"));

      const plus = document.createElement("button");
      plus.type = "button";
      plus.className = "stage-cast-status is-off";
      plus.textContent = "足す";
      plus.title = "いまのシーンへ、この型の装置を足します";
      plus.addEventListener("click", () => applyRig(rig.id, "add"));

      const update = document.createElement("button");
      update.type = "button";
      update.className = "stage-cast-profile";
      update.textContent = "↺";
      update.title = "いまの並びで、この型を上書きします";
      update.setAttribute("aria-label", `${rig.name}をいまの並びで上書き`);
      update.addEventListener("click", () => overwriteRig(rig.id));

      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "stage-cast-remove";
      remove.innerHTML = squareGlyphSvg("close");
      remove.setAttribute("aria-label", `${rig.name}を消す`);
      remove.addEventListener("click", () => removeRig(rig.id));

      foot.append(count, swap, plus, update, remove);
      row.append(head, foot);
      els.rigList.append(row);
    });
  }

  function currentRigPieces() {
    return sc().pieces.filter(isRigPiece);
  }

  function saveRig() {
    if (!editionAllows("formations")) return;
    const raw = (els.rigName && els.rigName.value || "").trim();
    if (!raw) {
      announce("名前を入れてから残してください。");
      if (els.rigName) els.rigName.focus();
      return;
    }
    const pieces = currentRigPieces();
    if (!pieces.length) {
      announce("舞台に装置がありません。");
      return;
    }
    if (!hasCapacity(state.project.rigs, "rigs", 1, "大道具の並びを保存")
      || !hasCapacity(pieces, "piecesPerRig", 0, "保存した大道具の駒")) return;
    checkpoint();
    state.project.rigs.push({ id: rid("rig"), name: raw.slice(0, 24), pieces: pieces.map(copyPiece) });
    if (els.rigName) els.rigName.value = "";
    renderRigs();
    persistSoon();
    announce(`${raw}として${pieces.length}点を残しました。`);
  }

  async function overwriteRig(rigId) {
    if (!editionAllows("formations")) return;
    const rig = (state.project.rigs || []).find((r) => r.id === rigId);
    if (!rig) return;
    const pieces = currentRigPieces();
    if (!await surfaceProjectConfirm(`「${rig.name}」を、いまの並び（${pieces.length}点）で上書きしますか。`)) return;
    checkpoint();
    rig.pieces = pieces.map(copyPiece);
    renderRigs();
    persistSoon();
    announce(`${rig.name}を上書きしました。`);
  }

  function applyRig(rigId, mode) {
    if (!editionAllows("formations")) return;
    const rig = (state.project.rigs || []).find((r) => r.id === rigId);
    if (!rig) return;
    const scene = sc();
    const kept = mode === "replace" ? scene.pieces.filter((piece) => !isRigPiece(piece)) : scene.pieces;
    if (!canAddScenePieces({ pieces: kept }, rig.pieces.length)) return;
    checkpoint();
    if (mode === "replace") scene.pieces = kept;
    rig.pieces.forEach((piece) => scene.pieces.push(copyPiece(piece)));
    selectedId = null;
    renderScenes();
    updateInspector();
    render();
    persistSoon();
    announce(`${rig.name}の${rig.pieces.length}点を${mode === "replace" ? "置き換えました" : "足しました"}。`);
  }

  async function removeRig(rigId) {
    if (!editionAllows("formations")) return;
    const rig = (state.project.rigs || []).find((r) => r.id === rigId);
    if (!rig) return;
    if (!await surfaceProjectConfirm(`「${rig.name}」を消します。置いてある装置はそのままです。`)) return;
    checkpoint();
    state.project.rigs = state.project.rigs.filter((r) => r.id !== rigId);
    renderRigs();
    persistSoon();
    announce(`${rig.name}を消しました。`);
  }

  /* ---------- 舞台セットの寸法（モーダル） ---------- */

  let setInfoId = null;

  function currentSetItem() {
    return setInfoId ? (state.project.sets || []).find((t) => t.id === setInfoId) : null;
  }

  /* ---------- L-04 設定窓の回転台プレビュー（2026-09-18 本人要望） ----------
   * 「自動で回転台に乗っているようにぐるぐる回って360度みれるように。
   *   もしドラッグされたらそのオブジェクトを3Dでみることができるように」。
   * ★形は pieceParts()（本体の正本）から取る。ここが持つのは塗りと見る向きだけ。
   *   共有部品 stage-set-render.js は別セッションの作業中で本体へは読み込まれていないため、
   *   当てにしない。読み込まれたら、この塗りをそちらへ寄せられる。
   * ★大きさの見当がつくように、身長1.7mの人の影を横に置く（回さない）。
   * ★prefers-reduced-motion では自動で回さない（ドラッグでは回せる）。 */
  const SETINFO_PREVIEW = Object.freeze({
    height: 150,
    turnSeconds: 14,          // 1周にかける秒数
    tiltDeg: 18,              // 見下ろす角度の既定
    tiltMinDeg: -5,
    tiltMaxDeg: 60,
    figureM: 1.7,             // 横に置く人の背丈
    figureMinM: 0.6,          // これより小さい道具は人でなく物差しで見せる
    marginPx: 14,
  });
  let setInfoPreview = null;

  function setInfoPreviewItem() {
    return setInfoId ? (state.project.sets || []).find((t) => t.id === setInfoId) : null;
  }

  /* その登録物を「1つ置いた駒」として見たときの形。本体と同じ関数から取る。 */
  function setInfoPreviewShape(item) {
    const piece = {
      id: `preview:${item.id}`, type: item.kind, setId: item.id,
      dims: item.dims, color: item.color, u: 0.5, v: 0.5, facing: 0, size: 100,
    };
    const dims = pieceDims(piece) || item.dims || { w: 1, d: 1, h: 1 };
    let parts = [];
    try { parts = pieceParts(piece) || []; } catch (_) { parts = []; }
    /* ★なめらかな小道具は、箱ではなく本体と同じ曲面で描く。
       pieceParts は当たり判定のために外接の箱を返すので、形の正本は別に取る
       （本体の drawSmoothStageProp と同じ scaledPropShape）。 */
    let smooth = null;
    /* ★仮面だけは曲面の部品ではなく、本体と同じ paintMask で描く（顔が積み木に見えるため）。 */
    const mask = item.kind === "prop" && isMask(piece);
    if (item.kind === "prop" && !mask) {
      try { smooth = scaledPropShape(piece, dims).parts || null; } catch (_) { smooth = null; }
    }
    if (item.kind === "block" && item.round === true) smooth = [{
      shape: "cylinder", x: 0, y: 0, z: 0, w: dims.w, d: dims.w,
      dia: dims.w, h: dims.h, tint: 1,
    }];
    /* ディアボロは箱でも部品の集まりでもなく、軸のまわりに回した曲面。
       形の式は drawDiabolo と共有（diaboloProfile）。 */
    const lathe = item.kind === "diabolo" ? diaboloProfile(dims) : null;
    if (!parts.length && !smooth && !lathe) {
      const w = finite(dims.w, finite(dims.dia, 1));
      const d = finite(dims.d, finite(dims.dia, w));
      const h = finite(dims.h, finite(dims.dia, 1));
      parts = [{ ox: 0, oz: 0, w, d, h, lift: finite(dims.lift, 0), tint: 1 }];
    }
    return { parts, dims, smooth, lathe, mask };
  }

  /* 箱を8つの角へ。ox/oz は道具の中心からのずれ、lift は床からの高さ。 */
  function setInfoPreviewCorners(part) {
    const w = Math.max(0.01, finite(part.w, 0.5)) / 2;
    const d = Math.max(0.01, finite(part.d, 0.5)) / 2;
    const h = Math.max(0.01, finite(part.h, 0.5));
    const ox = finite(part.ox, 0);
    const oz = finite(part.oz, 0);
    const lift = finite(part.lift, 0);
    const out = [];
    [-1, 1].forEach((sz) => [-1, 1].forEach((sx) => {
      out.push({ x: ox + sx * w, y: oz + sz * d, z: lift });
    }));
    [-1, 1].forEach((sz) => [-1, 1].forEach((sx) => {
      out.push({ x: ox + sx * w, y: oz + sz * d, z: lift + h });
    }));
    return out;
  }

  function drawSetInfoPreview() {
    const canvas = els.setInfoPreview;
    const item = setInfoPreviewItem();
    if (!canvas || !item || !setInfoPreview) return;
    const ratio = Math.min(2, window.devicePixelRatio || 1);
    const cssWidth = canvas.clientWidth || 320;
    const cssHeight = SETINFO_PREVIEW.height;
    if (canvas.width !== Math.round(cssWidth * ratio) || canvas.height !== Math.round(cssHeight * ratio)) {
      canvas.width = Math.round(cssWidth * ratio);
      canvas.height = Math.round(cssHeight * ratio);
    }
    const ctx = canvas.getContext("2d");
    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
    ctx.clearRect(0, 0, cssWidth, cssHeight);

    const { parts, dims, smooth, lathe, mask } = setInfoPreviewShape(item);
    const yaw = (setInfoPreview.yaw * Math.PI) / 180;
    const tilt = Math.sin((setInfoPreview.tilt * Math.PI) / 180);
    const cos = Math.cos(yaw);
    const sin = Math.sin(yaw);
    // 回転台に乗せた点 → 画面（1mあたり k 画素は後で決める）
    const flat = (point) => ({
      fx: point.x * cos + point.y * sin,
      fy: -point.x * sin + point.y * cos,
      z: point.z,
    });
    const boxes = parts.filter((part) => part && !part.kind).map(setInfoPreviewCorners);
    const lines = parts.filter((part) => part && part.kind === "line" && part.a && part.b);
    /* ★丸いものを箱で出さない。球は丸く、円盤（盆・丸い座面）は楕円で描く。
       pieceParts は球に外接の箱を返すので、ここで見分けて描き替える。 */
    const discs = parts.filter((part) => part && part.kind === "disc" && Array.isArray(part.c));
    const ball = item.kind === "sphere"
      ? { r: Math.max(0.05, finite(dims.dia, finite(dims.w, 0.6)) / 2), lift: finite(dims.lift, 0) }
      : null;
    const setInfoPreviewSmoothPoints = (list) => (list || []).flatMap((part) => {
      const x = finite(part.x, 0);
      const y = finite(part.y, 0);
      const z = finite(part.z, 0);
      // 回転体・切り抜き板は輪郭から外接を取る（2026-09-29）
      if (part.shape === "lathe" && Array.isArray(part.profile) && part.profile.length) {
        const r = Math.max(...part.profile.map((p) => finite(p[1], 0))) / 2;
        const t0 = part.profile[0][0], t1 = part.profile[part.profile.length - 1][0];
        return [{ x: x - r, y: z - r, z: y + t0 }, { x: x + r, y: z + r, z: y + t1 }];
      }
      if (part.shape === "flat" && Array.isArray(part.pts) && part.pts.length) {
        const xs = part.pts.map((p) => p[0]), ys = part.pts.map((p) => p[1]);
        const hd = Math.max(0.004, finite(part.d, 0.05)) / 2;
        return [{ x: x + Math.min(...xs), y: z - hd, z: y + Math.min(...ys) }, { x: x + Math.max(...xs), y: z + hd, z: y + Math.max(...ys) }];
      }
      const hw = Math.max(finite(part.w, 0), finite(part.d, 0)) / 2;
      return [
        { x: x - hw, y: z - hw, z: y },
        { x: x + hw, y: z + hw, z: y + Math.max(0, finite(part.h, 0)) },
      ];
    });
    /* ろくろの形の点（軸に沿った輪の上下左右）。枠へ収める尺を決めるのに使う。 */
    const setInfoPreviewLathePoints = (shape) => {
      if (!shape) return [];
      const out = [];
      shape.sections.forEach(({ t, r }) => {
        const along = (t * shape.len) / 2;
        [[r, 0], [-r, 0], [0, r], [0, -r]].forEach(([dz, dy]) => {
          out.push({ x: along, y: dy, z: shape.R + dz });
        });
      });
      return out;
    };
    const all = setInfoPreviewLathePoints(lathe).concat(setInfoPreviewSmoothPoints(smooth))
      .concat(boxes.flat()).concat(lines.flatMap((part) => [
      { x: finite(part.a[0], 0), y: finite(part.a[2], 0), z: finite(part.a[1], 0) },
      { x: finite(part.b[0], 0), y: finite(part.b[2], 0), z: finite(part.b[1], 0) },
    ]));
    const flatAll = all.map(flat);
    const radius = Math.max(0.05, ...all.map(q => Math.hypot(q.x, q.y)));
    const rawSpan = radius * 2;
    const rawTop = Math.max(...flatAll.map((q) => q.z));
    /* ★小さい道具は人の影と並べない。12cmのディアボロを1.7mの人と並べると、
       道具が数画素になって形が読めない。見当をつける相手を物差しへ替える。 */
    const bigEnoughForFigure = Math.max(rawSpan, rawTop) >= SETINFO_PREVIEW.figureMinM;
    const figureH = bigEnoughForFigure ? SETINFO_PREVIEW.figureM : 0;
    const spanX = Math.max(0.1, rawSpan);
    const topZ = Math.max(figureH, rawTop, 0.05);
    /* 左に人の影の場所を取り、残りの真ん中へ道具を置く。
       尺は「人と道具の両方が枠に収まる」いちばん大きい値。 */
    const figureSpanM = bigEnoughForFigure ? 0.55 : 0;
    const gapM = bigEnoughForFigure ? 0.3 : 0;
    const margin = SETINFO_PREVIEW.marginPx;
    // 物差しのときは数字が下に付くので、そのぶん余白を取る（取らないと数字が切れる）
    const labelRoom = bigEnoughForFigure ? 13 : 24;
    const k = Math.min(
      (cssWidth - margin * 2) / (spanX + figureSpanM + gapM),
      (cssHeight - margin - labelRoom) / Math.max(0.6, topZ + radius * Math.abs(tilt) * 2),
    );
    const baseY = cssHeight - margin - labelRoom - radius * k * Math.abs(tilt);
    const figX = margin + (figureSpanM / 2) * k;
    const leftEdge = margin + (figureSpanM + gapM) * k;
    const centerX = leftEdge + (cssWidth - margin - leftEdge) / 2;
    const project = (point) => {
      const q = flat(point);
      return { X: centerX + q.fx * k, Y: baseY - q.z * k + q.fy * k * tilt, depth: q.fy };
    };

    // 床（回転台の面）
    ctx.save();
    ctx.strokeStyle = "rgba(239,231,214,0.10)";
    ctx.lineWidth = 1;
    const plateR = Math.max(0.45, spanX / 2 + 0.2);
    ctx.beginPath();
    for (let i = 0; i <= 48; i += 1) {
      const a = (i / 48) * Math.PI * 2;
      const at = project({ x: Math.cos(a) * plateR, y: Math.sin(a) * plateR, z: 0 });
      if (i) ctx.lineTo(at.X, at.Y); else ctx.moveTo(at.X, at.Y);
    }
    ctx.stroke();
    ctx.restore();

    /* 大きさの見当をつける人の影（回さない。いつも左に立つ）。
       ★頭と体は1つながりに描く。離して描くと点が浮いて見える。 */
    if (!bigEnoughForFigure) {
      /* 物差し。道具の幅に合う切りのよい長さ（1・2・5・10…cm）を選んで、足元に引く。 */
      const setInfoPreviewRuler = () => {
        /* ★物差しの長さは幅ではなく「いちばん長いところ」から決める。
           幅だけで決めると、細長いクラブ（幅10cm・丈50cm）で2cmの棒になって読めない。 */
        const want = Math.max(0.01, Math.max(spanX, topZ) * 0.6);
        const power = Math.pow(10, Math.floor(Math.log10(want)));
        const step = [1, 2, 5, 10].map((unit) => unit * power).find((value) => value >= want) || want;
        const half = (step / 2) * k;
        const y = baseY + 6;
        ctx.save();
        ctx.strokeStyle = "rgba(239,231,214,0.42)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(centerX - half, y);
        ctx.lineTo(centerX + half, y);
        ctx.moveTo(centerX - half, y - 4); ctx.lineTo(centerX - half, y + 4);
        ctx.moveTo(centerX + half, y - 4); ctx.lineTo(centerX + half, y + 4);
        ctx.stroke();
        ctx.fillStyle = "rgba(239,231,214,0.5)";
        ctx.font = "11px 'Hiragino Kaku Gothic ProN', sans-serif";
        ctx.textAlign = "center";
        ctx.fillText(step >= 1 ? `${Math.round(step * 10) / 10}m` : `${Math.round(step * 100)}cm`,
          centerX, y + 15);
        ctx.restore();
      };
      setInfoPreviewRuler();
    }
    ctx.save();
    const figTop = baseY - figureH * k;
    const headR = 0.093 * figureH * k;
    const shoulderY = figTop + headR * 2.05;
    const hipW = 0.155 * figureH * k;
    const shoulderW = 0.2 * figureH * k;
    ctx.fillStyle = "rgba(239,231,214,0.17)";
    if (!bigEnoughForFigure) { ctx.restore(); } else {
    ctx.beginPath();
    ctx.moveTo(figX - hipW, baseY);
    ctx.lineTo(figX - shoulderW, shoulderY + headR * 0.5);
    ctx.quadraticCurveTo(figX - shoulderW * 0.8, shoulderY - headR * 0.25, figX - headR * 0.62, shoulderY - headR * 0.35);
    ctx.arc(figX, shoulderY - headR * 0.72, headR, Math.PI * 0.86, Math.PI * 0.14, false);
    ctx.quadraticCurveTo(figX + shoulderW * 0.8, shoulderY - headR * 0.25, figX + shoulderW, shoulderY + headR * 0.5);
    ctx.lineTo(figX + hipW, baseY);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    }

    // 道具。奥の面から順に塗る
    const tone = validColor(item.color, "#8b98a1");
    const faces = [[0, 1, 3, 2], [4, 5, 7, 6], [0, 1, 5, 4], [2, 3, 7, 6], [0, 2, 6, 4], [1, 3, 7, 5]];
    const drawn = [];
    (ball || smooth || lathe || mask ? [] : boxes).forEach((corners) => {
      const at = corners.map(project);
      faces.forEach((face) => {
        const pts = face.map((index) => at[index]);
        const depth = pts.reduce((sum, q) => sum + q.depth, 0) / pts.length;
        drawn.push({ pts, depth, up: face === faces[1] });
      });
    });
    drawn.sort((a, b) => a.depth - b.depth).forEach((face) => {
      ctx.beginPath();
      face.pts.forEach((q, index) => { if (index) ctx.lineTo(q.X, q.Y); else ctx.moveTo(q.X, q.Y); });
      ctx.closePath();
      ctx.fillStyle = mixToneForPreview(tone, face.up ? 0.22 : -0.12);
      ctx.fill();
      ctx.strokeStyle = "rgba(0,0,0,0.35)";
      ctx.lineWidth = 1;
      ctx.stroke();
    });
    /* ディアボロ。軸のまわりに輪を並べ、帯（四角）でつないで塗る。
       ★奥の帯から順に塗る。明るさは輪のどこを向いているかで決める（左上から光が当たる感じ）。 */
    const setInfoPreviewLathe = (shape) => {
      const around = 24;
      const faces = [];
      for (let i = 0; i + 1 < shape.sections.length; i += 1) {
        const a = shape.sections[i];
        const bSec = shape.sections[i + 1];
        const ax = (a.t * shape.len) / 2;
        const bx = (bSec.t * shape.len) / 2;
        for (let j = 0; j < around; j += 1) {
          const t0 = (j / around) * Math.PI * 2;
          const t1 = ((j + 1) / around) * Math.PI * 2;
          const corner = (x, r, angle) => project({
            x, y: Math.sin(angle) * r, z: shape.R + Math.cos(angle) * r,
          });
          const pts = [corner(ax, a.r, t0), corner(bx, bSec.r, t0),
            corner(bx, bSec.r, t1), corner(ax, a.r, t1)];
          const mid = (t0 + t1) / 2;
          faces.push({
            pts,
            depth: pts.reduce((sum, q) => sum + q.depth, 0) / pts.length,
            shade: 0.26 * Math.cos(mid - Math.PI * 0.25) - 0.06,
          });
        }
      }
      faces.sort((x, y) => x.depth - y.depth).forEach((face) => {
        ctx.beginPath();
        face.pts.forEach((q, index) => { if (index) ctx.lineTo(q.X, q.Y); else ctx.moveTo(q.X, q.Y); });
        ctx.closePath();
        ctx.fillStyle = mixToneForPreview(tone, face.shade);
        ctx.fill();
        // 帯の継ぎ目を消す。線を引かないと、帯の境に地の色が透ける
        ctx.strokeStyle = ctx.fillStyle;
        ctx.lineWidth = 1;
        ctx.stroke();
      });
    };
    if (lathe) setInfoPreviewLathe(lathe);

    /* なめらかな小道具。本体と同じ paintSmoothProp に、回転台の投影を渡す。
       受け渡しの約束: (左右, 高さ, 奥行き) → 画面。z は奥から順に塗るための遠さ。 */
    const setInfoPreviewSmooth = window.SHOSAI_STAGE_BODY;
    if (smooth && setInfoPreviewSmooth) {
      setInfoPreviewSmooth.paintSmoothProp(ctx, smooth, (px, py, pz) => {
        const at = project({ x: px, y: pz, z: py });
        return { x: at.X, y: at.Y, z: at.depth };
      }, tone);
    }

    /* 仮面。本体と同じ paintMask へ回転台の投影を渡す。
       ★paintMask の高さは面の中心からの差。床からの高さへ直すのはこちら側の仕事。 */
    const setInfoPreviewMask = window.SHOSAI_STAGE_BODY;
    if (mask && setInfoPreviewMask) {
      setInfoPreviewMask.paintMask(ctx, (mx, my, mz) => {
        const at = project({ x: mx, y: mz, z: finite(dims.h, 0.3) / 2 + my });
        return { x: at.X, y: at.Y, z: at.depth };
      }, dims, tone);
    }

    // 円盤（盆・丸い座面）。回転台の面と同じ向きの楕円で置く
    const setInfoPreviewDisc = (part) => {
      const cx = finite(part.c[0], 0);
      const cz = finite(part.c[2], 0);
      const cy = finite(part.c[1], 0);
      const r = Math.max(0.02, finite(part.r, 0.2));
      const top = cy + Math.max(0, finite(part.h, 0));
      ctx.beginPath();
      for (let i = 0; i <= 40; i += 1) {
        const a = (i / 40) * Math.PI * 2;
        const at = project({ x: cx + Math.cos(a) * r, y: cz + Math.sin(a) * r, z: top });
        if (i) ctx.lineTo(at.X, at.Y); else ctx.moveTo(at.X, at.Y);
      }
      ctx.closePath();
      ctx.fillStyle = mixToneForPreview(tone, 0.16);
      ctx.fill();
      ctx.strokeStyle = "rgba(0,0,0,0.35)";
      ctx.lineWidth = 1;
      ctx.stroke();
    };
    discs.forEach(setInfoPreviewDisc);

    // 球。回しても見え方は変わらないので、丸と陰影だけで出す
    if (ball) {
      const at = project({ x: 0, y: 0, z: ball.lift + ball.r });
      const px = ball.r * k;
      const shade = ctx.createRadialGradient(at.X - px * 0.35, at.Y - px * 0.4, px * 0.1, at.X, at.Y, px);
      shade.addColorStop(0, mixToneForPreview(tone, 0.3));
      shade.addColorStop(1, mixToneForPreview(tone, -0.22));
      ctx.beginPath();
      ctx.ellipse(at.X, at.Y, px, px, 0, 0, Math.PI * 2);
      ctx.fillStyle = shade;
      ctx.fill();
      ctx.strokeStyle = "rgba(0,0,0,0.3)";
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    // 綱・棒のたぐい
    ctx.strokeStyle = mixToneForPreview(tone, 0.1);
    ctx.lineCap = "round";
    lines.forEach((part) => {
      const a = project({ x: finite(part.a[0], 0), y: finite(part.a[2], 0), z: finite(part.a[1], 0) });
      const b = project({ x: finite(part.b[0], 0), y: finite(part.b[2], 0), z: finite(part.b[1], 0) });
      ctx.lineWidth = Math.max(1.5, finite(part.w, 0.05) * k);
      ctx.beginPath();
      ctx.moveTo(a.X, a.Y);
      ctx.lineTo(b.X, b.Y);
      ctx.stroke();
    });

    // 寸法の目安（人の影の足元に）
    if (bigEnoughForFigure) {
      ctx.fillStyle = "rgba(239,231,214,0.45)";
      ctx.font = "11px 'Hiragino Kaku Gothic ProN', sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(`${SETINFO_PREVIEW.figureM.toFixed(1)}m`, figX, baseY + 11);
    }
  }

  /* 色を明るく／暗くする。面ごとの陰影だけに使う小さな道具。 */
  function mixToneForPreview(hex, amount) {
    const text = /^#[0-9a-f]{6}$/i.test(String(hex)) ? String(hex) : "#8b98a1";
    const value = parseInt(text.slice(1), 16);
    const mix = (channel) => {
      const next = amount >= 0
        ? channel + (255 - channel) * amount
        : channel * (1 + amount);
      return Math.max(0, Math.min(255, Math.round(next)));
    };
    return `rgb(${mix((value >> 16) & 255)},${mix((value >> 8) & 255)},${mix(value & 255)})`;
  }

  function setInfoPreviewFrame(now) {
    if (!setInfoPreview) return;
    const last = setInfoPreview.last || now;
    setInfoPreview.last = now;
    if (setInfoPreview.spin && !document.hidden) {
      setInfoPreview.yaw = (setInfoPreview.yaw + ((now - last) / 1000) * (360 / SETINFO_PREVIEW.turnSeconds)) % 360;
    }
    const item = setInfoPreviewItem();
    const stamp = item ? JSON.stringify([item.kind, item.dims, item.color, item.framed,
      item.frameWidth, item.propShape, item.modelId, item.flown]) : "";
    if (setInfoPreview.spin || stamp !== setInfoPreview.stamp || setInfoPreview.dirty) {
      setInfoPreview.stamp = stamp;
      setInfoPreview.dirty = false;
      drawSetInfoPreview();
    }
    setInfoPreview.raf = window.requestAnimationFrame(setInfoPreviewFrame);
  }

  function startSetInfoPreview() {
    const canvas = els.setInfoPreview;
    if (!canvas) return;
    stopSetInfoPreview();
    const still = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    setInfoPreview = { yaw: 24, tilt: SETINFO_PREVIEW.tiltDeg, spin: !still, stamp: "", dirty: true, raf: 0, last: 0 };
    if (els.setInfoPreviewHint) {
      els.setInfoPreviewHint.textContent = tx(still ? "ドラッグで回せます" : "自動で回ります。ドラッグでも回せます");
    }
    setInfoPreview.raf = window.requestAnimationFrame(setInfoPreviewFrame);
  }

  function stopSetInfoPreview() {
    if (setInfoPreview && setInfoPreview.raf) window.cancelAnimationFrame(setInfoPreview.raf);
    setInfoPreview = null;
    document.body.classList.remove("is-setinfo-preview-dragging");
  }

  function openSetInfo(setId) {
    if (window.GAMMA_UI.layers.isOpen(els.setInfo)) return;
    const item = (state.project.sets || []).find((t) => t.id === setId);
    if (!item || !els.setInfo) return;
    setInfoId = setId;
    els.setInfoTitle.textContent = `${item.name}（${setKindName(item.kind)}）`;
    els.setInfoName.value = item.name;
    els.setInfoColor.value = item.color;
    if (els.setInfoKindRow) {
      els.setInfoKindRow.hidden = item.kind !== "light";
      if (item.kind === "light" && els.setInfoKind) els.setInfoKind.value = lightKindOf(item);
    }
    if (els.setInfoMotionRow) {
      els.setInfoMotionRow.hidden = item.kind !== "light";
      if (item.kind === "light" && els.setInfoMotion) {
        els.setInfoMotion.value = normalizeLightCapability(item.lightCapability)?.motion || "fixed";
      }
    }
    if (els.setInfoPropShapeRow) {
      els.setInfoPropShapeRow.hidden = item.kind !== "prop";
      if (item.kind === "prop") renderPropShapeSelect(els.setInfoPropShape, item.propShape);
    }
    if (els.setInfoFlownRow) {
      // 吊れるのは形のあるもの（台・テーブル・椅子・壁）だけ
      const canFly = Boolean(SOLID_TYPES[item.kind]
        && !["seri", "model", "revolve", "deck", "curtain", "pool"].includes(item.kind));
      const onlyFlown = Boolean(FLOWN_ONLY[item.kind]);
      els.setInfoFlownRow.hidden = !canFly;
      if (els.setInfoFlown) {
        // 吊物にしかならない道具は、床置きへ戻せない
        els.setInfoFlown.disabled = onlyFlown;
        els.setInfoFlownRow.title = onlyFlown ? "この道具は吊物にしかなりません" : "";
      }
      if (els.setInfoFlownNote) els.setInfoFlownNote.hidden = !canFly || !item.flown;
      if (els.setInfoFlown) els.setInfoFlown.checked = Boolean(item.flown);
      if (els.setInfoFramedRow) {
        els.setInfoFramedRow.hidden = item.kind !== "wall";
        if (els.setInfoFramed) els.setInfoFramed.checked = Boolean(item.framed);
      }
      if (els.setInfoRoundRow) {
        els.setInfoRoundRow.hidden = item.kind !== "block";
        if (els.setInfoRound) els.setInfoRound.checked = item.round === true;
      }
      /* T-30: 枠の幅はフレームにしているときだけ出す（値は隠しても保持する）。 */
      if (els.setInfoFrameWidthRow) {
        const showFrameWidth = item.kind === "wall" && Boolean(item.framed);
        els.setInfoFrameWidthRow.hidden = !showFrameWidth;
        if (showFrameWidth && els.setInfoFrameWidth) {
          els.setInfoFrameWidth.value = wallFrameWidth(item, pieceDims({ type: "wall", setId: item.id, dims: item.dims }) || item.dims || { w: 2, h: 2 }).toFixed(2);
        }
      }
      if (els.setInfoWiresRow) els.setInfoWiresRow.hidden = !canFly || !item.flown;
      if (els.setInfoWires) els.setInfoWires.value = String(Number(item.wires) === 1 ? 1 : 2);
    }
    els.setInfoNote.value = item.note || "";
    buildDimControls(els.setInfoDims, "stage-setinfo", item.kind, item.dims, () => {
      if (item.kind === "block" && item.round === true) item.dims.d = item.dims.w;
      item.estimated = false;
      renderSets();
      renderLights();
      updateInspector();
      render();
      persistSoon();
    }, Boolean(item.flown));
    if (item.kind === "block" && item.round === true) {
      const depth = els.setInfoDims.querySelector("#stage-setinfo-d");
      const depthLabel = els.setInfoDims.querySelector('label[for="stage-setinfo-d"]');
      const widthLabel = els.setInfoDims.querySelector('label[for="stage-setinfo-w"] span');
      if (depth) depth.hidden = true;
      if (depthLabel) depthLabel.hidden = true;
      if (widthLabel) widthLabel.textContent = tx("直径");
    }
    els.setInfo.hidden = false;
    startSetInfoPreview();          // L-04: 回転台のプレビューを回し始める
    els.setInfoBackdrop.hidden = false;
    els.setInfoName.focus();
    els.setInfoName.select();
  }

  function closeSetInfo() {
    for (const input of [els.setInfoName, els.setInfoColor, els.setInfoNote]) noteEditCheckpoints.delete(input);
    stopSetInfoPreview();           // L-04: 閉じたら回すのをやめる
    setInfoId = null;
    if (els.setInfo) els.setInfo.hidden = true;
    if (els.setInfoBackdrop) els.setInfoBackdrop.hidden = true;
  }

  /* ---------- 演者プロフィール ---------- */

  let profileId = null;
  const noteEditCheckpoints = new WeakSet();
  function checkpointNoteEdit(input) {
    if (noteEditCheckpoints.has(input)) return;
    checkpoint(); noteEditCheckpoints.add(input);
  }
  for (const input of [els.profileName, els.profileHeight, els.profileColor, els.profileNote, els.setInfoName, els.setInfoColor, els.setInfoNote]) {
    input?.addEventListener("blur", () => noteEditCheckpoints.delete(input));
  }

  function openProfile(castId) {
    if (window.GAMMA_UI.layers.isOpen(els.profile)) return;
    for (const input of [els.profileName, els.profileHeight, els.profileColor, els.profileNote]) noteEditCheckpoints.delete(input);
    const member = state.project.cast.find((c) => c.id === castId);
    if (!member || !els.profile) return;
    profileId = castId;
    els.profileName.value = member.name;
    updateDuplicateCastNotice(els.profileName, member.id);
    els.profileHeight.value = String(member.heightCm || DEFAULT_HEIGHT_CM);
    els.profileHeightValue.textContent = String(member.heightCm || DEFAULT_HEIGHT_CM);
    els.profileColor.value = member.color;
    els.profileNote.value = member.note || "";
    els.profile.hidden = false;
    els.profileBackdrop.hidden = false;
    els.profileName.focus();
    els.profileName.select();
  }

  function closeProfile() {
    for (const input of [els.profileName, els.profileHeight, els.profileColor, els.profileNote]) noteEditCheckpoints.delete(input);
    profileId = null;
    if (els.profile) els.profile.hidden = true;
    if (els.profileBackdrop) els.profileBackdrop.hidden = true;
  }

  function profileMember() {
    return profileId ? state.project.cast.find((c) => c.id === profileId) : null;
  }

  // 身長が変わると、その演者が出ているシーンすべてで見え方が変わる
  function applyProfileChange(fn) {
    const member = profileMember();
    if (!member) return;
    fn(member);
    renderCast();
    renderSets();
    renderLights();
    renderRigs();
    render();
    persistSoon();
  }

  if (els.profileClose) els.profileClose.addEventListener("click", closeProfile);
  if (els.profileBackdrop) els.profileBackdrop.addEventListener("click", closeProfile);
  if (els.profileName) {
    els.profileName.addEventListener("input", (e) => {
      const member = profileMember(), name = e.target.value.slice(0, 24);
      if (!member || member.name === name) return;
      checkpointNoteEdit(els.profileName);
      applyProfileChange((m) => { m.name = name; });
      updateDuplicateCastNotice(els.profileName, profileId);
    });
  }
  if (els.profileHeight) {
    els.profileHeight.addEventListener("input", (e) => {
      const member = profileMember(), height = clamp(Number(e.target.value), 120, 210);
      els.profileHeightValue.textContent = e.target.value;
      if (!member || member.heightCm === height) return;
      checkpointNoteEdit(els.profileHeight);
      applyProfileChange((m) => { m.heightCm = height; });
    });
  }
  if (els.profileColor) {
    els.profileColor.addEventListener("input", (e) => {
      const member = profileMember();
      if (!member || member.color === e.target.value) return;
      checkpointNoteEdit(els.profileColor);
      applyProfileChange((m) => {
        m.color = e.target.value;
        state.project.scenes.forEach((scene) => {
          scene.pieces.forEach((piece) => {
            if (piece.castId === m.id) piece.color = m.color;
          });
        });
      });
    });
  }
  if (els.profileNote) {
    els.profileNote.addEventListener("input", (e) => {
      const member = profileMember(), note = e.target.value.slice(0, 200);
      if (!member || (member.note || "") === note) return;
      checkpointNoteEdit(els.profileNote);
      applyProfileChange((m) => { m.note = note; });
    });
  }
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && profileId) closeProfile();
  });

  /* ---------- シーンとプロジェクト ---------- */

  /* 並べ替え・追加・削除の起点になる行。セクションを押したときは、
   * 絵を持たないので「開く」ことはできないが、操作の起点にはなる。 */
  function cursorIndex() {
    const list = state.project.scenes;
    const byCursor = list.findIndex((x) => x.id === state.cursorRowId);
    if (byCursor >= 0) return byCursor;
    return list.findIndex((x) => x.id === state.project.activeSceneId);
  }

  // その行に属する子（自分より深い行が続くあいだ）
  function sceneChildren(index) {
    const list = state.project.scenes;
    const base = list[index].depth;
    let end = index + 1;
    while (end < list.length && list[end].depth > base) end += 1;
    return list.slice(index + 1, end);
  }

  // どの入口から深さを変えても、飛び級の入れ子を保存しない。
  function tidySceneDepths() {
    let prev = -1;
    state.project.scenes.forEach((sceneRow) => {
      sceneRow.depth = Math.min(sceneRow.depth, prev + 1);
      prev = sceneRow.depth;
    });
    let generatedSectionCount = state.project.scenes
      .filter((row) => row.kind === "section" && row.depth === 0).length;
    wrapUnsectionedSceneRuns(state.project.scenes,
      () => newScene(sectionTitle(++generatedSectionCount), false, "section", 0));
  }

  function canShiftSceneDepth(scene, step) {
    const list = state.project.scenes;
    const index = list.indexOf(scene);
    if (index < 0) return false;
    if (step === -1) return scene.kind === "scene" ? scene.depth > 1 : scene.depth > 0;
    if (step !== 1 || scene.depth + 1 > MAX_DEPTH || index === 0) return false;
    return scene.depth <= list[index - 1].depth;
  }

  async function shiftSceneDepth(scene, step) {
    if (!canShiftSceneDepth(scene, step)) return false;
    const project = state.project, list = project.scenes;
    const index = list.indexOf(scene);
    const moving = [scene, ...sceneChildren(index)];
    // 親だけ動いて子が上限に取り残される状態は作らない。
    if (step > 0 && moving.some(row => row.depth + step > MAX_DEPTH)) {
      announce("これ以上内側へは入れられません。");
      return false;
    }
    const candidate = list.slice();
    if (step < 0) {
      // 外へ出すときは元の親の最後へ移し、後続の兄弟を子として取り込まない。
      const parentDepth = scene.depth - 1;
      let end = index + moving.length;
      while (end < list.length && list[end].depth > parentDepth) end += 1;
      if (end > index + moving.length) {
        candidate.splice(index, moving.length);
        candidate.splice(end - moving.length, 0, ...moving);
      }
    }
    const before = list.filter(row => row.kind === "scene").map(row => row.id);
    const after = candidate.filter(row => row.kind === "scene").map(row => row.id);
    const reordered = before.some((id, at) => id !== after[at]);
    if (reordered) {
      // Compare only structural input; rendering and autosave can change other state while the dialog is open.
      const structure = () => JSON.stringify(state.project.scenes.map(row => [row.id, row.kind, row.depth]));
      const original = structure();
      const allowed = await window.GAMMA_REORDER_WARNING?.request({ before, after,
        labelFor: id => id === null ? tx("終了") : list.find(row => row.id === id)?.title || id });
      if (!allowed || state.project !== project || structure() !== original) return false;
    }
    checkpoint();
    state.project.scenes = candidate;
    moving.forEach(row => { row.depth += step; });
    tidySceneDepths();
    if (reordered) {
      const changed = window.GAMMA_REORDER_WARNING.changes(before, after);
      for (const item of state.project.runOfShow?.items || []) {
        if (changed.some(edge => edge.id === item.sceneId)) item.transitionReview = true;
      }
    }
    state.cursorRowId = scene.id;
    renderScenes();
    renderSceneGrid();
    persistSoon();
    window.dispatchEvent(new Event("stage-timeline-structure-change"));
    announce(step > 0 ? "一段内側へ入れました。" : "一段外へ出しました。");
    return true;
  }

  function focusSceneChip(sceneId) {
    if (!els.sceneList) return;
    const renderedRow = [...els.sceneList.querySelectorAll("[data-scene-id]")]
      .find((row) => row.dataset.sceneId === sceneId);
    const chip = renderedRow && renderedRow.querySelector(".stage-scene-chip");
    if (chip) chip.focus();
  }

  // セクション内は直下だけでなく、さらに入れ子になったシーンも同じまとまりとして数える。
  function sectionTotals(index) {
    const scenes = sceneChildren(index).filter((row) => row.kind === "scene");
    const seconds = scenes.reduce((sum, scene) => {
      const rehearsal = scene.rehearsal || {};
      return sum + finite(rehearsal.holdDurationSeconds, 0)
        + finite(rehearsal.transitionToNextSeconds, 0);
    }, 0);
    return { scenes: scenes.length, seconds };
  }

  function sectionDurationText(seconds) {
    if (seconds < 60) return lang === "en" ? `${Math.round(seconds)} sec` : `${Math.round(seconds)}${tx("秒")}`;
    return sx(`約${Math.round(seconds / 60)}分`, `~${Math.round(seconds / 60)} min`);
  }

  function sectionSummary(totals, place) {
    const showTime = featureOn("sceneTiming") && totals.seconds > 0;
    const duration = showTime ? sectionDurationText(totals.seconds) : "";
    if (place === "list") return showTime ? `${totals.scenes}・${duration}` : `${totals.scenes}`;
    return languageValue(() => {
      const scenes = `${totals.scenes} ${totals.scenes === 1 ? "scene" : "scenes"}`;
      if (!showTime) return scenes;
      return place === "title" ? `${scenes} · total ${duration}` : `${scenes} · ${duration}`;
    }, () => {
      if (!showTime) return `${totals.scenes}シーン`;
      return place === "title"
        ? `${totals.scenes}シーン・合計 ${duration}`
        : `${totals.scenes}シーン・${duration}`;
    });
  }

  // 畳んだセクションの中にいるか
  function sceneHidden(index) {
    const list = state.project.scenes;
    for (let i = index - 1; i >= 0; i -= 1) {
      if (list[i].depth < list[index].depth) {
        if (list[i].kind === "section" && state.closedSections[list[i].id]) return true;
        if (sceneHidden(i)) return true;
        return false;
      }
    }
    return false;
  }

  // 一覧とグリッドで同じ数え札を使う。深さが戻ったら内側の札は捨てる。
  function sceneNumberMap(rows) {
    const counters = [];
    const numbers = new Map();
    (rows || []).forEach((scene) => {
      counters[scene.depth] = (counters[scene.depth] || 0) + 1;
      counters.length = scene.depth + 1;
      numbers.set(scene.id, counters.join("-"));
    });
    return numbers;
  }

  // 「後からまとめる」の開始行。プロジェクトの内容ではないためstateへ保存しない。
  let wrapPickStartId = null;
  // 常設の転換ポイントから開いた詳細。ショーの内容ではないため保存しない。
  let expandedSceneTransitionToId = null;
  let timelinePanelTransition = null;

  function clearWrapPick() {
    wrapPickStartId = null;
    if (!els.sceneList) return;
    els.sceneList.classList.remove("is-wrap-picking");
    els.sceneList.querySelectorAll(".is-wrap-start").forEach((row) => row.classList.remove("is-wrap-start"));
  }

  function cancelWrapPick(message) {
    clearWrapPick();
    renderScenes();
    announce(message || "まとめるのを中止しました。");
  }

  function beginWrapPick(sceneId) {
    wrapPickStartId = sceneId;
    renderScenes();
    announce("まとめる最後のシーンをクリックしてください。同じシーンを押すと1つだけまとめます。Escで中止。");
  }

  function finishWrapPick(endId) {
    const list = state.project.scenes;
    const start = list.findIndex((row) => row.id === wrapPickStartId);
    const end = list.findIndex((row) => row.id === endId);
    const startRow = list[start];
    const endRow = list[end];
    const depth = startRow && startRow.depth;
    const valid = start >= 0 && end >= start
      && startRow.kind === "scene" && endRow.kind === "scene"
      && endRow.depth === depth
      && list.slice(start, end + 1).every((row) => row.depth >= depth);
    if (!valid) {
      cancelWrapPick();
      return;
    }

    const chosen = list.slice(start, end + 1);
    if (chosen.some((row) => row.depth + 1 > MAX_DEPTH)) {
      clearWrapPick();
      renderScenes();
      announce("深さの上限に達するため、ここではまとめられません。");
      return;
    }

    checkpoint();
    const count = list.filter((row) => row.kind === "section").length;
    const section = newScene(sx(`セクション ${count + 1}`, `Section ${count + 1}`),
      false, "section", depth);
    const sceneCount = chosen.filter((row) => row.kind === "scene").length;
    chosen.forEach((row) => { row.depth += 1; });
    list.splice(start, 0, section);
    state.cursorRowId = section.id;
    clearWrapPick();
    renderScenes();
    persistSoon();
    openRename(section);
    announce(`${sceneCount}シーンをまとめました。`);
  }

  /* 色バーは行の中の一列ではなく、行の左端に敷いた溝へ置く。
   * 見出しの中に入れると、開いている行（メモや動線のボタンを抱えた背の高い行）で
   * 上の数十pxしか塗られず、幕の線がそこで切れて見える。 */
  function makeSceneBars(scene, ancestors) {
    const bars = document.createElement("span");
    bars.className = "stage-scene-bars";
    bars.setAttribute("aria-hidden", "true");
    for (let depth = 0; depth < scene.depth; depth += 1) {
      const section = ancestors[depth];
      if (!section || section.kind !== "section") continue;
      const mark = document.createElement("i");
      mark.className = "stage-scene-bar-mark";
      mark.style.setProperty("--bar-slot", depth);
      mark.style.backgroundColor = sectionColor(section);
      bars.append(mark);
    }
    if (scene.kind === "section") {
      const own = document.createElement("i");
      own.className = "stage-scene-bar-mark is-own";
      own.style.setProperty("--bar-slot", scene.depth);
      own.style.backgroundColor = sectionColor(scene);
      bars.append(own);
    }
    return bars;
  }

  /* 行と行の隙間でバーが切れないよう、下の行へ続く分だけ伸ばす。
   * 「次に見えている行が、その溝より深いか」で判断する。深くなければ
   * そこがその幕の終わりなので伸ばさない（次の幕の頭まで線が垂れない）。 */
  function linkSceneBars() {
    if (!els.sceneList) return;
    const rows = [...els.sceneList.children].filter((row) => row.dataset && row.dataset.sceneId);
    rows.forEach((row, i) => {
      const next = rows[i + 1];
      const nextDepth = next ? Number(next.dataset.depth) : -1;
      const linkLength = next
        ? Math.max(0, next.getBoundingClientRect().top - row.getBoundingClientRect().bottom)
        : 0;
      row.querySelectorAll(".stage-scene-bar-mark").forEach((mark) => {
        const slot = Number(mark.style.getPropertyValue("--bar-slot"));
        const linked = nextDepth > slot;
        mark.classList.toggle("is-linked", linked);
        if (linked) mark.style.setProperty("--scene-bar-link", `${linkLength}px`);
        else mark.style.removeProperty("--scene-bar-link");
      });
    });
  }
  let sceneBarLinkFrame = 0;
  function scheduleSceneBarLinks() {
    if (sceneBarLinkFrame) cancelAnimationFrame(sceneBarLinkFrame);
    sceneBarLinkFrame = requestAnimationFrame(() => {
      sceneBarLinkFrame = 0;
      linkSceneBars();
    });
  }

  // 2026-09-21 本人指定: 暗転の保存値と再生処理は残し、編集欄だけを一時的に隠す。
  const SHOW_BLACKOUT_CONTROL = false;

  /* シーン一覧を組む。
     引数なし＝従来どおり全部作り直す（69箇所の呼び出し元はこのまま）。
     ★`{ activeChange: { fromId, toId, cursorFromId } }` を渡すと、変わった行と隣接する転換の境界だけ
       「中身」を差し替える（要素そのものは入れ替えない）。
       ・一覧の直下の要素を入れ替えないので、タイムラインの MutationObserver（直下の childList を監視）が
         発火せず、全プロジェクトの複製を伴う renderTimeline（400シーンで61ms・2026-09-16 実測）が走らない。
       ・行を作り直さないので、他の行の入力中の文字・フォーカス・スクロールが残る。
       ・行の並びが変わる操作（追加・削除・並べ替え・折り畳み）では、並びの照合で不一致になり従来の全再構築へ落ちる。 */
  function renderScenes(options) {
    syncSceneLocation();
    const p = state.project;
    const activeChange = options && options.activeChange ? options.activeChange : null;
    if (els.sceneList) {
      if (wrapPickStartId && !p.scenes.some((row) => row.id === wrapPickStartId)) wrapPickStartId = null;
      els.sceneList.classList.toggle("is-wrap-picking", Boolean(wrapPickStartId));
      /* 番号は入れ子に沿って振る。セクションの中のシーンは「4-1」のようになる。
       * 深さごとの数え札を持ち、浅い所へ戻ったら深い側は捨てる。 */
      const sceneNumbers = sceneNumberMap(p.scenes);
      const overviewContext = createSceneOverviewContext(sceneNumbers);
      const sectionStack = [];

      const makeRehearsalTimeInput = (ownerScene, labelJa, key) => {
        const label = document.createElement("label");
        /* T-1（2026-09-17）: ラベルの文字は画面に出さない（本人指示）。
         * 読み上げ用には input の aria-label が残るので、意味は失わない。 */
        const title = document.createElement("span");
        title.className = "visually-hidden";
        title.textContent = tx(labelJa);
        const value = document.createElement("span");
        const input = document.createElement("input");
        input.type = "number";
        input.min = "0";
        input.max = "86400";
        input.step = "0.1";
        input.inputMode = "decimal";
        input.value = ownerScene.rehearsal && ownerScene.rehearsal[key] !== null
          ? String(ownerScene.rehearsal[key]) : "";
        input.setAttribute("aria-label", tx(`${labelJa}（秒）`));
        /* T-1: ラベルを消したぶん、ポインタを乗せれば何の秒数かわかるようにしておく。 */
        input.title = tx(labelJa);
        // Keep the starting state until blur: number steppers emit change for each
        // press, while typing (including native Undo) must keep the same input node.
        const project = state.project;
        let edit = null;
        const currentOwner = () => state.project === project
          ? state.project.scenes.find(row => row.id === ownerScene.id) : null;
        const writeValue = (seconds) => {
          const owner = currentOwner();
          if (!owner || owner.rehearsal?.[key] === seconds) return;
          if (!edit) edit = { before: snapshot(), start: owner.rehearsal?.[key] };
          if (!owner.rehearsal) owner.rehearsal = normalizeSceneRehearsal(null);
          owner.rehearsal[key] = seconds;
          persistSoon();
        };
        input.addEventListener("input", () => {
          writeValue(rehearsalSeconds(input.value));
          /* 2026-09-17: 打っている間もタイムラインを動かす。確定まで動かないと
             「効いていない」ように見えるため。受け手はフレームに1回へまとめている。
             シーン一覧の作り直しは重いので、確定（blur）のときだけにする。 */
          window.dispatchEvent(new CustomEvent("stage-timeline-structure-change"));
          if (els.rehearsalExportModal && !els.rehearsalExportModal.hidden) {
            refreshRehearsalExport();
          }
        });
        input.addEventListener("change", () => {
          /* T-2: 空のまま確定したら既定値へ戻す（入力中の一時的な空欄は邪魔しない）。 */
          const owner = currentOwner();
          if (owner?.rehearsal?.[key] === null) {
            writeValue(key === "holdDurationSeconds"
              ? DEFAULT_SCENE_HOLD_SECONDS
              : DEFAULT_SCENE_TRAVEL_SECONDS);
            input.value = String(owner.rehearsal[key]);
          }
        });
        input.addEventListener("blur", () => {
          const owner = currentOwner();
          if (!owner) { edit = null; return; }
          // Blur also finalizes an empty draft if no native change was emitted.
          if (owner.rehearsal?.[key] === null) {
            writeValue(key === "holdDurationSeconds" ? DEFAULT_SCENE_HOLD_SECONDS : DEFAULT_SCENE_TRAVEL_SECONDS);
          }
          if (!edit) return;
          if (edit && owner.rehearsal?.[key] !== edit.start) checkpointFrom(edit.before);
          edit = null;
          renderScenes();
          renderSceneGrid();
          /* T-3（2026-09-17）: シーンパネルで秒数を変えたら、タイムラインの長さもその場で合わせる。
           * 同じ scene.rehearsal を見ているのに、再描画だけが呼ばれていなかった。 */
          window.dispatchEvent(new CustomEvent("stage-timeline-structure-change"));
        });
        input.addEventListener("keydown", event => {
          if (event.key === "Enter" && !event.isComposing && event.keyCode !== 229) input.blur();
        });
        value.append(input, document.createTextNode(` ${tx("秒")}`));
        label.append(title, value);
        return label;
      };

      /* 転換は到着側シーンのデータだが、UIでは二つのシーンの間へ置く。
       * 選択中の上は「前→現在」、下は「現在→次」を同じ形で見せる。 */
      const makeSceneTransitionFrame = (fromScene, toScene, position) => {
        const frame = document.createElement("div");
        frame.className = `stage-scene-transition is-${position}`;
        frame.dataset.transitionFrom = fromScene.id;
        frame.dataset.transitionTo = toScene.id;
        frame.setAttribute("role", "group");
        frame.setAttribute("aria-label", `${tx("転換")}: ${fromScene.title} → ${toScene.title}`);

        /* R-23（2026-09-17 本人要望）: 「転換　◯◯ → △△」の行は消した。
         * すぐ上の見出し行に既に「転換」と出ていて重複していたため。
         * 同じ内容は読み上げ用に frame の aria-label（下）と転換メモの aria-label に残るので、
         * スクリーンリーダーからは失われない。 */

        const controls = document.createElement("div");
        controls.className = "stage-scene-transition-controls";

        if (SHOW_BLACKOUT_CONTROL && featureOn("blackout")) {
          const dark = document.createElement("label");
          dark.className = "stage-canvas-toggle stage-scene-transition-blackout";
          dark.title = tx("このシーンへの転換を、一度真っ暗にしてから明ける");
          const darkBox = document.createElement("input");
          darkBox.type = "checkbox";
          darkBox.checked = Boolean(toScene.blackout);
          darkBox.addEventListener("change", () => {
            checkpoint();
            toScene.blackout = darkBox.checked;
            persistSoon();
            announce(toScene.blackout ? "暗転で始まるシーンにしました。" : "暗転をやめました。");
          });
          const darkWord = document.createElement("span");
          darkWord.textContent = tx("暗転");
          dark.append(darkBox, darkWord);
          controls.append(dark);
        }

        if ((position === "outgoing" || position === "between") && featureOn("sceneTiming")) {
          const movement = makeRehearsalTimeInput(
            fromScene,
            "次のシーンへの移動時間",
            "transitionToNextSeconds",
          );
          movement.className = "stage-scene-transition-movement";
          controls.append(movement);
        }

        const noteLabel = document.createElement("label");
        noteLabel.className = "stage-scene-transition-note";
        const noteInput = document.createElement("textarea");
        noteInput.className = "stage-text-input";
        noteInput.rows = 1;
        noteInput.maxLength = 1000;
        noteInput.value = toScene.transitionNote || "";
        noteInput.placeholder = tx("演者・大道具・きっかけなど、この転換で行うこと");
        noteInput.setAttribute(
          "aria-label",
          `${tx("転換メモ")}: ${fromScene.title} → ${toScene.title}`,
        );
        const growTransitionNote = (preserveCurrent = false) => {
          const currentHeight = preserveCurrent ? noteInput.getBoundingClientRect().height : 0;
          const computed = getComputedStyle(noteInput);
          const borderHeight = parseFloat(computed.borderTopWidth) + parseFloat(computed.borderBottomWidth);
          noteInput.style.height = "0px";
          const contentHeight = noteInput.scrollHeight + borderHeight;
          noteInput.style.height = `${Math.max(46, currentHeight, contentHeight)}px`;
        };
        noteInput.addEventListener("input", () => {
          toScene.transitionNote = noteInput.value.slice(0, 1000);
          growTransitionNote(true);
          persistSoon();
        });
        noteLabel.append(noteInput);
        requestAnimationFrame(() => {
          growTransitionNote(false);
          requestAnimationFrame(() => growTransitionNote(false));
        });

        frame.append(controls, noteLabel);
        return frame;
      };

      /* タイムライン上の移動時間が0秒でも、隣り合うシーンの間には必ず境界がある。
       * 一覧では短い札を常設し、必要なときだけ既存の転換詳細を同じ場所へ開く。 */
      /* 転換の境界の中身を、渡された要素へ詰める。全再構築でも部分更新でも同じ手順を通す */
      const fillTransitionBoundary = (boundary, fromScene, toScene) => {
        boundary.replaceChildren();
        boundary.className = "stage-scene-transition-boundary";
        boundary.dataset.transitionFrom = fromScene.id;
        boundary.dataset.transitionTo = toScene.id;

        const point = document.createElement("button");
        point.type = "button";
        point.className = "stage-scene-transition-point";
        point.classList.toggle("is-current", timelinePanelTransition?.from === fromScene.id && timelinePanelTransition?.to === toScene.id);
        if (point.classList.contains("is-current")) point.setAttribute("aria-current", "true");
        const expandedBySetting = featureOn("sceneTransitions")
          && (fromScene.id === p.activeSceneId || toScene.id === p.activeSceneId);
        const expanded = expandedSceneTransitionToId === toScene.id || expandedBySetting;
        point.setAttribute("aria-expanded", String(expanded));
        point.setAttribute(
          "aria-label",
          `${tx("転換")}: ${fromScene.title} → ${toScene.title}`,
        );
        point.title = tx(expanded ? "転換の詳細を閉じる" : "転換の詳細を開く");

        const axis = document.createElement("span");
        axis.className = "stage-scene-transition-point-axis";
        axis.setAttribute("aria-hidden", "true");
        const kicker = document.createElement("span");
        kicker.className = "stage-scene-transition-point-kicker";
        kicker.textContent = tx("転換");
        const facts = [];
        if (toScene.blackout) facts.push(tx("暗転"));
        // 2026-10-11 本人指示: 転換メモがあっても行には「メモ」と出さない（「転換」だけ。メモは開いた中で読む）。
        const summary = document.createElement("span");
        summary.className = "stage-scene-transition-point-summary";
        summary.textContent = facts.join("・");
        point.append(axis, kicker, summary);
        point.addEventListener("click", () => {
          expandedSceneTransitionToId = expandedSceneTransitionToId === toScene.id
            ? null : toScene.id;
          const canPreview = state.animateScenes
            && !document.body.classList.contains("stage-session-guest");
          if (canPreview) {
            openScene(toScene.id, { transitionFromSceneId: fromScene.id });
          } else {
            renderScenes();
          }
          requestAnimationFrame(() => {
            const reopened = els.sceneList && els.sceneList.querySelector(
              `.stage-scene-transition-boundary[data-transition-to="${CSS.escape(toScene.id)}"] .stage-scene-transition-point`,
            );
            if (reopened) reopened.focus();
          });
        });

        boundary.append(point);
        if (expanded) boundary.append(makeSceneTransitionFrame(fromScene, toScene, "between"));
        return boundary;
      };
      const makeSceneTransitionPoint = (fromScene, toScene) => fillTransitionBoundary(document.createElement("div"), fromScene, toScene);

      /* i 番目の行の「上位セクション」。全再構築のループが積む sectionStack を、その行まで巻き戻して再現する */
      const rowAncestors = (index) => {
        const stack = [];
        let ancestors = [];
        for (let k = 0; k <= index; k += 1) {
          const item = p.scenes[k];
          stack.length = item.depth;
          ancestors = stack.slice();
          stack[item.depth] = item.kind === "section" ? item : null;
          stack.length = item.depth + 1;
        }
        return ancestors;
      };

      /* 行の中身を、渡された要素へ詰める。行そのものの生成と一覧への追加は呼び出し側 */
      const fillSceneRow = (row, scene, i, ancestors, numberText) => {
        row.replaceChildren();
        const isCursor = scene.id === (state.cursorRowId || p.activeSceneId);
        const isOpen = scene.kind === "scene" && scene.id === p.activeSceneId;

        row.className = `stage-scene-row${isOpen ? " is-open" : ""}${scene.id === wrapPickStartId ? " is-wrap-start" : ""}`;

        row.classList.toggle("is-cursor", isCursor);
        row.classList.toggle("is-timeline-transition", Boolean(timelinePanelTransition) && isOpen);
        row.dataset.sceneId = scene.id;
        row.dataset.depth = String(scene.depth);
        // 左端に空ける溝。バーはこの中へ、行の高さいっぱいに敷く
        const slots = scene.depth + (scene.kind === "section" ? 1 : 0);
        row.style.setProperty("--scene-gutter", `${slots * 14}px`);

        const head = document.createElement("div");
        head.className = "stage-scene-head";
        const bars = makeSceneBars(scene, ancestors);

        // 掴んで動かす取っ手。行そのものを掴むと中の編集ができなくなる
        const grip = document.createElement("span");
        grip.className = "stage-scene-grip";
        grip.textContent = "⠿";
        grip.setAttribute("aria-hidden", "true");
        grip.addEventListener("pointerdown", (e) => startSceneDrag(e, scene.id, row));

        const button = document.createElement("button");
        button.type = "button";
        button.setAttribute("data-contract-view", "");
        button.className = `stage-scene-chip${scene.kind === "section" ? " is-section" : ""}${isOpen ? " is-open" : ""}`;
        if (scene.kind === "section") button.style.setProperty("--section-color", sectionColor(scene));
        button.setAttribute("aria-pressed", String(isCursor));

        const num = document.createElement("span");
        num.className = "stage-scene-num";
        if (scene.kind === "section") {
          const shut = Boolean(state.closedSections[scene.id]);
          num.textContent = `${shut ? "▸" : "▾"} ${numberText}`;
          button.setAttribute("aria-expanded", String(!shut));
        } else {
          num.textContent = numberText;
        }

        const name = document.createElement("span");
        name.className = "stage-scene-name";
        if (scene.kind === "section") {
          const colorChip = document.createElement("i");
          colorChip.className = "stage-scene-section-color";
          colorChip.style.backgroundColor = sectionColor(scene);
          colorChip.setAttribute("aria-hidden", "true");
          name.append(colorChip, document.createTextNode(scene.title));
        } else {
          name.textContent = scene.title;
        }

        /* T-4（2026-09-17）: セクションのシーン数・シーンの物の数の表示を削除
         * （docs/ui-audit-2026-09-16/UI_REWORK_SPEC.md T-4。本人確認済み・情報自体を残す必要なし）。 */
        button.append(num, name);
        /* 名前はダブルクリックでも直せる。階層操作は常設せず補助メニューへまとめる。 */
        button.title = `${scene.title}／${tx(scene.kind === "section" ? "押すと開閉します" : "押すと開きます")}`;
        button.addEventListener("dblclick", (e) => {
          e.preventDefault();
          openRename(scene);
        });
        button.addEventListener("click", () => {
          if (wrapPickStartId) {
            finishWrapPick(scene.id);
            return;
          }
          if (scene.kind === "section") {
            const sectionIndex = p.scenes.indexOf(scene);
            const children = sceneChildren(sectionIndex);
            const firstScene = children.find((row) => row.kind === "scene");
            if (firstScene && !children.some((row) => row.id === p.activeSceneId)
                && !document.body.classList.contains("stage-session-guest")) {
              // 別の章を選んだら、その先頭シーンを表示し、畳まれた親も開く。
              let depth = firstScene.depth;
              for (let i = p.scenes.indexOf(firstScene) - 1; i >= sectionIndex && depth > scene.depth; i -= 1) {
                const ancestor = p.scenes[i];
                if (ancestor.depth >= depth) continue;
                if (ancestor.kind === "section") delete state.closedSections[ancestor.id];
                depth = ancestor.depth;
              }
              openScene(firstScene.id, { cursorRowId: scene.id });
              renderSceneGrid();
              focusSceneChip(scene.id);
              return;
            }
            if (state.cursorRowId === scene.id) {
              state.closedSections[scene.id] = !state.closedSections[scene.id];
            }
            state.cursorRowId = scene.id;
            renderScenes();
            renderSceneGrid();
            persistSoon();
            focusSceneChip(scene.id);
            return;
          }
          openSceneFromList(scene.id);
          focusSceneChip(scene.id);
        });
        head.append(grip, button);
        // 選択行には補助操作の入口を残す。セクションもキーボードから名前を編集できる。
        if (isCursor && !wrapPickStartId) {
          const more = document.createElement("details");
          more.className = "stage-scene-more";
          const summary = document.createElement("summary");
          summary.textContent = "…";
          summary.title = tx("その他のシーン操作");
          summary.setAttribute("aria-label", summary.title);
          const menu = document.createElement("div");
          menu.className = "stage-scene-more-menu";
          const menuButton = (label, action) => {
            const item = document.createElement("button");
            item.type = "button";
            item.textContent = tx(label);
            item.addEventListener("click", (event) => {
              event.stopPropagation();
              more.open = false;
              action();
            });
            menu.append(item);
            return item;
          };
          const outdent = menuButton("一段外へ出す", () => shiftSceneDepth(scene, -1));
          outdent.disabled = !canShiftSceneDepth(scene, -1);
          const indent = menuButton("一段内側へ入れる", () => shiftSceneDepth(scene, 1));
          indent.disabled = !canShiftSceneDepth(scene, 1);
          menuButton(scene.kind === "section" ? "名前を変える" : "シーンの詳細", () => openRename(scene, summary));
          menuButton("ここから範囲をまとめて新しいセクションにする", () => beginWrapPick(scene.id));
          if (scene.kind === "scene") {
            menuButton("次のシーンをつくる", () => openSceneCreate(scene, summary));
            const remove = menuButton("このシーンを削除", () => openSceneDelete(scene, summary));
            remove.disabled = p.scenes.filter((item) => item.kind === "scene").length <= 1;
          }
          more.addEventListener("keydown", (event) => {
            if (event.key !== "Escape" || !more.open) return;
            event.preventDefault(); event.stopPropagation();
            more.open = false; summary.focus();
          });
          more.append(summary, menu);
          head.append(more);
        }
        row.append(bars, head);
        if (scene.kind === "scene") {
          const info = sceneOverviewById(scene.id, overviewContext);
          if (info.cues.length || info.musicCues.length) row.append(sceneOverviewCueBadges(info));
        }


        if (editionAllows("formations") && RELEASE_FEATURES.formationSync && isCursor && scene.kind === "section" && !wrapPickStartId
            && !document.body.classList.contains("is-public")) {
          const entry = document.createElement("div");
          entry.className = "stage-section-formation-entry";
          if (formationSectionPlaybackItems(scene).length) {
            const play = document.createElement("button");
            play.type = "button";
            play.className = "stage-minor-action stage-section-sync-play";
            play.textContent = `▶ ${tx("舞台スケッチで再生")}`;
            play.title = tx("このセクションの音楽とシーンを最初から再生");
            play.addEventListener("click", () => { void playFormationSection(scene); });
            entry.append(play);
          }
          const open = document.createElement("button");
          open.type = "button"; open.className = "btn-quiet";
          // この入口は、未作成・作成済みの区別ではなく、音源と動きを扱う別アプリを開く操作として示す。
          open.textContent = tx("ミュージックシンクを開く");
          open.title = tx("このセクションのミュージックシンクを開く");
          open.addEventListener("click", () => openFormationModal(scene));
          entry.append(open); row.append(entry);
        }

        if (editionAllows("lightRender") && scene.kind === "scene" && scene.lightingIntent) {
          const lightSummary = document.createElement("div");
          lightSummary.className = "stage-scene-light-summary";
          const useEnglish = languageValue(() => true, () => false);
          lightSummary.textContent = lightingIntentSummary(scene.lightingIntent, useEnglish, 96);
          lightSummary.title = lightingIntentSummary(scene.lightingIntent, useEnglish, 220);
          row.append(lightSummary);
        }


        /* 開いているシーンだけ、名前とメモをその場で開く。
         * 閉じている行は名前だけ。並びを見渡すときに邪魔にならない。 */
        if (isOpen && scene.kind === "scene") {
          const body = document.createElement("div");
          body.className = "stage-scene-body";
          if (featureOn("sceneSubtitle") && scene.beat && scene.beat.role) {
            const beat = document.createElement("div");
            beat.className = "stage-scene-beat";
            const role = document.createElement("span");
            role.textContent = scene.beat.role;
            beat.append(role);
            body.append(beat);
          }
          const timing = document.createElement("div");
          timing.className = "stage-rehearsal-time-grid stage-scene-rehearsal-times";
          if (featureOn("sceneTiming")) {
            timing.append(makeRehearsalTimeInput(scene, "見せる時間", "holdDurationSeconds"));
          }
          const note = document.createElement("textarea");
          note.className = "stage-text-input stage-scene-note";
          note.rows = 2;
          note.maxLength = Math.max(2000, String(scene.note || "").length);
          note.autocomplete = "off";
          note.setAttribute("data-1p-ignore", "true");
          note.value = scene.note || "";
          note.placeholder = tm("misc", "sceneNoteHint", "このシーンのメモ（何が起きるか）");
          note.setAttribute("aria-label", tx("シーンのメモ"));
          /* 開いているのがいまのシーンなら、絵の上の欄と対になる。
             片方を打ったときに、もう片方だけを書き換えるための目印。 */
          if (scene.id === state.project.activeSceneId) note.id = "stage-scene-note-input";
          const growNote = (preserveCurrent = false) => {
            const currentHeight = preserveCurrent ? note.getBoundingClientRect().height : 0;
            const borderHeight = Math.max(0, note.offsetHeight - note.clientHeight);
            note.style.height = "0px";
            const contentHeight = note.scrollHeight + borderHeight;
            note.style.height = `${Math.ceil(Math.max(46, currentHeight, contentHeight))}px`;
          };
          trackSceneNoteUndo(note, () => scene);
          note.addEventListener("input", () => {
            scene.note = note.value;
            growNote(true);
            // 絵の上の「シーンの説明」も打ちながら追いかける
            if (scene.id === state.project.activeSceneId) {
              syncSceneDesc();
              if (presenting) render();
            }
            persistSoon();
          });
          const nextRow = document.createElement("div");
          nextRow.className = "stage-scene-next-row";
          const apply = document.createElement("button");
          apply.type = "button";
          apply.className = "btn-quiet stage-scene-apply";
          apply.textContent = tx("次のシーンをつくる");
          apply.title = tx("まっさらなシーン、または現在のシーンから引き継いだシーンを次に作ります");
          apply.addEventListener("click", () => openSceneCreate(scene, apply));
          const remove = document.createElement("button");
          remove.type = "button";
          remove.className = "btn-quiet stage-scene-row-delete";
          remove.innerHTML = squareGlyphSvg("close");
          remove.title = tx("このシーンを削除");
          remove.setAttribute("aria-label", tx("このシーンを削除"));
          remove.disabled = state.project.scenes.filter((row) => row.kind === "scene").length <= 1;
          remove.addEventListener("click", () => openSceneDelete(scene, remove));
          // ★2026-09-23 本人指示: 秒数欄は「次のシーンをつくる」の左に一列で並べる。
          if (timing.childElementCount) nextRow.append(timing);
          nextRow.append(apply, remove);
          body.append(note, nextRow);
          row.append(body);
          /* 行をDOMへ置き、幅と折り返しが確定した後に全文の高さを測る。
             次のフレームでもう一度測り、フォント適用直後の高さ差も拾う。 */
          requestAnimationFrame(() => {
            growNote(false);
            requestAnimationFrame(() => growNote(false));
          });
        }
      };

      /* ---- 部分更新：シーン切替で変わる行と、その前後の転換の境界だけ ---- */
      let updatedInPlace = false;
      if (activeChange && !wrapPickStartId) {
        const visibleIds = [];
        p.scenes.forEach((scene, i) => { if (!sceneHidden(i)) visibleIds.push(scene.id); });
        const renderedIds = [...els.sceneList.children]
          .filter((node) => node.dataset && node.dataset.sceneId)
          .map((node) => node.dataset.sceneId);
        const sameOrder = visibleIds.length === renderedIds.length
          && visibleIds.every((id, k) => id === renderedIds[k]);
        if (sameOrder) {
          const targets = new Set([
            activeChange.fromId, activeChange.toId, activeChange.cursorFromId, activeChange.cursorToId,
          ].filter(Boolean));
          p.scenes.forEach((scene, i) => {
            if (!targets.has(scene.id) || sceneHidden(i)) return;
            const row = els.sceneList.querySelector(`:scope > [data-scene-id="${CSS.escape(scene.id)}"]`);
            if (row) fillSceneRow(row, scene, i, rowAncestors(i), sceneNumbers.get(scene.id) || String(i + 1));
          });
          [...els.sceneList.children].forEach((node) => {
            if (!node.classList.contains("stage-scene-transition-boundary")) return;
            const fromId = node.dataset.transitionFrom;
            const toId = node.dataset.transitionTo;
            if (!targets.has(fromId) && !targets.has(toId)) return;
            const fromScene = p.scenes.find((item) => item.id === fromId);
            const toScene = p.scenes.find((item) => item.id === toId);
            if (fromScene && toScene) fillTransitionBoundary(node, fromScene, toScene);
          });
          updatedInPlace = true;
        }
      }

      /* ---- 全再構築（従来どおり） ---- */
      if (!updatedInPlace) {
        els.sceneList.innerHTML = "";
        p.scenes.forEach((scene, i) => {
          const numberText = sceneNumbers.get(scene.id) || String(i + 1);
          sectionStack.length = scene.depth;
          const ancestors = sectionStack.slice();
          sectionStack[scene.depth] = scene.kind === "section" ? scene : null;
          sectionStack.length = scene.depth + 1;
          if (sceneHidden(i)) return;
          const row = document.createElement("div");
          fillSceneRow(row, scene, i, ancestors, numberText);
          els.sceneList.append(row);
          if (scene.kind === "scene") {
            const next = nextSceneOf(scene);
            if (next) els.sceneList.append(makeSceneTransitionPoint(scene, next));
          }
        });
      }
      linkSceneBars();
      scheduleSceneBarLinks();
    }
    if (els.planDeriveRoute) {
      const current = sc();
      const next = nextSceneOf(current);
      els.planDeriveRoute.disabled = !next
        || (!movedPairs(current, next).length && !exitPieces(current, next).length);
    }
    if (els.projectTitle && document.activeElement !== els.projectTitle) els.projectTitle.value = p.title;
    if (els.versionLabel && document.activeElement !== els.versionLabel) els.versionLabel.value = p.versionLabel;
    syncProjectSummary();
    if (els.versionNote) {
      const bundled = Object.prototype.hasOwnProperty.call(BUNDLED_VERSION_NOTE_REASONS, p.id);
      els.versionNote.hidden = bundled;
      els.versionNote.textContent = bundled ? "" : p.parentVersionId
        ? (sx(`${p.branchReason || "別バージョンとして複製"}（元の版から派生）`, `${p.branchReason || "Duplicated as another version"} (derived from an earlier version)`))
        : (tx("このショーの最初の版です。"));
    }
    const idx = cursorIndex();
    renderSceneStudy();
    syncSceneBar();
    syncTabletSceneBar();
    syncPhoneViewer();
    syncSpinRun();
    /* 並べ替えと入れ子は、掴んで動かす方に一本化した。
     * 矢印のボタンは同じことを二通りに増やすだけなので置かない。 */
  }

  function stopSceneGridGeneration() {
    sceneGridGeneration += 1;
    if (sceneGridFrame) cancelAnimationFrame(sceneGridFrame);
    sceneGridFrame = 0;
  }

  /* 一枚を撮るあいだだけシーンと拡大を差し替える。途中で画像化に失敗しても、
   * いま編集している絵へ必ず戻す。 */
  function sceneGridThumbnail(scene, view) {
    const keepScene = state.project.activeSceneId;
    const keepHeight = H, keepPan = state.frontPan, keepPanY = state.frontPanY;
    // Both tabs use the same canonical thumbnail frame, independent of the
    // visible stage canvas height or the user's current front-view pan.
    H = BASE_H; state.frontPan = 0; state.frontPanY = 0;
    const keepAnim = sceneAnim;
    sceneAnim = null;
    const sceneIndex = state.project.scenes.findIndex(item => item.id === scene.id);
    const originalScene = state.project.scenes[sceneIndex];
    // Drawing resolves support heights and positions. Thumbnail previews must not
    // write those derived values into scenes the user has not edited.
    if (originalScene) state.project.scenes[sceneIndex] = stripTransientPieceFields({scenes:[projectIoClone(originalScene)]}).scenes[0];
    const keepFront = Object.assign({}, zoomState.front);
    const keepPlan = Object.assign({}, zoomState.plan);
    try {
      state.project.activeSceneId = scene.id;
      zoomState.front = { z: 1, ox: 0, oy: 0 };
      zoomState.plan = { z: 1, ox: 0, oy: 0 };
      const source = document.createElement("canvas");
      source.width = W;
      source.height = H;
      drawStage(source.getContext("2d"), false, view);
      const thumb = document.createElement("canvas");
      // カードをフェーダーで最大420pxまで広げられるため、拡大してもぼけない幅で撮る
      thumb.width = 480;
      thumb.height = Math.round((H / W) * thumb.width);
      thumb.getContext("2d").drawImage(source, 0, 0, thumb.width, thumb.height);
      return thumb.toDataURL("image/jpeg", 0.82);
    } finally {
      H = keepHeight; state.frontPan = keepPan; state.frontPanY = keepPanY;
      if (originalScene) state.project.scenes[sceneIndex] = originalScene;
      state.project.activeSceneId = keepScene;
      sceneAnim = keepAnim;
      zoomState.front = keepFront;
      zoomState.plan = keepPlan;
    }
  }

  function sceneGridThumbnailStamp(scene) {
    const staticScene = stripTransientPieceFields({scenes:[projectIoClone(scene)]}).scenes[0];
    return runOfShowSceneStamp(scene.id, runOfShowSharedStamp(), staticScene);
  }

  function cachedSceneGridThumbnail(scene, view) {
    const key = `${scene.id}:${view}`;
    const stamp = sceneGridThumbnailStamp(scene);
    const cached = sceneGridThumbs.get(key);
    if (cached?.stamp === stamp) return cached.src;
    const src = sceneGridThumbnail(scene, view);
    sceneGridThumbs.set(key, {stamp,src});
    return src;
  }

  function renderSceneGrid() {
    if (!els.sceneGrid || !els.sceneGridModal || els.sceneGridModal.hidden) return;
    stopSceneGridGeneration();
    const generation = sceneGridGeneration;
    els.sceneGrid.innerHTML = "";
    if (els.sceneGridFront) els.sceneGridFront.setAttribute("aria-pressed", String(sceneGridView === "front"));
    if (els.sceneGridPlan) els.sceneGridPlan.setAttribute("aria-pressed", String(sceneGridView === "plan"));
    const numbers = sceneNumberMap(state.project.scenes);
    const overviewContext = createSceneOverviewContext(numbers);
    const jobs = [];

    state.project.scenes.forEach((scene, index) => {
      const numberText = numbers.get(scene.id) || String(index + 1);
      if (sceneHiddenIn(state.project.scenes, index)) return;
      if (scene.kind === "section") {
        const heading = document.createElement("h3");
        heading.className = "stage-scene-grid-section";
        heading.style.setProperty("--scene-indent", `${8 + scene.depth * 14}px`);
        heading.style.setProperty("--section-color", sectionColor(scene));
        const shut = Boolean(state.closedSections[scene.id]);
        const toggle = document.createElement("button");
        toggle.type = "button";
        toggle.className = "stage-scene-grid-section-button";
        toggle.setAttribute("aria-expanded", String(!shut));
        toggle.title = tx("押すと開閉します");
        const title = document.createElement("span");
        title.textContent = `${shut ? "▸" : "▾"} ${numberText} ${scene.title}`.trim();
        const totals = document.createElement("span");
        totals.className = "stage-scene-grid-section-total";
        totals.textContent = sectionSummary(sectionTotals(index), "grid");
        toggle.append(title, totals);
        toggle.addEventListener("click", () => {
          state.closedSections[scene.id] = !state.closedSections[scene.id];
          renderSceneGrid();
          renderScenes();
          persistSoon();
        });
        heading.append(toggle);
        els.sceneGrid.append(heading);
        return;
      }

      const card = document.createElement("button");
      card.type = "button";
      card.dataset.sceneId = scene.id;
      card.className = `stage-scene-grid-card stage-scene-overview-card${scene.id === state.project.activeSceneId ? " is-current" : ""}`;
      card.setAttribute("aria-label", sx(`${numberText} ${scene.title}、配置 ${scene.pieces.length}、開く`, `Open ${numberText} ${scene.title}, ${scene.pieces.length} placed`));
      card.addEventListener("click", () => {
        openScene(scene.id);
        closeSceneGrid();
      });

      const picture = document.createElement("span");
      picture.className = "stage-scene-grid-thumb";
      const image = document.createElement("img");
      image.alt = "";
      image.hidden = true;
      picture.append(image);

      const caption = document.createElement("span");
      caption.className = "stage-scene-grid-caption";
      const title = document.createElement("strong");
      const overview = sceneOverviewById(scene.id, overviewContext);
      title.textContent = `${tx("シーン")} ${overview.number} ${overview.name}`;
      title.title = title.textContent;
      caption.append(title, sceneOverviewCueBadges(overview));
      card.append(picture, caption);
      els.sceneGrid.append(card);

      const key = `${scene.id}:${sceneGridView}`;
      const cached = sceneGridThumbs.get(key);
      if (cached?.stamp === sceneGridThumbnailStamp(scene)) {
        image.src = cached.src;
        image.hidden = false;
      } else {
        jobs.push({ scene, view: sceneGridView, key, image });
      }
    });

    let at = 0;
    const drawChunk = () => {
      if (generation !== sceneGridGeneration || els.sceneGridModal.hidden) return;
      const end = Math.min(at + 3, jobs.length);
      while (at < end) {
        const job = jobs[at];
        at += 1;
        try {
          const src = cachedSceneGridThumbnail(job.scene, job.view);
          if (generation === sceneGridGeneration && job.image.isConnected) {
            job.image.src = src;
            job.image.hidden = false;
          }
        } catch (_) {
          // 一枚が画像化できなくても、空枠のまま残して次のシーンへ進む
        }
      }
      if (at < jobs.length) sceneGridFrame = requestAnimationFrame(drawChunk);
      else sceneGridFrame = 0;
    };
    if (jobs.length) sceneGridFrame = requestAnimationFrame(drawChunk);
  }

  // カードの列幅。全画面字幕サイズと同じく prefs に覚えさせる
  function applySceneGridSize() {
    const size = clamp(finite(prefs.sceneGridSize, 220), 150, 420);
    if (els.sceneGrid) els.sceneGrid.style.setProperty("--scene-grid-size", `${size}px`);
    if (els.sceneGridSize) els.sceneGridSize.value = String(size);
  }

  /* 機能一覧「端末による違い」（旧称「どこで何ができるか」）。幅が要る資料なので窓で開く。
     以前は保存パネルの中に畳んで入れていたが、側柱が268pxしかなく
     列見出しが「ブ／ラ／ウ／ザ」と縦積みになって読めなかった（2026-08-25）。 */
  function openReachTable() {
    if (!els.reachModal || !els.reachBackdrop) return;
    els.reachModal.hidden = false;
    els.reachBackdrop.hidden = false;
    if (els.reachClose) els.reachClose.focus();
  }

  function closeReachTable() {
    if (els.reachModal) els.reachModal.hidden = true;
    if (els.reachBackdrop) els.reachBackdrop.hidden = true;
    if (els.reachOpen) els.reachOpen.focus();
  }

  const sceneCreateGroup = (piece) => (piece && piece.type === "performer"
    ? "performer"
    : (piece && piece.type === "light"
      ? "light"
      : (piece && piece.type === "prop" ? "prop" : "set")));

  function sceneCreateGroupLabel(group) {
    if (group === "performer") return tx("すべての演者");
    if (group === "prop") return tx("すべての小道具");
    if (group === "light") return tx("すべての照明");
    return tx("すべての大道具");
  }

  function sceneCreateGroupIcon(group) {
    const icons = {
      performer: '<circle cx="12" cy="7" r="3"></circle><path d="M5 21v-2a7 7 0 0 1 14 0v2M12 10v6M8.5 13h7"></path>',
      set: '<path d="m4 8 8-4 8 4-8 4-8-4Zm0 0v8l8 4 8-4V8M12 12v8"></path>',
      prop: '<rect x="4" y="8" width="16" height="11" rx="1"></rect><path d="M9 8V5h6v3M8 12v3M16 12v3M4 13h16"></path>',
      light: '<path d="M8 4h8l-1 8H9L8 4Zm4 8v5M8 20h8M4 7H2M22 7h-2M5 2 3.5.5M19 2l1.5-1.5"></path>',
    };
    const icon = document.createElement("span");
    icon.className = "stage-scene-create-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" focusable="false">${icons[group] || icons.set}</svg>`;
    return icon;
  }

  function sceneCreateSourceScene() {
    return sceneCreateSourceId
      ? state.project.scenes.find((row) => row.id === sceneCreateSourceId && row.kind === "scene")
      : null;
  }

  function syncSceneCreateSelection() {
    const source = sceneCreateSourceScene();
    const pieces = source ? (source.pieces || []) : [];
    sceneCreateItemInputs.forEach((input, id) => { input.checked = sceneCreateSelection.has(id); });
    sceneCreateGroupInputs.forEach((input, group) => {
      const groupPieces = pieces.filter((piece) => sceneCreateGroup(piece) === group);
      const checked = groupPieces.filter((piece) => sceneCreateSelection.has(piece.id)).length;
      input.checked = Boolean(groupPieces.length) && checked === groupPieces.length;
      input.indeterminate = checked > 0 && checked < groupPieces.length;
    });
    if (els.sceneCreateCount) {
      els.sceneCreateCount.textContent = sx(
        `${sceneCreateSelection.size} / ${pieces.length} 選択中`,
        `${sceneCreateSelection.size} / ${pieces.length} selected`,
      );
    }
    if (els.sceneCreateSubmit) {
      els.sceneCreateSubmit.disabled = !sceneCreateMode
        || (sceneCreateMode === "inherit" && sceneCreateSelection.size < 1);
    }
  }

  function renderSceneCreateList() {
    if (!els.sceneCreateList) return;
    els.sceneCreateList.innerHTML = "";
    sceneCreateGroupInputs.clear();
    sceneCreateItemInputs.clear();
    const source = sceneCreateSourceScene();
    const pieces = source ? (source.pieces || []) : [];
    ["performer", "set", "prop", "light"].forEach((group) => {
      const members = pieces.filter((piece) => sceneCreateGroup(piece) === group);
      if (!members.length) return;
      const block = document.createElement("section");
      block.className = "stage-scene-create-group";
      const heading = document.createElement("label");
      heading.className = "stage-scene-create-group-head";
      const groupInput = document.createElement("input");
      groupInput.type = "checkbox";
      groupInput.addEventListener("change", () => {
        members.forEach((piece) => {
          if (groupInput.checked) sceneCreateSelection.add(piece.id);
          else sceneCreateSelection.delete(piece.id);
        });
        syncSceneCreateSelection();
      });
      sceneCreateGroupInputs.set(group, groupInput);
      const title = document.createElement("strong");
      title.textContent = sceneCreateGroupLabel(group);
      const total = document.createElement("small");
      total.textContent = sx(`${members.length}点`, `${members.length} items`);
      heading.append(groupInput, sceneCreateGroupIcon(group), title, total);
      const list = document.createElement("div");
      list.className = "stage-scene-create-items";
      members.forEach((piece) => {
        const row = document.createElement("label");
        row.className = "stage-scene-create-item";
        const input = document.createElement("input");
        input.type = "checkbox";
        input.value = piece.id;
        input.addEventListener("change", () => {
          if (input.checked) sceneCreateSelection.add(piece.id);
          else sceneCreateSelection.delete(piece.id);
          syncSceneCreateSelection();
        });
        sceneCreateItemInputs.set(piece.id, input);
        const words = document.createElement("span");
        const name = document.createElement("strong");
        name.textContent = pieceLabel(piece);
        const kind = document.createElement("small");
        kind.textContent = piece.route
          ? sx(`${pieceTypeName(piece.type)}・動線の先へ移動`, `${pieceTypeName(piece.type)} · moves to route end`)
          : pieceTypeName(piece.type);
        words.append(name, kind);
        row.append(input, sceneCreateGroupIcon(group), words);
        list.append(row);
      });
      block.append(heading, list);
      els.sceneCreateList.append(block);
    });
    syncSceneCreateSelection();
  }

  function setSceneCreateMode(mode) {
    sceneCreateMode = mode === "inherit" ? "inherit" : (mode === "blank" ? "blank" : null);
    if (els.sceneCreateBlank) els.sceneCreateBlank.checked = sceneCreateMode === "blank";
    if (els.sceneCreateInherit) els.sceneCreateInherit.checked = sceneCreateMode === "inherit";
    if (els.sceneCreateInheritOptions) els.sceneCreateInheritOptions.hidden = sceneCreateMode !== "inherit";
    syncSceneCreateSelection();
  }

  function openSceneCreate(scene, returnFocus) {
    if (window.GAMMA_UI.layers.isOpen(els.sceneCreateModal)) return;
    if (!scene || scene.kind !== "scene" || !els.sceneCreateModal || !els.sceneCreateBackdrop) return;
    sceneCreateSourceId = scene.id;
    sceneCreateMode = null;
    sceneCreateReturnFocus = returnFocus || null;
    sceneCreateSelection.clear();
    (scene.pieces || []).forEach((piece) => sceneCreateSelection.add(piece.id));
    if (els.sceneCreateSource) {
      els.sceneCreateSource.textContent = sx(
        `「${scene.title}」の次に作ります。`,
        `The new scene will follow “${scene.title}”.`,
      );
    }
    const hasPieces = Boolean((scene.pieces || []).length);
    if (els.sceneCreateInherit) els.sceneCreateInherit.disabled = !hasPieces;
    if (els.sceneCreateMoveRoutes) els.sceneCreateMoveRoutes.checked = true;
    renderSceneCreateList();
    setSceneCreateMode(hasPieces ? "inherit" : "blank");
    els.sceneCreateModal.hidden = false;
    els.sceneCreateBackdrop.hidden = false;
    const initialChoice = hasPieces ? els.sceneCreateInherit : els.sceneCreateBlank;
    if (initialChoice) initialChoice.focus();
  }

  function closeSceneCreate() {
    if (els.sceneCreateModal) els.sceneCreateModal.hidden = true;
    if (els.sceneCreateBackdrop) els.sceneCreateBackdrop.hidden = true;
    const target = sceneCreateReturnFocus;
    sceneCreateSourceId = null;
    sceneCreateMode = null;
    sceneCreateReturnFocus = null;
    sceneCreateSelection.clear();
    sceneCreateGroupInputs.clear();
    sceneCreateItemInputs.clear();
    if (target && target.isConnected && typeof target.focus === "function") target.focus();
  }

  function openSceneGrid() {
    if (!els.sceneGridModal || !els.sceneGridBackdrop) return;
    sceneGridThumbs.clear();
    applySceneGridSize();
    els.sceneGridModal.hidden = false;
    els.sceneGridBackdrop.hidden = false;
    renderSceneGrid();
    if (els.sceneGridClose) els.sceneGridClose.focus();
  }

  function closeSceneGrid() {
    stopSceneGridGeneration();
    if (els.sceneGridModal) els.sceneGridModal.hidden = true;
    if (els.sceneGridBackdrop) els.sceneGridBackdrop.hidden = true;
  }

  function setSceneGridView(view) {
    const next = view === "plan" ? "plan" : "front";
    if (sceneGridView === next) return;
    sceneGridView = next;
    renderSceneGrid();
  }

  /* 行の名前をその場で書き換える。
   * 入力欄はボタンの外へ出す。ボタンの中へ入れると、押した先がボタンに
   * 吸われて文字を打てない（実際それで動かなかった）。 */
  /* 名前を変える小窓。シーンにもセクションにも同じものを使う。 */
  let renameTarget = null;
  let renameReturnFocus = null;
  // Search navigation suspends this editor only; never writes a draft into a show.
  const renameSearchDrafts = new WeakMap();
  const renameDraftFields = ["renameInput", "renameSubtitle", "renameSceneNote", "renameSectionNote"];
  const renameDraftKey = scene => JSON.stringify([scene.id, sceneAlternatives?.current(scene)?.id || ""]);
  const renameDraftValues = () => Object.fromEntries(renameDraftFields.filter(name => els[name]).map(name => [name, els[name].value]));
  let renameEditBaseline = null, renameDraftConflicts = {}, renameDraftConflictPanel = null;
  hasPendingRenameDrafts = () => {
    if (renameSearchDrafts.get(state.project)?.size) return true;
    if (!renameTarget || !els.rename || els.rename.hidden) return false;
    return Object.keys(renameDraftConflicts).length > 0
      || Object.entries(renameDraftValues()).some(([name, value]) => value !== renameEditBaseline?.[name]);
  };
  function transferRenameSearchDrafts(previousProject, restoredProject) {
    if (!previousProject || !restoredProject || previousProject.id !== restoredProject.id) return;
    const drafts = renameSearchDrafts.get(previousProject);
    if (drafts) renameSearchDrafts.set(restoredProject, drafts);
  }
  function setRenameDraftValue(name, value) {
    if (!els[name]) return;
    els[name].value = value;
    if (name === "renameSceneNote" || name === "renameSectionNote") els[name].maxLength = Math.max(2000, value.length);
  }
  function renderRenameDraftConflicts() {
    renameDraftConflictPanel?.remove(); renameDraftConflictPanel = null;
    const entries = Object.entries(renameDraftConflicts);
    if (!entries.length) return;
    const panel = document.createElement("section");
    const message = tm("misc", "sceneSearchDraftConflict", "別の場所で内容が変わったため、現在の内容を表示しています。下書きの控えはここで確認できます。");
    const notice = document.createElement("p"); notice.className = "stage-profile-hint"; notice.textContent = message;
    notice.setAttribute("role", "status"); panel.append(notice);
    const labels = { renameInput: "名前", renameSubtitle: "サブタイトル", renameSceneNote: "シーンの説明", renameSectionNote: "メモ" };
    for (const [name, draft] of entries) {
      const label = document.createElement("label"); label.className = "stage-control-label"; label.textContent = tx(labels[name]);
      const copy = document.createElement("textarea"); copy.className = "stage-text-input"; copy.rows = 3; copy.readOnly = true;
      copy.value = draft.value; copy.autocomplete = "off"; copy.setAttribute("data-1p-ignore", "true");
      copy.setAttribute("aria-label", tx(labels[name])); label.append(copy); panel.append(label);
      const use = document.createElement("button"); use.type = "button"; use.className = "stage-minor-action";
      use.textContent = tm("misc", "sceneSearchDraftUse", "この下書きを入力欄へ戻す");
      use.addEventListener("click", () => {
        setRenameDraftValue(name, draft.value); delete renameDraftConflicts[name];
        renderRenameDraftConflicts(); els[name]?.focus();
      });
      panel.append(use);
    }
    if (els.renameOk) els.renameOk.before(panel); else els.rename.append(panel);
    renameDraftConflictPanel = panel;
    announce(message);
  }
  function suspendRenameForSearch() {
    if (!renameTarget || !els.rename || els.rename.hidden) return false;
    const project = state.project, key = renameDraftKey(renameTarget), values = {}, base = {};
    for (const [name, value] of Object.entries(renameDraftValues())) {
      if (value !== renameEditBaseline?.[name]) { values[name] = value; base[name] = renameEditBaseline?.[name]; }
      else if (renameDraftConflicts[name]) { values[name] = renameDraftConflicts[name].value; base[name] = renameDraftConflicts[name].base; }
    }
    closeRename();
    if (Object.keys(values).length) {
      let drafts = renameSearchDrafts.get(project);
      if (!drafts) renameSearchDrafts.set(project, drafts = new Map());
      drafts.set(key, { values, base });
    }
    return true;
  }

  function updateRenameColorSummary(scene) {
    if (!scene || scene.kind !== "section") return;
    const explicitIndex = SECTION_COLORS.indexOf(scene.color);
    const label = explicitIndex < 0 ? "自動" : `色 ${explicitIndex + 1}`;
    if (els.renameColorPreview) els.renameColorPreview.style.backgroundColor = sectionColor(scene);
    if (els.renameColorValue) els.renameColorValue.textContent = tx(label);
    if (els.renameColorSummary) {
      els.renameColorSummary.setAttribute("aria-label", `${tx("色を選ぶ")}: ${tx(label)}`);
    }
  }

  /* ---- R-25（2026-09-17 本人要望）: そのシーンの顔ぶれを1件ぶん組み立てる ----
   * 本人の意図: 「後にキューシートにつなげるため、キューシートの一部という形のイメージ」。
   * そのため読める文章ではなく**項目と値**で返し、モーダルの中に直接書かない。
   * こうしておけば、後でショー全体ぶんを並べたり書き出したりするときに同じものを使える。
   *
   * ★ここは引数の scene を見る。sc()（いま開いているシーン）ではない。
   *   詳細の窓は別のシーンを指しても開けるので、sc() を使うと
   *   どのシーンを開いても現在のシーンの顔ぶれが出てしまう。
   *
   * 舞台裏の定義は本人決定（2026-09-17）:「名簿に居るが、このシーンに出ていない人」。
   * 駒が舞台の枠の外にあるかどうか（onStageArea）は見ない。 */
  function sceneCastFacts(scene) {
    const pieces = (scene && Array.isArray(scene.pieces) ? scene.pieces : [])
      .filter((piece) => piece && piece.type !== "light");
    const onStage = [];
    const sets = [];
    const props = [];
    const held = [];
    const byId = new Map(pieces.map((piece) => [piece.id, piece]));
    pieces.forEach((piece) => {
      const name = pieceLabel(piece);
      if (piece.type === "performer") { onStage.push(name); return; }
      const registered = pieceSet(piece);
      if (registered && registered.kind === "prop") props.push(name);
      else sets.push(name);
    });
    // 「誰が何を持っているか」。持たれる側（小道具など）が heldBy で演者の駒を指している。
    pieces.forEach((piece) => {
      if (!piece.heldBy) return;
      const owner = byId.get(piece.heldBy);
      if (!owner) return;
      held.push(`${pieceLabel(owner)}: ${pieceLabel(piece)}`);
    });
    const castOut = (state.project.cast || [])
      .filter((member) => !pieces.some((piece) => piece.castId === member.id))
      .map((member) => member.name);
    const sortJa = (list) => [...list].sort((a, b) => String(a).localeCompare(String(b), "ja"));
    return { onStage: sortJa(onStage), backstage: sortJa(castOut), sets: sortJa(sets), props: sortJa(props), held };
  }

  /* 上の事実を「3件（名前, 名前, 名前）」の形の1行にする。多いときは件数だけ先に出す。 */
  function castFactLine(list, unit = "件") {
    if (!list.length) return "—";
    const head = list.slice(0, 8).join("、");
    return list.length > 8 ? `${list.length}${unit}: ${head} ほか` : `${list.length}${unit}: ${head}`;
  }

  function openRename(scene, returnTo = document.activeElement) {
    if (window.GAMMA_UI.layers.isOpen(els.rename)) return;
    if (!scene || !els.rename) return;
    renameReturnFocus = returnTo;
    renameTarget = scene;
    const runRecordsButton = document.getElementById("stage-scene-run-records");
    if (runRecordsButton) { runRecordsButton.hidden = window.GAMMA_EDITION === "lite" || scene.kind !== "scene"; runRecordsButton.onclick = () => window.GAMMA_FIELD_RUNS?.review(scene.id); }
    els.renameTitle.textContent = tx(scene.kind === "section" ? "セクションの詳細" : "シーンの詳細");
    els.renameInput.value = scene.title;
    if (els.renameSectionFields) els.renameSectionFields.hidden = scene.kind !== "section";
    if (els.renameSectionNote) {
      els.renameSectionNote.value = scene.kind === "section" ? String(scene.note || "") : "";
      els.renameSectionNote.maxLength = Math.max(2000, els.renameSectionNote.value.length);
    }
    if (els.renameSceneFields) els.renameSceneFields.hidden = scene.kind !== "scene";
    const timecodeOriginButton = document.getElementById("stage-scene-timecode-origin");
    if (timecodeOriginButton) timecodeOriginButton.onclick = () => {
      window.dispatchEvent(new CustomEvent("stage-timecode-origin-edit", { detail: { sceneId: scene.id } }));
    };
    const timelineFacts = scene.kind === "scene"
      && window.SHOSAI_STAGE_TIMELINE_DETAILS
      && typeof window.SHOSAI_STAGE_TIMELINE_DETAILS.sceneFactsById === "function"
      ? window.SHOSAI_STAGE_TIMELINE_DETAILS.sceneFactsById(scene.id) : null;
    if (els.renameSceneNumber) els.renameSceneNumber.textContent = timelineFacts && timelineFacts.sceneNumber || "—";
    if (els.renameSceneSection) els.renameSceneSection.textContent = timelineFacts && timelineFacts.section || "—";
    if (els.renameScenePosition) {
      const el=els.renameScenePosition;el.textContent=timelineFacts && timelineFacts.position || '—';
      el.setAttribute('role','button');el.tabIndex=0;el.setAttribute('aria-label',tx('開始位置の設定を開く'));
      el.onclick=()=>{closeRename();window.dispatchEvent(new CustomEvent('stage-timecode-origin-edit',{detail:{sceneId:scene.id}}));};
      el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};
    }
    if (els.renameSceneHold) els.renameSceneHold.textContent = timelineFacts && timelineFacts.hold || "—";
    if (els.renameSceneTransition) els.renameSceneTransition.textContent = timelineFacts && timelineFacts.transition || "—";
    /* R-25: そのシーンの顔ぶれ。セクションでは出さない（本人決定で対象外）。 */
    if (els.renameSceneCast) els.renameSceneCast.hidden = scene.kind !== "scene";
    if (scene.kind === "scene") {
      const facts = sceneCastFacts(scene);
      if (els.renameSceneOnStage) els.renameSceneOnStage.textContent = castFactLine(facts.onStage, "人");
      if (els.renameSceneBackstage) els.renameSceneBackstage.textContent = castFactLine(facts.backstage, "人");
      if (els.renameSceneSets) els.renameSceneSets.textContent = castFactLine(facts.sets);
      if (els.renameSceneProps) els.renameSceneProps.textContent = castFactLine(facts.props);
      if (els.renameSceneHeld) els.renameSceneHeld.textContent = facts.held.length ? facts.held.join(" / ") : "—";
    }
    if (els.renameSubtitle) els.renameSubtitle.value = scene.kind === "scene"
      ? normalizeBeat(scene.beat).role : "";
    if (els.renameSceneNote) {
      els.renameSceneNote.value = scene.kind === "scene" ? String(scene.note || "") : "";
      els.renameSceneNote.maxLength = Math.max(2000, els.renameSceneNote.value.length);
    }
    if (els.renameOk) {
      els.renameOk.textContent = tx(scene.kind === "section" ? "保存する" : "変更を保存");
    }
    if (els.renameColors) els.renameColors.hidden = scene.kind !== "section";
    if (els.renameColorPicker) els.renameColorPicker.open = false;
    if (els.renameDelete) els.renameDelete.hidden = scene.kind !== "section";
    if (els.renameSwatches) {
      els.renameSwatches.innerHTML = "";
      if (scene.kind === "section") {
        const choices = [{ color: null, label: "自動" },
          ...SECTION_COLORS.map((color, index) => ({ color, label: `色 ${index + 1}` }))];
        choices.forEach((choice) => {
          const swatch = document.createElement("button");
          swatch.type = "button";
          swatch.className = `stage-rename-swatch${choice.color === null ? " is-auto" : ""}`;
          swatch.setAttribute("aria-label", tx(choice.label));
          swatch.setAttribute("aria-pressed", String(choice.color === null
            ? scene.color === null : sectionColor(scene) === choice.color));
          if (choice.color === null) {
            swatch.textContent = tx("自動");
            swatch.title = tx("idから決まる既定の色に戻す");
          } else {
            swatch.style.backgroundColor = choice.color;
          }
          swatch.addEventListener("click", () => {
            if (!renameTarget || renameTarget.kind !== "section") return;
            checkpoint();
            renameTarget.color = choice.color;
            els.renameSwatches.querySelectorAll(".stage-rename-swatch").forEach((button) => {
              button.setAttribute("aria-pressed", String(button === swatch));
            });
            updateRenameColorSummary(renameTarget);
            if (els.renameColorPicker) els.renameColorPicker.open = false;
            renderScenes();
            renderSceneGrid();
            persistSoon();
          });
          els.renameSwatches.append(swatch);
        });
        updateRenameColorSummary(scene);
      }
    }
    renameEditBaseline = renameDraftValues();
    renameDraftConflicts = {};
    const searchDraft = renameSearchDrafts.get(state.project)?.get(renameDraftKey(scene));
    if (searchDraft) for (const [name, value] of Object.entries(searchDraft.values)) {
      if (renameEditBaseline[name] === searchDraft.base[name] || renameEditBaseline[name] === value) setRenameDraftValue(name, value);
      else renameDraftConflicts[name] = { value, base: searchDraft.base[name] };
    }
    renderRenameDraftConflicts();
    els.rename.hidden = false;
    els.renameBackdrop.hidden = false;
    els.renameInput.focus();
    els.renameInput.select();
  }

  function closeRename() {
    const returnTo = renameReturnFocus, sceneId = renameTarget?.id;
    renameReturnFocus = null;
    if (renameTarget) renameSearchDrafts.get(state.project)?.delete(renameDraftKey(renameTarget));
    renameDraftConflictPanel?.remove(); renameDraftConflictPanel = null;
    renameDraftConflicts = {}; renameEditBaseline = null;
    renameTarget = null;
    if (!els.rename) return;
    els.rename.hidden = true;
    els.renameBackdrop.hidden = true;
    requestAnimationFrame(() => {
      if (returnTo?.isConnected && returnTo.getClientRects().length) returnTo.focus({ preventScroll: true });
      else if (sceneId) focusSceneChip(sceneId);
    });
  }

  function commitRename() {
    if (!renameTarget) return;
    const next = els.renameInput.value.trim().slice(0, 40);
    const titleChanged = Boolean(next && next !== renameTarget.title);
    const currentBeat = normalizeBeat(renameTarget.beat);
    const nextBeat = renameTarget.kind === "scene" ? normalizeBeat({
      ...currentBeat,
      role: els.renameSubtitle ? els.renameSubtitle.value.trim().slice(0, 160) : currentBeat.role,
    }) : currentBeat;
    const beatChanged = renameTarget.kind === "scene"
      && nextBeat.role !== currentBeat.role;
    const currentSectionNote = renameTarget.kind === "section" ? String(renameTarget.note || "") : "";
    const nextSectionNote = renameTarget.kind === "section" && els.renameSectionNote
      ? els.renameSectionNote.value : currentSectionNote;
    const sectionNoteChanged = renameTarget.kind === "section" && nextSectionNote !== currentSectionNote;
    const currentSceneNote = renameTarget.kind === "scene" ? String(renameTarget.note || "") : "";
    const nextSceneNote = renameTarget.kind === "scene" && els.renameSceneNote
      ? els.renameSceneNote.value : currentSceneNote;
    const sceneNoteChanged = renameTarget.kind === "scene" && nextSceneNote !== currentSceneNote;
    if (titleChanged || beatChanged || sectionNoteChanged || sceneNoteChanged) {
      checkpoint();
      if (titleChanged) renameTarget.title = next;
      if (beatChanged) renameTarget.beat = nextBeat;
      if (sectionNoteChanged) renameTarget.note = nextSectionNote;
      if (sceneNoteChanged) renameTarget.note = nextSceneNote;
      renderScenes();
      renderSceneGrid();
      persistSoon();
    }
    closeRename();
  }

  if (els.renameOk) els.renameOk.addEventListener("click", commitRename);
  if (els.renameDelete) {
    els.renameDelete.addEventListener("click", () => {
      if (!renameTarget || renameTarget.kind !== "section") return;
      const target = renameTarget;
      closeRename();
      openSceneDelete(target);
    });
  }
  if (els.renameClose) els.renameClose.addEventListener("click", closeRename);
