  // A backpack follows the torso; its straps wrap over both shoulders to the palms.
  function backpackWalkingPose(pose,piece,pieces) {
    if(String(pose.id).replace(LEFT_HAND_SUFFIX,"")!=="backpack_walk")return pose;
    const bag=pieces.find(p=>p.heldBy===piece.id&&p.type==="prop"&&propShapeOf(p)==="backpack"&&p.holdMode!=="face");
    if(!bag)return pose;
    const H=pieceHeightM(piece)*piece.size/100,dims=pieceDims(bag),motion=window.STAGE_PERFORMER_MOTION,st=motion.standard;
    const j={},dist=(a,b)=>Math.hypot(...a.map((v,i)=>v-b[i])),sin=.20,cos=Math.sqrt(1-sin*sin);
    const directions={L:norm3([0,1,.25]),R:norm3([0,1,.25])},palms={};
    for(const [side,sign] of [["L",-1],["R",1]]) {
      j["hip"+side]=[sign*.055,.49,0];j["sh"+side]=[sign*.1075,.49+.30*cos,.30*sin];
      const leg=motion.twoBone(j["hip"+side],side==="L"?[-.065,.07,-.13]:[.065,.04,.16],dist(st["hip"+side],st["kn"+side]),dist(st["kn"+side],st["an"+side]),[sign*.1,0,1]);
      j["kn"+side]=leg.joint;j["an"+side]=leg.end;j["to"+side]=[leg.end[0],.012,leg.end[2]+(side==="L"?.065:.075)];
      palms[side]=[sign*.085,.695,.143];
      const wrist=palms[side].map((v,i)=>v-directions[side][i]*.0341);
      const arm=motion.twoBone(j["sh"+side],wrist,dist(st["sh"+side],st["el"+side]),dist(st["el"+side],st["wr"+side]),[0,-1,-.1]);
      j["el"+side]=arm.joint;j["wr"+side]=arm.end;
    }
    j.neck=[0,j.shL[1]+.035,.068];j.head=[0,j.neck[1]+.08*Math.sqrt(.99),.076];
    const back=.055+.09*(dims.d/.18)/H;
    const mesh={kind:"mesh",c:[0,.49+.065*cos+back*sin,.065*sin-back*cos],axes:[[-dims.w/.30/H,0,0],[0,cos*dims.h/.42/H,sin*dims.h/.42/H],[0,sin*dims.d/.18/H,-cos*dims.d/.18/H]],
      groups:[{color:bag.color||"#60867a",parts:PROP_SHAPES.backpack.parts}]};
    const world=p=>mesh.c.map((v,i)=>v+mesh.axes.reduce((sum,a,k)=>sum+a[i]*p[k],0));
    const straps=[];
    for(const [side,sign] of [["L",-1],["R",1]]) {
      const path=[world([-sign*.09,.34,-.09]),[sign*.085,j.shL[1]+.017,.035],[sign*.085,j.shL[1]+.009,.092],
        [sign*.085,.75,.137],palms[side],[sign*.10,.60,.109],[sign*.112,.59,.015],world([-sign*.09,.065,-.09])];
      const sample=(segment,t)=>{
        const a=path[Math.max(0,segment-1)],b=path[segment],c=path[segment+1],d=path[Math.min(path.length-1,segment+2)];
        return b.map((v,i)=>.5*((2*v)+(-a[i]+c[i])*t+(2*a[i]-5*v+4*c[i]-d[i])*t*t+(-a[i]+3*v-3*c[i]+d[i])*t*t*t));
      };
      const half=.015/H;
      for(let segment=0;segment<path.length-1;segment++)for(let step=0;step<8;step++) {
        const a=sample(segment,step/8),b=sample(segment,(step+1)/8);
        straps.push({shape:"surface",points:[[a[0]-half,a[1],a[2]],[a[0]+half,a[1],a[2]],[b[0]+half,b[1],b[2]],[b[0]-half,b[1],b[2]]],tint:1});
      }
    }
    const strapMesh={kind:"mesh",c:[0,0,0],axes:[[1,0,0],[0,1,0],[0,0,1]],groups:[{color:"#384e47",parts:straps}]};
    if(pose.id.endsWith(LEFT_HAND_SUFFIX)) {
      const old={...j},flip=p=>[-p[0],p[1],p[2]];
      for(const key of Object.keys(old)){const other=/[LR]$/.test(key)?key.slice(0,-1)+(key.endsWith("L")?"R":"L"):key;j[other]=flip(old[key]);}
      mesh.c=flip(mesh.c);mesh.axes=mesh.axes.map(flip);straps.forEach(p=>{p.points=p.points.map(flip).reverse();});
    }
    return {...pose,joints:j,wide:[1,0,0],face:[0,-.05,Math.sqrt(1-.05*.05)],handDirections:directions,handGrips:{L:"handle",R:"handle"},props:[mesh,strapMesh],backpackDepth:true};
  }

