      const bell=Math.sin(Math.PI*u),wave=Math.sin(Math.PI*4*u+v*2)*Math.sin(Math.PI*v)*bell;
      return palms.L.map((p,i)=>p+(palms.R[i]-p)*u+(i===1?(-.38*bell-dims.w*.78*v+.035*wave+.09*v*v*Math.sin(3*Math.PI*u+.4))/H:i===2?(-slack*bell-dims.w*.42*v+.06*wave+.10*v*v*Math.sin(3*Math.PI*u))/H:0));
