    const normal=[0,1/unit,-slope/unit],origin=half-pad/2;
    const wood=[],rubber=[],frame=[];
    // Give the catalogue board and its raised pads their full width and thickness.
    const plank=(z0,z1,offset,thickness,parts)=>{
      const corners=[];
      for(const z of [z0,z1])for(const y of [-1,1])for(const x of [-1,1])corners.push([x*d.d/2,low+slope*(z+half)+normal[1]*(offset+y*thickness/2),origin+z+normal[2]*(offset+y*thickness/2)]);
      for(const ids of [[0,1,3,2],[4,6,7,5],[0,4,5,1],[2,3,7,6],[0,2,6,4],[1,5,7,3]])parts.push({shape:"surface",points:ids.map(i=>corners[i])});
    };
    plank(-half,half,0,.07,wood);plank(-half,-half+pad,.07,.07,rubber);plank(half-pad,half,.07,.07,rubber);
