    const mesh={kind:"mesh",c:[0,0,0],axes:[[1/H,0,0],[0,1/H,0],[0,0,1/H]],groups:[{color:"#b58b51",parts:wood},{color:"#414a50",parts:rubber},{color:"#69747b",parts:frame}]};
    const surface=z=>(low+slope*(z*H-origin+half)+.105*unit)/H;
    const motion=window.STAGE_PERFORMER_MOTION,st=motion.standard,dist=(a,b)=>Math.hypot(...a.map((v,i)=>v-b[i])),j={};
    const hipY=surface(-.035)+.035+.405,up=[0,Math.sqrt(.30*.30-.035*.035)/.30,.035/.30];
