      const leg=motion.twoBone(j["hip"+side],[x,surface(-.035)+.035,-.035],dist(st["hip"+side],st["kn"+side]),dist(st["kn"+side],st["an"+side]),[0,0,1]);
      j["kn"+side]=leg.joint;j["an"+side]=leg.end;j["to"+side]=[x,surface(.04)+.012,.04];
      const upper=dist(st["sh"+side],st["el"+side]),fore=dist(st["el"+side],st["wr"+side]);
