  /* ---------- 全画面表示 ----------
     ページを全画面にし、正面図と操作を同じ表示層へ置く。
     既存の図・パネルを一時的に移し、終了時に元の位置へ戻す。 */
  let fullscreenHome = null;
  let fullscreenTransitionPending = false;

  function fullscreenModalOpen() {
    return [...document.querySelectorAll('[role="dialog"], [role="alertdialog"]')]
      .some((dialog) => dialog.getClientRects().length > 0);
  }

  function setFullscreenDrawer(open, restoreFocus = true) {
    if (!els.presentDrawer || !els.presentDrawerToggle) return;
    els.presentDrawer.hidden = !open;
    els.presentOverlay.classList.toggle("is-drawer-open", open);
    const button = els.presentDrawerToggle;
    const label = open ? "パネルを閉じる" : "パネルを開く";
    button.setAttribute("aria-expanded", String(open));
    button.setAttribute("aria-label", tx(label));
    button.title = tx(label);
    button.dataset.jaAria = label;
    button.dataset.jaTitle = label;
    button.querySelector("span").textContent = open ? "◀" : "▶";
    if (open && tabletUi && tabletUi.drawer.hidden) openTabletGroup(tabletUi.groupId);
    if (!open && restoreFocus) button.focus({ preventScroll: true });
  }

  function setFullscreenView(which) {
    fullscreenMainView = which === "plan" && planCanvas ? "plan" : "front";
    const main = fullscreenMainView === "plan" ? planCanvas : canvas;
    const other = fullscreenMainView === "plan" ? canvas : planCanvas;
    els.presentCanvas.append(main);
    if (other) els.presentMiniView.append(other);
    els.presentMini.hidden = !other;
    els.presentOverlay.dataset.mainView = fullscreenMainView;
    els.presentMiniLabel.textContent = tx(fullscreenMainView === "plan" ? "正面図" : "平面図");
    syncCanvasResolution();
    render();
  }

  function swapFullscreenViews() {
    if (!presenting || fullscreenTransitionPending || !planCanvas || fullscreenModalOpen()) return false;
    const camera = document.querySelector("#stage-fpv-overlay");
    if (camera && camera.getClientRects().length) return false;
    setFullscreenView(fullscreenMainView === "front" ? "plan" : "front");
    return true;
  }

  function prepareFullscreenView() {
    sceneAlternatives?.adopted(state.project);
    if (fullscreenHome) return;
    const view = document.getElementById("view-stage");
    fullscreenHome = {
      focus: document.activeElement, view, inert: view ? view.inert : false, nodes: [],
      tablet: tabletUi ? { hidden: tabletUi.drawer.hidden, groupId: tabletUi.groupId, pageIndex: tabletUi.pageIndex } : null,
    };
    const move = (node, host) => {
      if (!node || !host) return;
      const marker = document.createComment("fullscreen-home");
      node.before(marker);
      fullscreenHome.nodes.push({ node, marker });
      host.append(node);
    };
    move(canvas, els.presentCanvas);
    move(planCanvas, els.presentMiniView);
    if (tabletUi) {
      move(tabletUi.rail, els.presentDrawerBody);
      move(tabletUi.drawer, els.presentDrawerBody);
    } else if (panelBottomActive()) {
      move(document.querySelector(".stage-center-bar"), els.presentDrawerBody);
      PANEL_BOTTOM_COLUMNS.forEach((col) => move(colEls[col], els.presentDrawerBody));
    } else move(colEls.left, els.presentDrawerBody);
    els.presentDrawerBody.classList.toggle("is-tablet", Boolean(tabletUi));
    presenting = true;
    document.body.classList.add("stage-fullscreen");
    document.documentElement.classList.add("stage-fullscreen-root");
    if (view) view.inert = true;
    if (els.presentBtn) els.presentBtn.setAttribute("aria-pressed", "true");
    if (els.presentOverlay) els.presentOverlay.setAttribute("aria-hidden", "false");
    setFullscreenDrawer(false, false);
    setFullscreenView(state.showPlan && !state.showFront ? "plan" : "front");
  }

  function finishFullscreenView() {
    // D-48 でも変えない（本番中の安全）: 全画面がブラウザ側で解けても、現場モードの表示の固定は外さない。
    // 現場モードを終える手段は「現場モードを終了」ボタンだけ（試験場 H の手順「Esc／F／背景で編集へ戻らない」）。
    if (fieldMode) { pseudoPresenting = true; return; }
    const saved = fullscreenHome;
    if (!saved) return;
    setFullscreenDrawer(false, false);
    saved.nodes.forEach(({ node, marker }) => marker.replaceWith(node));
    if (saved.tablet && tabletUi) {
      tabletUi.groupId = saved.tablet.groupId;
      tabletUi.pageIndex = saved.tablet.pageIndex;
      showTabletDrawerPage();
      if (saved.tablet.hidden) closeTabletDrawer();
      else {
        tabletUi.drawer.hidden = false;
        tabletUi.grid.classList.add("is-tablet-drawer-open");
        syncTabletWorkspace();
      }
    }
    presenting = false;
    pseudoPresenting = false;
    document.body.classList.remove("stage-fullscreen", "stage-pseudo-present");
    document.documentElement.classList.remove("stage-fullscreen-root");
    if (saved.view) saved.view.inert = saved.inert;
    if (els.presentBtn) els.presentBtn.setAttribute("aria-pressed", "false");
    if (els.presentOverlay) els.presentOverlay.setAttribute("aria-hidden", "true");
    fullscreenHome = null;
    syncCanvasResolution();
    render();
    if (saved.focus && saved.focus.isConnected) saved.focus.focus({ preventScroll: true });
    announce("全画面表示を終了しました。");
  }

  function enterPseudoPresentation() {
    prepareFullscreenView();
    pseudoPresenting = true;
    document.body.classList.add("stage-pseudo-present");
    els.presentClose.focus({ preventScroll: true });
    if (!fieldMode) announce("全画面表示です。下の矢印でシーン送り、右上のボタン・F・Escで戻ります。");
  }

  function exitPseudoPresentation() {
    finishFullscreenView();
  }

  function startPresentation() {
    prepareFullscreenView();
    const cv = document.documentElement;
    if (!cv || !cv.requestFullscreen) {
      enterPseudoPresentation();
      return;
    }
    return cv.requestFullscreen().then(() => {
      els.presentClose.focus({ preventScroll: true });
      syncCanvasResolution();
      render();
      if (!fieldMode) announce("全画面表示です。矢印キーでシーン送り、FまたはEscで戻ります。");
    }).catch(() => {
      announce("この環境では全画面にできませんでした。");
      enterPseudoPresentation();
    });
  }

  async function toggleStageFullscreen() {
    if (fieldMode) return;
    if (fullscreenTransitionPending) return;
    fullscreenTransitionPending = true;
    try {
      if (pseudoPresenting) exitPseudoPresentation();
      else if (presenting && document.fullscreenElement === document.documentElement) await document.exitFullscreen();
      else await startPresentation();
    } finally {
      fullscreenTransitionPending = false;
    }
  }

  /* ---------- 現場モード（表示だけ・保存と同期のガードには使わない） ---------- */
  const fieldConsole = document.getElementById("stage-field-console");
  const fieldEntry = document.getElementById("stage-field-mode");
  const fieldNode = (name) => document.getElementById("stage-field-" + name);
  let fieldHome = null;
  let fieldCommandPending = false;
  let fieldStarting = null;
  const fieldInert = new Map();
  function fieldElapsedText(seconds) {
    const n = Math.max(0, Math.floor(Number.isFinite(seconds) ? seconds : 0));
    return [Math.floor(n / 3600), Math.floor(n / 60) % 60, n % 60].map(v => String(v).padStart(2, "0")).join(":");
  }
  function fieldSceneContext() {
    const rows = state.project.scenes.filter(row => row.kind === "scene");
    const current = rows.find(row => row.id === state.project.activeSceneId);
    const at = rows.indexOf(current);
    const next = at >= 0 ? rows[at + 1] : null;
    const numbers = window.SHOSAI_CUE_SHEET?.sceneNumberMap(state.project.scenes);
    const label = row => row ? `${numbers?.get(row.id) || rows.indexOf(row) + 1} · ${row.title || tx("シーン")}` : tx("該当なし");
    return { current: label(current), next: next ? label(next) : tx("次のシーンはありません"), note: current?.note || tx("シーンのメモは舞台タブで入力できます"), hasNext: Boolean(next) };
  }
  function syncFieldMode(clock) {
    if (!fieldMode || !fieldConsole) return;
    const scene = fieldSceneContext(), transport = window.STAGE_FIELD_TIMELINE?.read();
    const write = (name, value) => { const node = fieldNode(name); if (node && node.textContent !== value) node.textContent = value; };
    write("scene", scene.current); write("note", scene.note); write("next-scene", scene.next);
    write("cue", transport?.currentCue || "");
    if (fieldNode("cue")) fieldNode("cue").hidden = !transport?.currentCue;
    write("next-cue", transport?.nextCue || tx("次のキューはありません（タイムラインの＋で追加できます）"));
    write("elapsed", fieldElapsedText(clock?.relativeSeconds ?? transport?.elapsed ?? 0));
    write("go", transport?.playing ? tx("一時停止") : "GO");
    const guest = guestSessionActive();
    fieldNode("go").disabled = guest || fieldCommandPending || !transport?.canPlay;
    fieldNode("go").title = tx(guest ? "共有セッション中はホストのシーンに追従します。" : transport?.canPlay ? "タイムラインを再生・一時停止" : "タイムラインを確認してください");
    fieldNode("scene-next").disabled = guest || !scene.hasNext;
    fieldNode("cue-next").disabled = guest || !transport?.nextCue || fieldCommandPending;
  }
  function lockFieldBackground() {
    if (!fieldMode) return;
    for (const node of document.body.children) {
      if (node === els.presentOverlay || fieldInert.has(node)) continue;
      fieldInert.set(node, node.inert); node.inert = true;
    }
  }
  async function enterFieldMode() {
    if (!window.SHOSAI_STAGE_SESSION_HOOKS?.role?.() && window.GAMMA_FIELD_RUNS && !STUDY_READ_ONLY && window.GAMMA_EDITION !== "lite" && !presenting && !fullscreenModalOpen()) { window.SHOSAI_STAGE_SESSION_HOOKS?.closeShareModal(); await window.GAMMA_FIELD_RUNS.open(); return; }
    if (fieldMode || presenting || !fieldConsole || !fieldEntry || STUDY_READ_ONLY || window.GAMMA_EDITION === "lite" || fullscreenModalOpen()) return;
    // Commit a focused editor's usual blur before locking; never cancel pending saves.
    document.activeElement?.blur?.();
    fieldHome = { focus: fieldEntry, panelHidden: document.getElementById("stage-timeline-panel")?.hidden };
    fieldMode = true;
    document.body.classList.add("stage-field-mode"); fieldConsole.hidden = false;
    fieldEntry.setAttribute("aria-pressed", "true");
    prepareFullscreenView(); lockFieldBackground();
    window.dispatchEvent(new Event("stage-field-mode-enter"));
    syncFieldMode(); (fieldNode("go").disabled ? fieldNode("exit") : fieldNode("go")).focus({ preventScroll: true });
    // Retain the same presentation shell if native fullscreen is unavailable.
    fieldStarting = Promise.resolve(startPresentation());
    await fieldStarting; fieldStarting = null;
    if (fieldMode) (fieldNode("go").disabled ? fieldNode("exit") : fieldNode("go")).focus({ preventScroll: true });
  }
  async function exitFieldMode() {
    if (!fieldMode) return;
    // A very quick explicit exit waits for the native request, then restores once.
    if (fieldStarting) await fieldStarting;
    if (!fieldMode) return;
    const home = fieldHome; fieldHome = null;
    fieldMode = false;
    document.body.classList.remove("stage-field-mode"); fieldConsole.hidden = true;
    fieldEntry.setAttribute("aria-pressed", "false");
    for (const [node, inert] of fieldInert) if (node.isConnected) node.inert = inert;
    fieldInert.clear();
    const panel = document.getElementById("stage-timeline-panel");
    if (panel && home) panel.hidden = home.panelHidden;
    finishFullscreenView();
    window.dispatchEvent(new Event("stage-field-mode-exit"));
    if (document.fullscreenElement === document.documentElement) await document.exitFullscreen().catch(() => {});
    home?.focus?.focus({ preventScroll: true });
  }
  async function fieldGo() {
    if (!fieldMode || fieldNode("go").disabled || fieldCommandPending) return;
    fieldCommandPending = true; syncFieldMode();
    try { await window.STAGE_FIELD_TIMELINE?.go(); }
    finally { fieldCommandPending = false; syncFieldMode(); }
  }
  function fieldNextCue() {
    if (!fieldMode || fieldNode("cue-next").disabled) return;
    window.STAGE_FIELD_TIMELINE?.next(); syncFieldMode();
    fieldNode("cue-next").focus({ preventScroll: true });
  }
  function guardFieldInput(event) {
    if (!fieldMode) return;
    const action = event.target?.closest?.("#stage-field-exit, #stage-field-go, #stage-field-scene-next, #stage-field-cue-next");
    if (event.type === "keydown") {
      if (event.key === "Tab") return; // Existing presentation focus trap. Esc stays blocked in field mode (D-48 keeps this).
      if (action && !event.metaKey && !event.ctrlKey && !event.altKey && ["Enter", " "].includes(event.key) && !event.repeat) return;
      event.preventDefault(); event.stopImmediatePropagation();
      if (event.repeat || event.isComposing || event.metaKey || event.ctrlKey || event.altKey) return;
      if (event.key === " ") void fieldGo();
      if (event.key === "ArrowDown" && !fieldNode("scene-next").disabled) { stepScene(1); syncFieldMode(); }
      if (event.key === "ArrowRight") fieldNextCue();
      return;
    }
    if (action && ["pointerdown", "pointerup", "mousedown", "mouseup", "click"].includes(event.type)) return;
    // Reading/scrolling the memo is safe, but no editor, drag, paste or shortcut is.
    if (event.type === "wheel" && fieldConsole.contains(event.target)) return;
    event.preventDefault(); event.stopImmediatePropagation();
  }
  if (fieldConsole && fieldEntry && !STUDY_READ_ONLY && window.GAMMA_EDITION !== "lite") {
    fieldEntry.addEventListener("click", () => {
      if (fieldMode || presenting) return;
      window.SHOSAI_STAGE_SESSION_HOOKS?.closeShareModal();
      void enterFieldMode();
    });
    fieldNode("exit").addEventListener("click", exitFieldMode);
    fieldNode("go").addEventListener("click", fieldGo);
    fieldNode("scene-next").addEventListener("click", () => { stepScene(1); syncFieldMode(); });
    fieldNode("cue-next").addEventListener("click", fieldNextCue);
    for (const type of ["keydown", "pointerdown", "pointerup", "pointermove", "mousedown", "mouseup", "click", "dblclick", "contextmenu", "beforeinput", "input", "change", "paste", "cut", "dragstart", "drop", "wheel"])
      window.addEventListener(type, guardFieldInput, { capture: true, passive: false });
    new MutationObserver(lockFieldBackground).observe(document.body, { childList: true });
    window.addEventListener("stage-scene-change", () => syncFieldMode());
    window.addEventListener("stage-timeline-position-change", event => syncFieldMode(event.detail));
    new MutationObserver(() => syncFieldMode()).observe(document.documentElement, { attributes: true, attributeFilter: ["lang"] });
  }
  /* ---------- 現場モードここまで ---------- */

  /* 大きな表示では内部解像度も追従させ、線や文字の粗さを抑える。
     論理座標は変えず、過大な描画負荷を避けるため3倍を上限とする。 */
  const BACKING_MAX_SCALE = 3;
  /* 下限も設ける。以前は1倍が下限で、スマホ（表示367px×dpr2＝734px）でも
     1280px幅で描いていた——必要な画素の約3倍を毎回描き直していた（2026-09-03 実測）。
     表示に要る画素数まで落とす。論理座標（W×H）は変えないので、入力の換算
     （pointFromEvent の W / rect.width）や書き出し（等倍の別 canvas）には影響しない。 */
  const BACKING_MIN_SCALE = 0.5;
  const canvasFullResolution = new WeakMap();
  function syncCanvasResolution() {
    let changed = false;
    for (const el of [canvas, planCanvas, canvas2]) {
      if (!el) continue;
      const cssW = el.getBoundingClientRect().width;
      if (!cssW) continue;
      canvasCssWidth.set(el, cssW);
      canvasBadgeInset.delete(el);
      const want = Math.min(BACKING_MAX_SCALE, Math.max(BACKING_MIN_SCALE, (cssW * (window.devicePixelRatio || 1)) / W));
      // Keep the original 100% resize threshold independent of the quality choice.
      let full = canvasFullResolution.get(el) || { width: el.width, height: el.height, logicalHeight: H };
      if (Math.abs(want - full.width / W) > 0.15 || full.logicalHeight !== H) {
        full = { width: Math.round(W * want), height: Math.round(H * want), logicalHeight: H };
      }
      canvasFullResolution.set(el, full);
      const quality = window.GAMMA_RENDER_RESOLUTION?.factor() || 1;
      const width = Math.max(1, Math.round(full.width * quality));
      const height = Math.max(1, Math.round(full.height * quality));
      if (el.width !== width || el.height !== height) {
        el.width = width; el.height = height;
        changed = true;
      }
    }
    if (changed) render();
  }
  const unsubscribeResolution = window.GAMMA_RENDER_RESOLUTION?.subscribe(() => {
    syncCanvasResolution();
    const select = document.querySelector("[data-stage-render-resolution]");
    if (select) select.value = String(window.GAMMA_RENDER_RESOLUTION.get());
  });
  window.addEventListener("pagehide", event => { if (!event.persisted) unsubscribeResolution?.(); });
  let canvasResizeFrame = 0;
  const canvasResObserver = new ResizeObserver(() => { if (!canvasResizeFrame) canvasResizeFrame = requestAnimationFrame(() => { canvasResizeFrame = 0; syncCanvasResolution(); }); });
  // The record frame owns CSS fitting and queues resolution from that fit.
  // Its viewports are observed there; do not add a second path on the fitted canvas.
  if (!(STUDY_READ_ONLY && document.querySelector(".field-frame-drawings"))) {
    canvasResObserver.observe(canvas);
    if (planCanvas) canvasResObserver.observe(planCanvas);
    if (canvas2) canvasResObserver.observe(canvas2);
  }
  window.addEventListener("resize", syncCanvasResolution);
  let bottomLayoutFrame = 0;
  const syncControlLayout = () => {
    if (bottomLayoutFrame) return;
    bottomLayoutFrame = requestAnimationFrame(() => {
      bottomLayoutFrame = 0;
      syncToolbarWrap();
      syncBottomScrollMode();
    });
  };
  window.addEventListener("resize", syncControlLayout);
  window.addEventListener("stage-timeline-layout-change", syncControlLayout);
  const controlLayoutObserver = new ResizeObserver(syncControlLayout);
  for (const el of [document.querySelector(".stage-center-bar"), colEls.center]) {
    if (el) controlLayoutObserver.observe(el);
  }
  /* ResizeObserverの初回通知は環境により来ないことがある（実際に来ない環境を確認済み）。
     読み込み直後の一度は自分で合わせる */
  requestAnimationFrame(syncCanvasResolution);
  /* スマホ閲覧機は起動後に図を組み替える（再親付け・4:3化）。その時点で
     ResizeObserver の通知が来ない環境があり、初回の rAF だけでは組み替え前の
     寸法で合わせたまま止まる（2026-09-03 実測: 表示367pxに対し1280pxのまま）。
     読み込み完了後と、その次の描画枠でもう一度合わせる。 */
  window.addEventListener("load", () => {
    syncCanvasResolution();
    requestAnimationFrame(syncCanvasResolution);
  });

  /* 全画面かどうか。全画面中だけ、シーンの説明を絵の中へ描く。
     入るときも出るときも描き直しがいる（出たあと字が残らないように）。 */
  let modeFullscreenElement = document.fullscreenElement;
  document.addEventListener("fullscreenchange", () => {
    const previous = modeFullscreenElement;
    modeFullscreenElement = document.fullscreenElement;
    // Safari may deliver no keydown after its native Esc. Clean up here too.
    if (previous && !modeFullscreenElement) {
      // 現場モードは表示の固定を保つ（finishFullscreenView が疑似全画面へ切り替える）。抜けるのはボタンだけ。
      if (fieldMode) { finishFullscreenView(); return; }
      window.SHOSAI_STAGE_FPV?.close();
      if (presenting) finishFullscreenView();
    } else if (presenting && modeFullscreenElement) { syncCanvasResolution(); render(); }
  });

  function modeExitInnerOpen(root = null) {
    const surface = root || els.presentOverlay;
    const overlays = [...document.querySelectorAll('[role="dialog"], [role="alertdialog"], [role="menu"], [popover], .stage-piece-context-menu, #stage-header-volume-pop, #stage-panel-layout-menu, #stage-panels-menu'),
      ...(surface?.querySelectorAll?.('details[open], .gamma-selection-floating') || [])];
    return overlays.some(node => node !== root && !node.hidden && !node.closest?.('[inert]') && node.getClientRects().length > 0);
  }
  function deferModeEscape(event, exit, root = null, dismiss = () => false) {
    if (event.key !== "Escape" || event.defaultPrevented || event.isComposing || event.repeat) return;
    // Snapshot before other capture/bubble listeners close their windows. Their
    // existing handlers keep ownership of this first Esc, even without preventDefault.
    const innerOpen = modeExitInnerOpen(root);
    queueMicrotask(() => {
      if (event.defaultPrevented) return;
      if (innerOpen) {
        // Native details/popovers do not all have a custom Esc listener.
        (root || els.presentOverlay)?.querySelectorAll('details[open]').forEach(node => {
          if (node.getClientRects().length) node.open = false;
        });
        document.querySelectorAll('[popover]').forEach(node => {
          if (node.getClientRects().length) node.hidePopover?.();
        });
        return;
      }
      if (dismiss()) return;
      exit();
    });
  }
  window.GAMMA_MODE_EXIT = Object.freeze({ deferEscape: deferModeEscape });
  window.addEventListener("keydown", event => {
    // 現場モードの Esc は guardFieldInput が止める（本番中の押し間違い防止）。ここでも扱わない。
    if (!presenting || fieldMode || window.SHOSAI_STAGE_FPV?.isOpen?.()) return;
    deferModeEscape(event, () => {
      if (presenting) void toggleStageFullscreen();
    }, null, () => {
      if (els.presentDrawer && !els.presentDrawer.hidden) {
        setFullscreenDrawer(false); return true;
      }
      return false;
    });
  }, true);

  // 全画面の入口と同じ可否を守る。入力中やダイアログ操作中のFは奪わない。
  document.addEventListener("keydown", (event) => {
    if (event.defaultPrevented || !window.SHOSAI_STAGE_SHORTCUTS?.matches(event, "view.presentation")) return;
    if (event.repeat || event.isComposing || event.keyCode === 229 || isTyping(event.target)) return;
    if (fullscreenModalOpen()) return;
    const fullscreen = presenting;
    if (!fullscreen) {
      const view = document.getElementById("view-stage");
      const button = els.presentBtn;
      if (!view || view.hidden || phoneViewerActive || !featureOn("presentation")) return;
      if (!button || button.hidden || button.disabled || button.offsetParent === null) return;
      if (button.getAttribute("aria-disabled") === "true" || button.dataset.publicLock) return;
      if (document.body.classList.contains("stage-session-guest")) return;

    }
    event.preventDefault();
    if (fullscreen) toggleStageFullscreen();
    else els.presentBtn.click();
  });

  // The keyboard and guest guide share the existing view-select change route.
  function switchStageView() {
    if (!els.viewSelect) return false;
    const current = els.viewSelect.value;
    const next = panelBottomActive() ? (current === "both-plan" ? "both-front" : "both-plan")
      : current === "front" ? "plan"
      : current === "plan" ? "front"
        : current === "both-plan" ? "both-front" : "both-plan";
    if (next === current) return false;
    els.viewSelect.value = next;
    els.viewSelect.dispatchEvent(new Event("change", { bubbles: true }));
    return true;
  }

  // Tは表示図を切り替える。片面表示なら反対の図へ、両面表示なら上下順だけを替える。
  document.addEventListener("keydown", (event) => {
    if (event.defaultPrevented || !window.SHOSAI_STAGE_SHORTCUTS?.matches(event, "view.switch")) return;
    if (event.repeat || event.isComposing || event.keyCode === 229 || isTyping(event.target)) return;
    if (phoneViewerActive || presenting || fullscreenModalOpen()) return;
    const view = document.getElementById("view-stage");
    if (!view || view.hidden || !els.viewSelect) return;
    if (switchStageView()) event.preventDefault();
  });

  // Cは舞台タブだけ。照明デザインや入力欄の文字入力は奪わない。
  document.addEventListener("keydown", (event) => {
    if (!editionAllows("lightRender") || event.defaultPrevented || !window.SHOSAI_STAGE_SHORTCUTS?.matches(event, "view.lightRender")) return;
    if (event.repeat || event.isComposing || event.keyCode === 229 || isTyping(event.target)) return;
    if (phoneViewerActive || fullscreenModalOpen()) return;
    if (!presenting && document.body.dataset.gammaWorkspace && document.body.dataset.gammaWorkspace !== "normal") return;
    const view = document.getElementById("view-stage");
    if (!view || (!presenting && view.hidden)) return;
    event.preventDefault();
    toggleLightRendering();
  });

  // Gは舞台タブだけ。照明デザインのGや入力欄の文字入力は奪わない。
  document.addEventListener("keydown", (event) => {
    if (!editionAllows("lightRender") || event.defaultPrevented || !window.SHOSAI_STAGE_SHORTCUTS?.matches(event, "view.workLight")) return;
    if (event.repeat || event.isComposing || event.keyCode === 229 || isTyping(event.target)) return;
    if (phoneViewerActive || fullscreenModalOpen()) return;
    if (!presenting && document.body.dataset.gammaWorkspace && document.body.dataset.gammaWorkspace !== "normal") return;
    const view = document.getElementById("view-stage");
    if (!view || (!presenting && view.hidden)) return;
    event.preventDefault();
    toggleWorkLightOff();
  });

  // 図の交換は全画面中だけ。文字入力や別の操作面へXを通す。
  document.addEventListener("keydown", (event) => {
    if (event.defaultPrevented || !window.SHOSAI_STAGE_SHORTCUTS?.matches(event, "view.swap")) return;
    if (event.repeat || event.isComposing || event.keyCode === 229 || isTyping(event.target)) return;
    if (swapFullscreenViews()) event.preventDefault();
  });

  /* ---------- 整列（平面図で選択したものだけ） ----------
     ★いまの位置関係をなるべく保つ（本人指定）。誰がどこへ行くかが
       席替えのように入れ替わると、並べた瞬間に配置の意味が壊れるため。
       横・斜め・V字は左右の順、縦は奥行きの順、円は重心から見た角度の順を使う。 */
  /* T-04（2026-09-18 本人要望）: 「整列」は削除した。
   * 実処理の lineupPerformers() も呼び出しが無くなったので一緒に外した。
   * 代替はフォーメーション（GAMMA_FORMATION_*）。 */

  /* ---------- 転換の忙しさ ---------- */
  function transitionStats(prev, row) {
    const size = venueSize();
    let dist = 0;
    let movers = 0;
    let inout = 0;
    (row.pieces || []).forEach((piece) => {
      if (piece.type === "light") return;
      const twin = twinOf(piece, prev.pieces || []);
      if (!twin) {
        if (piece.type === "performer" && piece.castId) inout += 1;
        return;
      }
      const d = Math.hypot((piece.u - twin.u) * (size.width || 12), (piece.v - twin.v) * (size.depth || 9));
      if (d >= 0.25) { movers += 1; dist += d; }
    });
    (prev.pieces || []).forEach((old_) => {
      if (old_.type === "performer" && old_.castId && !twinOf(old_, row.pieces || [])) inout += 1;
    });
    return { dist, movers, inout };
  }

  /* バミリ図とキューシートが同じ実寸変換を使う。表示先ごとに式を写さない。 */
  function bamiriPosition(piece, en = languageValue(() => true, () => false)) {
    const size = venueSize();
    const off = (finite(piece && piece.u, 0.5) - 0.5) * (size.width || 12);
    const across = Math.abs(off) < 0.15
      ? (en ? "centre" : "中央")
      : (en
        ? `${Math.abs(off).toFixed(1)}m ${off > 0 ? "SL" : "SR"}`
        : `${off > 0 ? "上手" : "下手"}${Math.abs(off).toFixed(1)}m`);
    const front = ((1 - finite(piece && piece.v, 0.5)) * (size.depth || 9)).toFixed(1);
    return { across, front: `${front}m`, text: `${across} / ${front}m` };
  }

  /* 既存の明かりのキューシートと新しい部署シートで、点灯差分の正本を共有する。 */
  function lightCueChanges(previousScene, scene) {
    const previous = previousScene || { pieces: [] };
    const cur = (scene && scene.pieces || []).filter((piece) => piece.type === "light");
    const before = (previous.pieces || []).filter((piece) => piece.type === "light");
    const on = cur.filter((piece) => !twinOf(piece, before)).map((piece) => pieceLabel(piece));
    const off = before.filter((piece) => !twinOf(piece, cur)).map((piece) => pieceLabel(piece));
    const changed = cur.map((piece) => {
      const twin = twinOf(piece, before);
      if (!twin) return null;
      const a = finite(twin.glow, 1);
      const b = finite(piece.glow, 1);
      if (Math.abs(a - b) < 0.01) return null;
      return `${pieceLabel(piece)} ${Math.round(a * 100)}→${Math.round(b * 100)}%`;
    }).filter(Boolean);
    return { on, off, changed };
  }

  /* ---------- 印刷用ページ ----------
     選んだシーンと図を並べた、印刷のためのページを別タブに開く。
     ブラウザの「印刷」からPDFにして、稽古場へ紙で持っていける。
     絵は本物の描画（drawStage）をシーンごとに退避・切替して撮る。 */
  const PRINT_IMAGE_TIMEOUT_MS = 5000;
  const PRINT_IMAGES_TOTAL_TIMEOUT_MS = 10000;

  async function preparePrintImages(project, rows, view) {
    const job = { images: new Map(), failed: new Set(), fallback: null };
    // All photoImage consumers read scene.photo.id or piece.imageId. Plan
    // diagrams do not paint photos. Count only images actually drawn later.
    const sources = new Set();
    if (view !== "plan") for (const row of rows) {
      if (row.photo) sources.add(project.photos?.[row.photo.id]);
      for (const piece of row.pieces || []) {
        if (piece.imageId) sources.add(project.photos?.[piece.imageId]);
      }
    }
    const deadline = Date.now() + PRINT_IMAGES_TOTAL_TIMEOUT_MS;
    await Promise.all([...sources].map(src => new Promise(resolve => {
      job.images.set(src, null);
      if (!src) { resolve(); return; }
      // Start/reuse the editor's cache, never create a second image loader.
      photoImage(src);
      const image = photoCache.get(src);
      if (!image) { resolve(); return; }
      let settled = false, decoding = false;
      const finish = success => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        image.removeEventListener("load", loaded);
        image.removeEventListener("error", failed);
        if (success && image.naturalWidth) job.images.set(src, image);
        resolve();
      };
      const failed = () => finish(false);
      const loaded = () => {
        if (settled || decoding) return;
        if (!image.naturalWidth) { finish(false); return; }
        decoding = true;
        if (typeof image.decode !== "function") { finish(true); return; }
        try { Promise.resolve(image.decode()).then(() => finish(true), failed); }
        catch (_) { finish(false); }
      };
      const timer = setTimeout(failed, Math.max(0, Math.min(PRINT_IMAGE_TIMEOUT_MS, deadline - Date.now())));
      image.addEventListener("load", loaded);
      image.addEventListener("error", failed);
      if (image.complete) loaded();
    })));
    return job;
  }

  function createPrintImageFallback(width = 640, height = 360) {
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.ceil(width)); canvas.height = Math.max(1, Math.ceil(height));
    // The existing projection renderer accepts CanvasImageSource and uses
    // natural dimensions for its perspective mapping.
    canvas.naturalWidth = canvas.width; canvas.naturalHeight = canvas.height;
    const context = canvas.getContext("2d");
    context.fillStyle = "#ffffff"; context.fillRect(0, 0, canvas.width, canvas.height);
    context.strokeStyle = "#404040"; context.lineWidth = 1;
    context.strokeRect(.5, .5, canvas.width - 1, canvas.height - 1);
    context.fillStyle = "#202020";
    context.font = '16px "Hiragino Kaku Gothic ProN", sans-serif';
    context.textAlign = "center"; context.textBaseline = "middle";
    context.fillText(tx("写真を読めませんでした"), canvas.width / 2, canvas.height / 2, Math.max(1, canvas.width - 16));
    return canvas;
  }

  let printPreparing = false;
  async function openPrintPage() {
    if (printPreparing) return;
    // Open during the gesture so browsers and the native shell can accept the tab.
    const win = window.open("", "_blank");
    if (!win) { announce("印刷用ページを開けませんでした。ポップアップの許可を確認してください。"); return; }
    const progress = win.document.createElement("p");
    progress.setAttribute("role", "status");
    win.document.title = tx("印刷／PDF");
    progress.textContent = tx("印刷用ページを準備しています…");
    win.document.body.append(progress);
    printPreparing = true;
    const snapshot = JSON.parse(JSON.stringify(state.project));
    const options = { view: exportView, scope: exportScope };
    const iterator = buildPrintPage(win, options);
    // A print popup can background its opener. Do not wait for the opener's
    // animation frames, which WebKit may suspend while the popup has focus.
    const yieldPrintTask = () => new Promise(resolve => {
      const channel = new MessageChannel();
      channel.port1.onmessage = () => { channel.port1.close(); channel.port2.close(); resolve(); };
      channel.port2.postMessage(null);
    });
    try {
      // exportTargets also adopts scene alternatives. Run it on the same copy
      // as the renderer, never on the live project while selecting images.
      const keepProject = state.project;
      try { state.project = snapshot; options.rows = exportTargets(); }
      finally { state.project = keepProject; }
      options.imageJob = await preparePrintImages(snapshot, options.rows, options.view);
      await yieldPrintTask();
      let result;
      do {
        if (win.closed) { iterator.return(); break; }
        // Rendering resolves support positions. Never expose the print snapshot to
        // autosave, input handlers or the editor across an asynchronous boundary.
        const keepProject = state.project, keepFront = zoomState.front, keepPlan = zoomState.plan;
        const keepPaper = printPaperSurface;
        try {
          state.project = snapshot;
          zoomState.front = { z: 1, ox: 0, oy: 0 };
          zoomState.plan = { z: 1, ox: 0, oy: 0 };
          result = iterator.next();
        } finally {
          state.project = keepProject; zoomState.front = keepFront; zoomState.plan = keepPlan;
          printPaperSurface = keepPaper;
        }
        if (!result.done) {
          progress.textContent = tx("印刷用ページを準備しています…") + ` ${result.value.done} / ${result.value.total}`;
          await yieldPrintTask();
        }
      } while (!result.done);
      if (result?.done && !win.closed && options.imageJob.failed.size) {
        announce(tx("印刷用ページを作りました。読めなかった写真: {count}件。")
          .replace("{count}", String(options.imageJob.failed.size)), { warning: false });
      }
    } catch (error) {
      if (!win.closed) win.close();
      console.error("stage print: 印刷用ページを作れませんでした", error);
      exportFailureNotice("印刷用ページを作れませんでした。もう一度お試しください。");
    } finally {
      printPreparing = false;
      render();
    }
  }

  function* buildPrintPage(win, options = { view: exportView, scope: exportScope }) {
    const keepView = exportView, keepScope = exportScope;
    let rows;
    try {
      exportView = options.view; exportScope = options.scope;
      rows = options.rows || exportTargets();
    } finally { exportView = keepView; exportScope = keepScope; }
    const views = options.view === "both" ? ["front", "plan"] : [options.view];
    const selectedIds = new Set(rows.map(row => row.id));
    const allRows = state.project.scenes;
    const allScenes = allRows.filter(row => row.kind === "scene");
    const printRows = allRows.filter((row, index) => {
      if (row.kind !== "section") return selectedIds.has(row.id);
      for (let k = index + 1; k < allRows.length && allRows[k].depth > row.depth; k++) {
        if (selectedIds.has(allRows[k].id)) return true;
      }
      return false;
    });
    if (!rows.length) { win.close(); announce("印刷するシーンがありません。"); return; }
    const keepScene = state.project.activeSceneId;
    const keepFront = Object.assign({}, zoomState.front);
    const keepPlan = Object.assign({}, zoomState.plan);
    zoomState.front = { z: 1, ox: 0, oy: 0 };
    zoomState.plan = { z: 1, ox: 0, oy: 0 };
    const canvases = Object.fromEntries(views.map(view => {
      const canvas = document.createElement("canvas"); canvas.width = W * 2; canvas.height = H * 2;
      return [view, canvas];
    }));
    // Bind native methods to the original context. Only the paper rendition
    // darkens diagram strokes/text; costume and object fill colors are retained.
    const printContext = canvas => {
      const context = canvas.getContext("2d");
      return new Proxy(context, {
        get(target, key) {
          if (key === "fillText" || key === "strokeText") return (...args) => {
            target.save(); if (printPaperSurface) { target.fillStyle = "#202020"; target.strokeStyle = "#202020"; }
            try { return target[key](...args); } finally { target.restore(); }
          };
          if (key === "drawImage") return (image, ...args) => {
            // A missing-image card is a paper annotation, not projected light:
            // screen blending or scrim opacity must not erase its black text.
            if (image === options.imageJob?.fallback) {
              target.save(); target.globalAlpha = 1; target.globalCompositeOperation = "source-over"; target.filter = "none";
              try { return target.drawImage(image, ...args); } finally { target.restore(); }
            }
            return target.drawImage(image, ...args);
          };
          const value = target[key]; return typeof value === "function" ? value.bind(target) : value;
        },
        set(target, key, value) {
          if (printPaperSurface && key === "strokeStyle" && typeof value === "string") value = "#404040";
          target[key] = value; return true;
        }
      });
    };
    const contexts = Object.fromEntries(views.map(view => [view, printContext(canvases[view])]));
    const en = languageValue(() => true, () => false);
    const parts = [];
    // セクション見出しも順番どおりに差し込む
    let sceneN = 0;
    let previousScene = null;
    let completed = 0;
    try {
    for (const row of printRows) {
      if (row.kind === "section") {
        parts.push(`<h2 class="section">${escapeHtml(row.title || "")}</h2>`);
        continue;
      }
      sceneN = allScenes.findIndex(scene => scene.id === row.id) + 1;
      previousScene = allScenes[sceneN - 2] || null;
      state.project.activeSceneId = row.id;
      const images = {};
      // Keep the renderer, canvas resolution, paper proxy and JPEG quality intact.
      // Only skip diagrams outside the selected view/scope; reuse canvases per row.
      for (const paper of [false, true]) {
        printPaperSurface = paper;
        for (const view of views) {
          // F-01: a reused canvas retains its current path (save/restore and
          // clearRect do not clear it), clips and drawing state. Start every
          // rendition as a fresh single-scene canvas, keeping its size/quality.
          canvases[view].width = W * 2;
          const keepImageJob = options.imageJob ? printImageJob : null;
          try {
            if (options.imageJob) printImageJob = options.imageJob;
            drawStage(contexts[view], false, view);
          } finally { if (options.imageJob) printImageJob = keepImageJob; }
          (images[view] ||= {})[paper ? "paper" : "dark"] = canvases[view].toDataURL("image/jpeg", 0.92);
        }
      }
      printPaperSurface = false;
      const cast = (row.pieces || []).filter((q) => q.type === "performer")
        .map((q) => pieceLabel(q)).filter(Boolean);
      const rh = row.rehearsal || {};
      const times = [];
      if (featureOn("sceneTiming")) {
        if (finite(rh.holdDurationSeconds, -1) >= 0) times.push(en ? `show ${formatAudioDuration(rh.holdDurationSeconds)}` : `見せる ${formatAudioDuration(rh.holdDurationSeconds)}`);
        if (finite(rh.transitionToNextSeconds, -1) >= 0) times.push(en ? `move ${formatAudioDuration(rh.transitionToNextSeconds)}` : `次へ移動 ${formatAudioDuration(rh.transitionToNextSeconds)}`);
      }
      const props = featureOn("propsplot") ? propSceneSummary(row, en) : [];
      const propMoves = featureOn("propsplot") ? propMovesBetweenScenes(previousScene, row, en) : [];
      parts.push(`<section class="scene">
  <header><span class="no">${sceneN}</span><h3>${escapeHtml(row.title || "")}</h3>
    <span class="times">${escapeHtml(times.join(" / "))}</span></header>
  ${row.note ? `<p class="desc"><span class="desc-label">${en ? "Scene description" : "シーンの説明"}</span>${escapeHtml(row.note)}</p>` : ""}
  <div class="pics">
    ${views.map(view => `<img class="${view}" src="${images[view].paper}" data-dark="${images[view].dark}" alt="${tx(view === "front" ? "正面図" : "平面図")}">`).join("\n")}
  </div>
  <div class="meta">
    ${cast.length ? `<p class="cast">${en ? "On stage" : "舞台上"}: ${escapeHtml(cast.join(" / "))}</p>` : ""}
    ${props.length ? `<p class="prop-meta">${en ? "Props" : "小道具"}: ${escapeHtml(props.join(" / "))}</p>` : ""}
    ${propMoves.length ? `<p class="prop-meta">${en ? "Handoffs" : "受け渡し"}: ${escapeHtml(propMoves.join(en ? " / " : " ／ "))}</p>` : ""}
    ${bamiriTable(row)}
  </div>
</section>`);
      completed += 1;
      yield { done: completed, total: rows.length };
    }
    } finally {
      // Also release buffers when the preparation window closes or drawing fails.
      for (const canvas of Object.values(canvases)) { canvas.width = 0; canvas.height = 0; }
    }
    /* バミリ図: 立ち位置の実寸表。床にテープを貼る作業へそのまま持っていける */
    function bamiriTable(row) {
      if (!featureOn("bamiri")) return "";
      const people = (row.pieces || []).filter((q) => q.type === "performer" && onStageArea(q.u, q.v));
      if (!people.length) return "";
      const cells = people.map((q) => {
        const position = bamiriPosition(q, en);
        return `<tr><td>${escapeHtml(pieceLabel(q) || "?")}</td><td>${escapeHtml(position.across)}</td><td>${position.front}</td></tr>`;
      }).join("");
      return `<table class="bamiri"><thead><tr><th>${en ? "Who" : "誰"}</th><th>${en ? "Across" : "左右"}</th><th>${en ? "From DS edge" : "ツラから"}</th></tr></thead><tbody>${cells}</tbody></table>`;
    }

    const printSceneRows = rows;

    /* 明かりのキューシート: シーンごとの点き・消え・強さの変化 */
    let cuesheetHtml = "";
    if (featureOn("cuesheet")) {
      const lines = [];
      printSceneRows.forEach((row, i2) => {
        const originalIndex = allScenes.findIndex(scene => scene.id === row.id);
        const prev = allScenes[originalIndex - 1] || { pieces: [] };
        const { on, off, changed } = lightCueChanges(prev, row);
        if (!on.length && !off.length && !changed.length) return;
        lines.push(`<tr><td>${i2 + 1} ${escapeHtml(row.title || "")}</td><td>${escapeHtml(on.join(" / "))}</td><td>${escapeHtml(off.join(" / "))}</td><td>${escapeHtml(changed.join(" / "))}</td></tr>`);
      });
      if (lines.length) {
        cuesheetHtml = `<section class="scene"><header><h3>${en ? "Light Q sheet" : "明かりのQシート"}</h3></header>
<table class="cues"><thead><tr><th>${en ? "Scene" : "シーン"}</th><th>${en ? "On" : "点く"}</th><th>${en ? "Off" : "消える"}</th><th>${en ? "Level" : "強さ"}</th></tr></thead><tbody>${lines.join("")}</tbody></table></section>`;
      }
    }

    /* 小道具の香盤表。列が増えてもキューシートと同じ薄い罫線に留め、
       変化したセルだけを小さく強調して、図より目立たせない。 */
    let propsPlotHtml = "";
    const propsForPlot = registeredProps();
    if (featureOn("propsplot") && propsForPlot.length) {
      const plotRows = propsForPlot.map((prop) => {
        let before = null;
        const cells = printSceneRows.map((row) => {
          const entry = propPlotState(row, prop);
          const changed = before ? propPlotStateChanged(before, entry) : false;
          before = entry;
          const value = entry.kind === "held" ? propHolderName(entry.holder).slice(0, 8)
            : (entry.kind === "floor" ? (en ? "floor" : "床") : "");
          return `<td${changed ? ' class="changed"' : ""}>${escapeHtml(value)}</td>`;
        });
        return { name: escapeHtml(prop.name || ""), cells };
      });
      const plots = [];
      // Columns carry the original scene numbers (as the scene sections do), also when the print is scoped (v0.4.0 G-30/31).
      const sceneNumberOf = (row) => allScenes.findIndex((scene) => scene.id === row.id) + 1;
      for (let start = 0; start < printSceneRows.length; start += 12) {
        const rows = printSceneRows.slice(start, start + 12);
        const head = rows.map((row) => `<th title="${escapeHtml(row.title || "")}">${sceneNumberOf(row)}</th>`).join("");
        const body = plotRows.map((row) => `<tr><th>${row.name}</th>${row.cells.slice(start, start + 12).join("")}</tr>`).join("");
        plots.push(`<section class="scene props-plot"><header><h3>${en ? "Props plot" : "小道具の香盤表"} (${sceneNumberOf(rows[0])}–${sceneNumberOf(rows[rows.length - 1])})</h3></header>
<table class="cues props-plot-table"><thead><tr><th>${en ? "Prop" : "小道具名"}</th>${head}</tr></thead><tbody>${body}</tbody></table></section>`);
      }
      propsPlotHtml = plots.join("\n");
    }

    state.project.activeSceneId = keepScene;
    zoomState.front = keepFront;
    zoomState.plan = keepPlan;
    render();
    const title = escapeHtml(state.project.title || "");
    const html = `<!DOCTYPE html><html lang="${en ? "en" : "ja"}"><head><meta charset="utf-8">
<title>${title}</title>
<style>
  body { font-family: 'Hiragino Kaku Gothic ProN', sans-serif; color: #1c1a17; margin: 24px; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  .stamp { color: #777; font-size: 12px; margin: 0 0 18px; }
  .print-toggle { font-size: 12px; color: #555; margin: 0 0 14px; }
  h2.section { font-size: 15px; letter-spacing: 0.1em; border-bottom: 1px solid #999; padding-bottom: 4px; margin: 26px 0 10px; page-break-after: avoid; }
  .scene { page-break-inside: avoid; margin: 0 0 26px; }
  .scene header { display: flex; align-items: baseline; gap: 10px; border-bottom: 2px solid #1c1a17; padding-bottom: 4px; margin-bottom: 8px; }
  .scene .no { font-size: 18px; font-weight: bold; }
  .scene h3 { font-size: 16px; margin: 0; flex: 1; }
  .scene .times { font-size: 12px; color: #555; }
  .pics { display: flex; gap: 10px; }
  .pics img { display: block; border: 1px solid #ccc; }
  .pics .front { width: 58%; height: auto; }
  .pics .plan { width: 40%; height: auto; }
  .pics img:only-child { width: 100%; height: auto; }
  body.two-up .pics .front { width: 44%; }
  body.two-up .pics .plan { width: 30%; }
  .meta { margin-top: 6px; }
  /* シーンの説明は絵の前に置く。何が起きるシーンかを読んでから図を見る順番になる */
  .desc { font-size: 13px; line-height: 1.6; margin: 0 0 8px; white-space: pre-wrap; }
  .desc-label { display: inline-block; font-size: 10px; letter-spacing: 0.08em; color: #666;
                border: 1px solid #bbb; border-radius: 2px; padding: 1px 5px; margin-right: 8px;
                vertical-align: 1px; white-space: nowrap; }
  .cast, .prop-meta { font-size: 12px; color: #555; margin: 0; }
  table.bamiri, table.cues { border-collapse: collapse; font-size: 11px; margin-top: 6px; }
  table.bamiri th, table.bamiri td, table.cues th, table.cues td {
    border: 1px solid #bbb; padding: 2px 8px; text-align: left; }
  table.bamiri th, table.cues th { background: #eee; }
  table.props-plot-table { width: 100%; table-layout: fixed; }
  table.props-plot-table th, table.props-plot-table td { overflow-wrap: anywhere; padding: 2px 3px; }
  table.props-plot-table th:first-child { width: 20%; }
  table.props-plot-table td.changed { font-weight: 600; text-decoration: underline; text-decoration-color: #888; }
  @page { size: A4 landscape; margin: 10mm; }
  @media print {
    body { margin: 0; }
    .print-toggle { display: none; }
    .scene { page-break-after: always; margin-bottom: 0; }
    .scene:last-of-type { page-break-after: auto; }
    body.two-up .scene { page-break-after: auto; }
    body.two-up .scene.pb { page-break-after: always; }
  }
</style><style id="print-page-orientation"></style></head><body>
<h1>${title}</h1>
<p class="stamp">${escapeHtml(state.project.versionLabel || "v1")} · ${window.STAGE_TIME_DOMAIN.dateText(new Date(), en ? "en" : "ja")} · ${en ? "Stage Sketch print sheet" : "舞台スケッチ 印刷用"}</p>
<div class="print-toggle">
  <label><input type="checkbox" id="print-paper" checked> ${tx("紙向けの明るい地（白い床・黒い線）")}</label>
  <label>${tx("用紙の向き")} <select id="print-orientation"><option value="landscape">${tx("横")}</option><option value="portrait">${tx("縦")}</option></select></label>
  <button type="button" onclick="window.print()">${tx("印刷・PDF")}</button>
  <label><input type="radio" name="print-layout" value="1" checked> ${en ? "1 scene / page" : "1シーン/ページ"}</label>
  <label><input type="radio" name="print-layout" value="2"> ${en ? "2 scenes / page" : "2シーン/ページ"}</label>
</div>
${parts.join("\n")}
${cuesheetHtml}
${propsPlotHtml}
<script>
(function () {
  document.querySelectorAll('.pics img').forEach(function (img) { img.dataset.paper = img.src; });
  document.getElementById('print-paper').addEventListener('change', function (event) {
    document.querySelectorAll('.pics img').forEach(function (img) { img.src = event.target.checked ? img.dataset.paper : img.dataset.dark; });
  });
  document.getElementById('print-orientation').addEventListener('change', function (event) {
    document.getElementById('print-page-orientation').textContent = '@page { size: A4 ' + (event.target.value === 'portrait' ? 'portrait' : 'landscape') + '; margin: 10mm; }';
  });
  var radios = document.querySelectorAll('.print-toggle input[type="radio"]');
  function applyPrintLayout() {
    var selected = document.querySelector('.print-toggle input[type="radio"]:checked');
    var twoUp = selected && selected.value === '2';
    document.body.classList.toggle('two-up', twoUp);
    var scenes = document.querySelectorAll('section.scene');
    scenes.forEach(function (scene, index) {
      scene.classList.toggle('pb', twoUp && (index + 1) % 2 === 0);
    });
  }
  radios.forEach(function (radio) {
    radio.addEventListener('change', applyPrintLayout);
  });
  applyPrintLayout();
})();
</script>
</body></html>`;
    const url = URL.createObjectURL(new Blob([html], { type: "text/html" }));
    win.addEventListener("load", () => URL.revokeObjectURL(url), { once: true });
    win.location.replace(url);
    if (!options.imageJob?.failed.size) announce("印刷用ページを開きました。ブラウザの印刷からPDFにできます。");
  }

  // 矢印キーでシーンを送ったとき、ページ全体やフォーカスは動かさずシーン欄だけ追従させる。
  function followSceneInPanel(sceneId, transitionToSceneId = null, expand = false) {
    const list = els.sceneList;
    if (!list || !list.getClientRects().length) return;
    let row = list.querySelector(`:scope > [data-scene-id="${CSS.escape(sceneId)}"]`);
    if (!row) {
      // 畳んだセクション内へ進んだ場合だけ、現在のシーンに至る親を開く。
      const scenes = state.project.scenes;
      const index = scenes.findIndex((scene) => scene.id === sceneId);
      if (index < 0) return;
      let depth = scenes[index].depth;
      let changed = false;
      for (let i = index - 1; i >= 0 && depth > 0; i -= 1) {
        const ancestor = scenes[i];
        if (ancestor.depth >= depth) continue;
        if (ancestor.kind === "section" && state.closedSections[ancestor.id]) {
          delete state.closedSections[ancestor.id];
          changed = true;
        }
        depth = ancestor.depth;
      }
      if (!changed) return;
      renderScenes();
      renderSceneGrid();
      row = list.querySelector(`:scope > [data-scene-id="${CSS.escape(sceneId)}"]`);
    }
    const boundary = transitionToSceneId && list.querySelector(`.stage-scene-transition-boundary[data-transition-from="${CSS.escape(sceneId)}"][data-transition-to="${CSS.escape(transitionToSceneId)}"]`);
    const chip = transitionToSceneId ? expand ? boundary : boundary?.querySelector(".stage-scene-transition-point") : row && row.querySelector(".stage-scene-chip");
    if (!chip) return;
    const scrollToChip = () => {
      if (!list.getClientRects().length || !chip.isConnected) return;
      if (transitionToSceneId ? timelinePanelTransition?.to !== transitionToSceneId : state.project.activeSceneId !== sceneId) return;
      // Scroll the list first, then only its owning column if the panel itself is off screen.
      // The floating timeline clips the visible work area; never scroll another column or the page.
      const limit = list.closest(".stage-col") || list.closest(".stage-panel") || list;
      const timelinePanel = document.getElementById("stage-timeline-panel");
      const overlayTop = timelinePanel && !timelinePanel.hidden && !timelinePanel.classList.contains("is-collapsed")
        ? timelinePanel.getBoundingClientRect().top : window.innerHeight;
      for (let container = list; container && container.id !== "view-stage"; container = container.parentElement) {
        if (/(auto|scroll)/.test(getComputedStyle(container).overflowY) && container.scrollHeight > container.clientHeight) {
          const viewport = container.getBoundingClientRect(), target = chip.getBoundingClientRect();
          const top = Math.max(viewport.top, 0), bottom = Math.min(viewport.bottom, overlayTop);
          if (bottom > top) {
            if (target.top < top || target.height > bottom - top) container.scrollTop += target.top - top;
            else if (target.bottom > bottom) container.scrollTop += target.bottom - bottom;
          } else if (container === list) container.scrollTop += target.top - viewport.top;
        }
        if (container === limit) break;
      }
    };
    scrollToChip();
    // メモ欄の高さは描画後に確定するため、その後も見出しの位置だけ再確認する。
    requestAnimationFrame(() => requestAnimationFrame(scrollToChip));
  }

  // シーンを前後へ送る。上下キーの割り当て先でもある
  function stepScene(dir, followPanel = false) {
    const rows = state.project.scenes.filter((row) => row.kind === "scene");
    if (rows.length < 2) { announce("シーンがひとつしかありません。"); return; }
    const at = rows.findIndex((row) => row.id === state.project.activeSceneId);
    const next = rows[clamp((at < 0 ? 0 : at) + dir, 0, rows.length - 1)];
    if (!next || next.id === state.project.activeSceneId) {
      announce(dir > 0 ? "最後のシーンです。" : "最初のシーンです。");
      return;
    }
    openScene(next.id, { throughTransition: true });
    if (followPanel && state.project.activeSceneId === next.id) followSceneInPanel(next.id);
  }

  function replaySceneTransition() {
    const rows = state.project.scenes.filter((row) => row.kind === "scene");
    const at = rows.findIndex((row) => row.id === state.project.activeSceneId);
    const fromScene = rows[at - 1];
    if (!state.animateScenes || !fromScene) return;
    beginSceneAnim(fromScene);
  }

  function openSceneFromList(id) {
    // The timeline owns seeking and playback; fall back when it cannot open this row.
    if (!window.dispatchEvent(new CustomEvent("stage-timeline-scene-open-request", {
      cancelable: true, detail: { sceneId: id },
    }))) return;
    openScene(id);
  }

  function openScene(id, options = {}) {
    timelinePanelTransition = null;
    /* 共有セッションのゲストはシーンを切り替えられない（ホストのシーンに追従する）。
       ホストからの同期は applyDocumentString が activeSceneId を直接差し替えるため、
       このガードの影響を受けない。 */
    if (document.body.classList.contains("stage-session-guest")) {
      announce("共有セッション中はホストのシーンに追従します。");
      return;
    }
    if (!options.fromTimeline) setTimelineLightCue(null);
    closeNoteEditor();
    if (sceneAlternatives && (options.fromTimeline || state.project.activeSceneId !== id)) sceneAlternatives.adopted(state.project);
    selectedNoteId = null;
    const cursorFromId = state.cursorRowId;    // 直前にカーソルがあった行（セクションの場合もある）も描き直す対象
    state.cursorRowId = options.cursorRowId || id;
    const transitionFromScene = options.transitionFromSceneId
      ? state.project.scenes.find(
        (row) => row.kind === "scene" && row.id === options.transitionFromSceneId,
      ) || null
      : null;
    managedTimecodeAudio = Boolean(options.managedTimecode);
    if (options.fromTimeline) {
      const timelineTrackId = normalizeAudioTrackId("scene", options.timelineTrackId);
      if (timelineTrackId) timelineAudioTrackId = timelineTrackId;
      else clearTimelineAudioPlayback();
    } else {
      clearTimelineAudioPlayback();
    }
    if (state.project.activeSceneId === id) {
      if (!options.fromTimeline && !options.throughTransition) { stopSceneAnim(); render(); }
      const liveSpins = transitionFromScene && state.animateScenes ? captureLiveSpins() : null;
      renderScenes();
      if (transitionFromScene && state.animateScenes) {
        beginSceneAnim(transitionFromScene, liveSpins, options.transitionDurationMs, options.transitionProgress);
      }
      return;
    }
    const before = sc();
    continueAudioOnNextSceneSync = !managedTimecodeAudio && Boolean(
      els.musicAudio && !els.musicAudio.paused && audioPlayback.ready
    );
    // 盆の生きた角度は、renderScenes→syncSpinRun が旧runを止める前のここで控える
    const liveSpins = captureLiveSpins();
    state.project.activeSceneId = id;
    selectedId = null;
    renderScenes({ activeChange: {
      fromId: before ? before.id : null, toId: id, cursorFromId, cursorToId: state.cursorRowId,
    } });
    renderCast();
    renderSets();
    renderLights();
    renderRigs();
    renderBeatTemplates();
    selectedTextId = null;
    renderScreenTexts();
    syncScreenTextControls();
    updateInspector();
    // 転換の初期姿勢を先に書き込む。開始済みなら beginSceneAnim がその姿勢を一度だけ描く。
    // 動きが無い切替だけは、ここで通常描画する。
    if (options.skipTransition || (!options.fromTimeline && !options.throughTransition)) { stopSceneAnim(); render(); }
    else if (!beginSceneAnim(transitionFromScene || before, liveSpins, options.transitionDurationMs, options.transitionProgress)) render();
    persistSoon();
    window.dispatchEvent(new CustomEvent("stage-scene-change", {
      detail: { sceneId: id, fromTimeline: Boolean(options.fromTimeline), transition: sceneAnim ? {fromSceneId: sceneAnim.fromSceneId, toSceneId: sceneAnim.toSceneId, progress: sceneAnim.progress, durationMs: sceneAnim.durationMs} : null },
    }));
    announce(`${sc().title}を開きました。`);
  }

  function addScene(carryRig) {
    const p = state.project;
    const carried = carryRig ? currentRigPieces().map(copyPiece) : [];
    if (!canAddSceneRows() || !canAddScenePieces({ pieces: [] }, carried.length)) return;
    checkpoint();
    const i = cursorIndex();
    // セクションを起点にしたときは、その中身として一段内側へ入れる。
    // 正規化済みのシーンから始める場合も、同じ親の下の兄弟として残す。
    const depth = i >= 0 ? p.scenes[i].depth + (p.scenes[i].kind === "section" ? 1 : 0) : 1;
    const count = p.scenes.filter((x) => x.kind === "scene").length;
    const scene = newScene(sceneTitle(count + 1), false, "scene", depth);
    scene.background = sc().background;      // 劇場は変えず、いまの背景色だけ引き継ぐ
    carried.forEach((piece) => scene.pieces.push(piece));
    // いまの行（とその中身）のすぐ後ろへ入れる
    const at = i >= 0 ? i + 1 + sceneChildren(i).length : p.scenes.length;
    p.scenes.splice(at, 0, scene);
    p.activeSceneId = scene.id;
    state.cursorRowId = scene.id;
    selectedId = null;
    renderScenes();
    renderCast();
    renderSets();
    renderLights();
    renderRigs();
    renderRosterKindLayer();
    if (els.setInfoPropShapeRow && !els.setInfoPropShapeRow.hidden) {
      const item = currentSetItem();
      renderPropShapeSelect(els.setInfoPropShape, item && item.propShape);
    }
    selectedTextId = null;
    renderScreenTexts();
    syncScreenTextControls();
    updateInspector();
    render();
    persistSoon();
    announce(`${scene.title}を足しました。`);
  }

  /* セクションを足す。いまの行のすぐ後ろへ、同じ深さで入れる。
   * 入れ物だけなので絵は持たず、押すと開閉する。 */
  function addSection() {
    if (!canAddSceneRows()) return;
    checkpoint();
    const p = state.project;
    const i = cursorIndex();
    const depth = i >= 0 ? p.scenes[i].depth : 0;
    const count = p.scenes.filter((x) => x.kind === "section").length;
    const section = newScene(sx(`セクション ${count + 1}`, `Section ${count + 1}`), false, "section", depth);
    const at = i >= 0 ? i + 1 + sceneChildren(i).length : p.scenes.length;
    p.scenes.splice(at, 0, section);
    state.cursorRowId = section.id;
    renderScenes();
    persistSoon();
    announce(sx(`${section.title}を足しました。ここにシーンを追加できます。`,
      `Added ${section.title}. You can add scenes here.`));
  }

  // セクションを起点にしたときは、中身ごと複製する
  /* シーンをまるごと写す。駒には新しい札を配り、
   * 付箋が指している駒の札も新しい方へ付け替える（付け替えないと写した瞬間に紐が切れる）。 */
  function cloneScene(row) {
    const copy = JSON.parse(JSON.stringify(row));
    copy.id = rid(row.kind === "section" ? "sect" : "scene");
    const swap = new Map();
    copy.pieces = (copy.pieces || []).map((piece) => {
      const id = nextId();
      swap.set(piece.id, id);
      return { ...piece, id, originId: piece.originId || piece.id };
    });
    copy.pieces.forEach((piece) => {
      if (piece.heldBy) piece.heldBy = swap.get(piece.heldBy) || null;
      for (const key of ["mountOn", "mountWith"]) if (piece[key]) piece[key] = swap.get(piece[key]) || null;
    });
    copy.notes = (copy.notes || []).map((note) => ({
      ...note,
      id: rid("note"),
      pieceId: note.pieceId ? (swap.get(note.pieceId) || null) : null,
    }));
    copy.arrows = (copy.arrows || []).map((arrow) => ({ ...arrow, id: rid("arrow") }));
    sceneAlternatives?.remapScene(copy, row.id, () => rid("alt-copy"));
    return normalizeScene(copy, 0);
  }

  /* ---------- 次のシーンから動線を起こす ----------
     「次のシーンをつくる」で動線を実らせる向きのちょうど逆。
     先に次のシーンを作ってから並べ替えることの方が多いので、
     「もう動かしてある差」から動線を引き直せると、置き直す手間が要らない。
     同じものが次のシーンでどれかは twinOf で照合する（登録の札→写しの元）。 */

  // シーンの並びの中で、その次のシーン。セクションの行は飛ばす
  function nextSceneOf(scene) {
    const rows = state.project.scenes.filter((row) => row.kind === "scene");
    const at = rows.indexOf(scene);
    return at >= 0 && at + 1 < rows.length ? rows[at + 1] : null;
  }

  /* これ未満しか動いていないものは、動線を引かない。
     立ち位置の微調整まで矢印になると、平面図が線だらけで読めなくなる。 */
  const ROUTE_MIN_M = 0.25;

  /* 次のシーンに居ない演者。舞台上に居て、向こうでは舞台裏＝はける人。
     装置は対象にしない（装置は「消える」のが転換として普通のため）。 */
  function exitPieces(scene, next) {
    return (scene.pieces || []).filter((piece) => piece.type === "performer"
      && onStageArea(piece.u, piece.v)
      && !twinOf(piece, next.pieces || []));
  }

  // はけ先。近い側の袖の中ほど（スラストは奥の袖）
  function wingDest(piece) {
    const b = planBounds();
    if (b.vMin < 0) return { u: clamp(piece.u, 0.06, 0.94), v: b.vMin * 0.6 };
    return {
      u: piece.u <= 0.5 ? b.uMin * 0.6 : 1 + (b.uMax - 1) * 0.6,
      v: clamp(piece.v, 0.08, 0.92),
    };
  }

  function movedPairs(scene, next) {
    const size = venueSize();
    const out = [];
    (scene.pieces || []).forEach((piece) => {
      if (piece.heldBy) return;
      const twin = twinOf(piece, next.pieces || []);
      if (!twin) return;
      const dx = (twin.u - piece.u) * (size.width || 12);
      const dz = (twin.v - piece.v) * (size.depth || 9);
      if (Math.hypot(dx, dz) < ROUTE_MIN_M) return;
      out.push({ piece, twin });
    });
    return out;
  }

  function deriveRoutes(scene) {
    if (!editionAllows("routeTool")) return;
    const next = nextSceneOf(scene);
    if (!next) { announce("次のシーンがありません。"); return; }
    const pairs = movedPairs(scene, next);
    const exits = exitPieces(scene, next).filter((piece) => !piece.route);
    // すでに引いてある動線は残す。手で曲げた線を黙って捨てない
    const fresh = pairs.filter((pair) => !pair.piece.route);
    const kept = pairs.length - fresh.length;
    if (!fresh.length && !exits.length) {
      announce(kept
        ? "動いたものには、すでに動線が引いてあります。"
        : "次のシーンとの差がありません。向こうで動かしてから引いてください。");
      return;
    }
    checkpoint();
    fresh.forEach(({ piece, twin }) => {
      /* 曲がりの制御点は、いまと行き先のちょうど中間。まっすぐな線になる。
         曲げたいときは、平面図で真ん中の丸を掴んで引く。 */
      piece.route = {
        u: clamp(twin.u, -0.5, 1.5),
        v: clamp(twin.v, -0.5, 1),
        bu: (piece.u + twin.u) / 2,
        bv: (piece.v + twin.v) / 2,
      };
    });
    // 次のシーンで舞台裏の人は、近い側の袖へはける動線にする
    exits.forEach((piece) => {
      const dest = wingDest(piece);
      piece.route = { u: dest.u, v: dest.v,
        bu: (piece.u + dest.u) / 2, bv: (piece.v + dest.v) / 2 };
    });
    // 隠したまま引くと「押したのに何も起きない」に見えるので、表示に戻す
    if (!(state.showRoutesCast && state.showRoutesLight && state.showRoutesSet)) {
      state.showRoutesCast = true;
      state.showRoutesLight = true;
      state.showRoutesSet = true;
      if (els.planRoutesCast) els.planRoutesCast.checked = true;
      if (els.planRoutesLight) els.planRoutesLight.checked = true;
      if (els.planRoutesSet) els.planRoutesSet.checked = true;
    }
    renderScenes();
    updateInspector();
    render();
    persistSoon();
    const total = fresh.length + exits.length;
    announce(exits.length
      ? `${total}本の動線を引きました。${exits.length}本は袖へのはけです。`
      : (kept
        ? `${total}本の動線を引きました。${kept}本はすでにあるので残しました。`
        : `${total}本の動線を引きました。`));
  }

  /* 選んだ駒だけへ新しい札を配る。手に持つ関係は両方が選ばれたときだけ残し、
     指定時だけ動線の行き先へ移す。元シーンの駒は一切書き換えない。 */
  function inheritedScenePieces(sourcePieces, selectedIds, idFactory = nextId, moveToRouteEnd = true) {
    const selected = new Set(Array.from(selectedIds || []));
    const swap = new Map();
    const entries = (sourcePieces || [])
      .filter((piece) => selected.has(piece.id))
      .map((piece) => {
        const copy = JSON.parse(JSON.stringify(piece));
        const id = idFactory();
        swap.set(piece.id, id);
        copy.id = id;
        copy.originId = piece.originId || piece.id;
        return { copy, wasHeld: Boolean(piece.heldBy) };
      });
    entries.forEach(({ copy, wasHeld }) => {
      copy.heldBy = copy.heldBy ? (swap.get(copy.heldBy) || null) : null;
      for (const key of ["mountOn", "mountWith"]) if (copy[key]) copy[key] = swap.get(copy[key]) || null;
      if (moveToRouteEnd && !wasHeld && copy.route) {
        const routeU = Number(copy.route.u);
        const routeV = Number(copy.route.v);
        copy.u = Math.max(-0.5, Math.min(1.5, Number.isFinite(routeU) ? routeU : 0.5));
        copy.v = Math.max(-0.5, Math.min(1, Number.isFinite(routeV) ? routeV : 0.5));
      }
      copy.route = null;
      copy.supportId = null;
      copy.base = 0;
    });
    return entries.map(({ copy }) => copy);
  }

  function buildNextScene(source, mode, selectedIds, moveToRouteEnd = true) {
    const count = state.project.scenes.filter((row) => row.kind === "scene").length;
    const next = newScene(
      mode === "inherit" ? sx(`${source.title} の続き`, `${source.title} – continuation`) : sceneTitle(count + 1),
      false,
      "scene",
      source.depth,
    );
    // 地の色だけは同じ舞台の基準として残す。描画・写真・注釈はシーン固有なので持ち越さない。
    next.background = source.background || next.background;
    if (mode === "inherit") {
      next.pieces = inheritedScenePieces(source.pieces, selectedIds, nextId, moveToRouteEnd);
    }
    return normalizeScene(next, count);
  }

  function createNextScene(source, mode, selectedIds, moveToRouteEnd = true) {
    const p = state.project;
    const i = p.scenes.indexOf(source);
    if (i < 0) return;
    const picked = mode === "inherit" ? Array.from(selectedIds || []) : [];
    if (mode === "inherit" && !picked.length) {
      announce(tx("引き継ぐものを1つ以上選んでください。"));
      return;
    }
    if (!canAddSceneRows() || !hasCapacity(picked, "piecesPerScene", 0, "このシーンの駒")) return;
    checkpoint();
    const next = buildNextScene(source, mode, picked, moveToRouteEnd);
    p.scenes.splice(i + 1, 0, next);
    p.activeSceneId = next.id;
    state.cursorRowId = next.id;
    selectedId = null;
    selectedNoteId = null;
    closeNoteEditor();
    closeSceneCreate();
    renderScenes();
    renderCast();
    renderSets();
    renderLights();
    renderRigs();
    selectedTextId = null;
    renderScreenTexts();
    syncScreenTextControls();
    updateInspector();
    render();
    persistSoon();
    announce(tx("次のシーンを作りました。"));
  }

  function duplicateScene() {
    sceneAlternatives?.adopted(state.project);
    const p = state.project;
    const i = cursorIndex();
    if (i < 0) return;
    const cur = p.scenes[i];
    const block = [cur].concat(sceneChildren(i));
    const copies = block.map((row) => cloneScene(row));
    if (!canAddSceneRows(copies.length)
      || copies.some((row) => !hasCapacity(row.pieces, "piecesPerScene", 0, "このシーンの駒"))) return;
    checkpoint();
    copies[0].title = `${cur.title} の複製`;
    if ([1, 2].includes(p.lightingDesign?.version) && Array.isArray(p.lightingDesign.scenes)) {
      block.forEach((source, index) => {
        const lighting = p.lightingDesign.scenes.find(row => row.id === source.id);
        if (lighting && copies[index].kind === "scene") p.lightingDesign.scenes.push({ ...projectIoClone(lighting), id: copies[index].id, name: copies[index].title });
      });
    }
    p.scenes.splice(i + block.length, 0, ...copies);
    window.STAGE_TIME_DOMAIN?.remapPlacements(p, new Map(block.map((row, index) => [row.id, copies[index].id])), () => rid("media"));
    sceneAlternatives?.restore(p);
    const firstScene = copies.find((x) => x.kind === "scene");
    if (firstScene) p.activeSceneId = firstScene.id;
    state.cursorRowId = copies[0].id;
    selectedId = null;
    renderScenes();
    renderCast();
    renderSets();
    renderLights();
    renderRigs();
    selectedTextId = null;
    renderScreenTexts();
    syncScreenTextControls();
    updateInspector();
    render();
    persistSoon();
    announce(`${cur.title}を複製しました。前のシーンから少しずつ動かすときに使えます。`);
  }

  function sceneDeleteDetails(targetScene = null) {
    const p = state.project;
    const i = targetScene ? p.scenes.indexOf(targetScene) : cursorIndex();
    if (i < 0) return null;
    const cur = p.scenes[i];
    const kids = sceneChildren(i);
    const kidScenes = kids.filter((x) => x.kind === "scene").length;
    const sceneLoss = (cur.kind === "scene" ? 1 : 0) + kidScenes;
    if (p.scenes.filter((x) => x.kind === "scene").length - sceneLoss < 1) {
      announce(tx("シーンがひとつしかありません。"));
      return null;
    }
    const message = cur.kind === "section"
      ? (kids.length
        ? sx(`「${cur.title}」セクションと、中に入れた${kids.length}件を削除します。`,
          `Delete “${cur.title}” and its ${kids.length} contained items.`)
        : sx(`「${cur.title}」セクションを削除します。`, `Delete the “${cur.title}” section.`))
      : sx(`「${cur.title}」を削除します。`, `Delete “${cur.title}”.`);
    return { p, i, cur, kids, message };
  }

  function openSceneDelete(targetScene, returnFocus = null) {
    const details = sceneDeleteDetails(targetScene);
    if (!details || !els.sceneDeleteModal || !els.sceneDeleteBackdrop) return false;
    sceneDeleteTarget = details.cur;
    sceneDeleteReturnFocus = returnFocus || null;
    if (els.sceneDeleteMessage) {
      const hiddenData = !editionAllows("sceneAlternatives") && [details.cur, ...details.kids].some(row =>
        row.sceneAlternatives?.items?.length || row.lightingIntent || row.notes?.length || row.strokes?.length || row.arrows?.length
        || row.audioTrackId || row.pieces?.some(piece => piece.type === "light" || piece.route)
        || state.project.cues?.some(cue => cue.sceneId === row.id || cue.sectionId === row.id)
        || state.project.lightingDesign?.scenes?.some(scene => scene.id === row.id));
      els.sceneDeleteMessage.textContent = `${details.message} ${tx("削除したものは元に戻せません。")}${hiddenData ? sx(" このシーンに含まれる照明・注釈・別案などの非表示データも削除対象です。必要なら先に別バージョンを作るか、ファイルへ書き出してください。", " Hidden data in these scenes, including lighting, annotations and alternatives, will also be deleted. Create a version or export a file first if needed.") : ""}`;
    }
    if (els.sceneDeleteCheck) els.sceneDeleteCheck.checked = false;
    if (els.sceneDeleteSubmit) els.sceneDeleteSubmit.disabled = true;
    els.sceneDeleteModal.hidden = false;
    els.sceneDeleteBackdrop.hidden = false;
    if (els.sceneDeleteCheck) els.sceneDeleteCheck.focus();
    return true;
  }

  function closeSceneDelete(restoreFocus = true) {
    if (els.sceneDeleteModal) els.sceneDeleteModal.hidden = true;
    if (els.sceneDeleteBackdrop) els.sceneDeleteBackdrop.hidden = true;
    const target = sceneDeleteReturnFocus;
    sceneDeleteTarget = null;
    sceneDeleteReturnFocus = null;
    if (restoreFocus && target && target.isConnected && typeof target.focus === "function") target.focus();
  }

  // セクションを消すときは、中に入れたシーンごと消える。確認は専用モーダルで済ませてから呼ぶ。
  function deleteScene(targetScene = null) {
    const details = sceneDeleteDetails(targetScene);
    if (!details) return false;
    const { p, i, cur, kids } = details;
    checkpoint();
    p.scenes.splice(i, 1 + kids.length);
    const nextScene = p.scenes.slice(i).find((x) => x.kind === "scene")
      || p.scenes.slice(0, i).reverse().find((x) => x.kind === "scene");
    p.activeSceneId = nextScene.id;
    state.cursorRowId = nextScene.id;
    selectedId = null;
    renderScenes();
    renderCast();
    renderSets();
    renderLights();
    renderRigs();
    selectedTextId = null;
    renderScreenTexts();
    syncScreenTextControls();
    updateInspector();
    render();
    persistSoon();
    announce(`${cur.title}を削除しました。`);
    return true;
  }

  // バージョン複製: いまのプロジェクトを丸ごと写し、別の版として続ける。
  // 設計計画書6.5節の派生（親ID＋一行の理由）に合わせ、完全な版管理は作らない。
  /* T-20（2026-09-18 本人要望）: OSの素の入力窓（window.prompt）をやめ、アプリの窓に寄せる。
   * 方針の根拠は gamma-workspace.js の「OSの素の窓が急に出る違和感をなくすため」。
   * 一行の入力＋〔キャンセル〕〔複製する〕。Enterで確定、Escapeで取り消し、開いたら入力欄へ合わせる。
   * 取り消し（null）は window.prompt と同じ意味にする＝呼ぶ側の分岐を変えない。 */
  function askBranchReason() {
    return new Promise((resolve) => {
      const backdrop = document.createElement("div");
      backdrop.className = "stage-modal-backdrop";
      const box = document.createElement("div");
      box.className = "stage-modal stage-branch-reason-modal";
      box.setAttribute("role", "dialog");
      box.setAttribute("aria-modal", "true");
      const head = document.createElement("header");
      head.className = "stage-modal-head";
      const title = document.createElement("h2");
      title.id = "stage-branch-reason-title";
      title.textContent = tx("別バージョンとして複製");
      box.setAttribute("aria-labelledby", title.id);
      const dismiss = document.createElement("button");
      dismiss.type = "button";
      dismiss.id = "stage-branch-reason-close";
      dismiss.className = "stage-modal-close";
      dismiss.setAttribute("aria-label", tx("閉じる"));
      dismiss.innerHTML = '<svg class="stage-square-glyph" viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M4 4l8 8M12 4l-8 8"/></svg>';
      dismiss.addEventListener("click", () => done(null));
      head.append(title, dismiss);
      const body = document.createElement("div");
      body.className = "stage-modal-body";
      /* T-20（2026-09-18 本人指摘）: この窓は「名前を登録する」ように見えていた。
       * ★いちばん知りたい「次が v いくつになるか」が、窓のどこにも出ていなかった。
       *   本人決定: 数字を大きく出し、入力欄は「メモ（省略可）」と明記して残す
       *   （メモは版の欄の下に「〜（元の版から派生）」として後で出るので、意味はある）。 */
      const current = state.project.versionLabel || "v1";
      const step = document.createElement("p");
      step.className = "stage-branch-version-step";
      step.textContent = `${current} → ${nextVersionLabel(current)}`;
      const lead = document.createElement("p");
      lead.className = "stage-profile-hint";
      lead.textContent = tx("別案＝1シーンの中で試す／版＝ショー全体の写し") + "。 " + tx("もとの版はそのまま残ります。");
      const memoLabel = document.createElement("p");
      memoLabel.className = "stage-field-label";
      memoLabel.textContent = tx("メモ（省略可）");
      const input = document.createElement("input");
      input.type = "text";
      input.className = "stage-text-input";
      input.maxLength = 120;
      input.autocomplete = "off";
      input.setAttribute("data-1p-ignore", "");
      input.placeholder = tx("何を変えるための版か");
      input.setAttribute("aria-label", tx("何を変えるための版か"));
      body.append(step, lead, memoLabel, input);
      const acts = document.createElement("footer");
      acts.className = "stage-branch-reason-actions";
      const mk = (label, value, cls) => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = cls;
        button.textContent = tx(label);
        button.addEventListener("click", () => { done(value === null ? null : input.value); });
        return button;
      };
      const onKey = (event) => {
        if (event.isComposing || event.keyCode === 229) return;
        if (event.key === "Escape") { event.preventDefault(); done(null); }
        if (event.key === "Enter" && event.target === input) { event.preventDefault(); done(input.value); }
      };
      function done(value) {
        document.removeEventListener("keydown", onKey, true);
        backdrop.remove(); box.remove();
        resolve(value);
      }
      const cancel = mk("キャンセル", null, "btn-quiet"); cancel.id = "stage-branch-reason-cancel";
      acts.append(cancel, mk("複製する", "ok", "stage-minor-action"));
      box.append(head, body, acts);
      backdrop.addEventListener("click", () => done(null));
      document.addEventListener("keydown", onKey, true);
      document.body.append(backdrop, box);
      input.focus();
    });
  }

  /* 2026-09-18 本人要望: 「バージョンの数字をクリックすることで、過去のバージョンに戻れるように」。
   * 版は別々のショーとして棚（readShows）に入っていて、parentVersionId で親子が繋がっている。
   * いま開いている版から根までさかのぼり、その根に繋がる版をすべて集めて並べる。 */
  function versionFamilyRows() {
    const shows = availableShows();
    const byId = new Map();
    Object.keys(shows).forEach((id) => {
      const entry = shows[id];
      const project = entry?.state?.project || (entry?.summary && {
        ...entry.summary, versionLabel: entry.summary.version,
      });
      if (!project) return;
      byId.set(id, {
        id, title: String(project.title || "").trim() || tx("無題のショー"),
        version: String(project.versionLabel || "").trim() || "v1",
        parent: typeof project.parentVersionId === "string" ? project.parentVersionId : null,
        savedAt: shows[id].savedAt || "", reason: String(project.branchReason || "").trim(),
      });
    });
    // 開いているショーは、まだ棚へ書かれていないことがあるので必ず足す。
    const open = state.project;
    byId.set(open.id, {
      id: open.id, title: String(open.title || "").trim() || tx("無題のショー"),
      version: String(open.versionLabel || "").trim() || "v1",
      parent: typeof open.parentVersionId === "string" ? open.parentVersionId : null,
      savedAt: state.lastSavedAt || "", reason: String(open.branchReason || "").trim(),
    });
    const rootOf = (row) => {
      let current = row; const seen = new Set();
      while (current && current.parent && byId.has(current.parent) && !seen.has(current.id)) {
        seen.add(current.id); current = byId.get(current.parent);
      }
      return current;
    };
    const root = rootOf(byId.get(open.id));
    const family = [];
    byId.forEach((row) => { if (root && rootOf(row) && rootOf(row).id === root.id) family.push(row); });
    return family.sort((a, b) => String(a.version).localeCompare(String(b.version), undefined, { numeric: true }));
  }

  function openVersionPicker() {
    const rows = versionFamilyRows();
    const backdrop = document.createElement("div");
    backdrop.className = "stage-modal-backdrop";
    const box = document.createElement("div");
    box.className = "stage-modal stage-version-picker";
    box.setAttribute("role", "dialog");
    box.setAttribute("aria-modal", "true");
    const head = document.createElement("header");
    head.className = "stage-modal-head";
    const title = document.createElement("h2");
    title.id = "stage-version-picker-title";
    title.textContent = tx("バージョンを切り替える");
    box.setAttribute("aria-labelledby", title.id);
    const dismiss = document.createElement("button");
    dismiss.type = "button";
    dismiss.id = "stage-version-picker-dismiss";
    dismiss.className = "stage-modal-close";
    dismiss.setAttribute("aria-label", tx("閉じる"));
    dismiss.innerHTML = '<svg class="stage-square-glyph" viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M4 4l8 8M12 4l-8 8"/></svg>';
    dismiss.addEventListener("click", () => close());
    head.append(title, dismiss);
    const body = document.createElement("div");
    body.className = "stage-modal-body";
    const close = () => { document.removeEventListener("keydown", onKey, true); backdrop.remove(); box.remove(); };
    const onKey = (event) => { if (event.key === "Escape") { event.preventDefault(); close(); } };
    if (rows.length <= 1) {
      const empty = document.createElement("p");
      empty.className = "stage-profile-hint";
      empty.textContent = tx("ほかの版はまだありません。");
      body.append(empty);
    } else {
      const hint = document.createElement("p");
      hint.className = "stage-profile-hint";
      hint.textContent = tx("選ぶとその版を開きます。いま開いている版には印が付いています。");
      const list = document.createElement("div");
      list.className = "stage-version-list";
      rows.forEach((row) => {
        const isCurrent = row.id === state.project.id;
        const button = document.createElement("button");
        button.type = "button";
        button.className = `stage-version-row${isCurrent ? " is-current" : ""}`;
        const label = document.createElement("span");
        label.className = "stage-version-row-label";
        label.textContent = row.version;
        const meta = document.createElement("span");
        meta.className = "stage-version-row-meta";
        const when = row.savedAt ? window.STAGE_TIME_DOMAIN.dateText(row.savedAt, lang) : "";
        meta.textContent = [row.title, row.reason, when].filter(Boolean).join("・")
          + (isCurrent ? `・${tx("開いています")}` : "");
        button.append(label, meta);
        button.disabled = isCurrent;
        button.addEventListener("click", () => { close(); openShow(row.id); });
        list.append(button);
      });
      body.append(hint, list);
    }
    const acts = document.createElement("footer");
    acts.className = "stage-branch-reason-actions";
    const cancel = document.createElement("button");
    cancel.type = "button";
    cancel.className = "btn-quiet";
    cancel.textContent = tx("閉じる");
    cancel.id = "stage-version-picker-close";
    cancel.addEventListener("click", close);
    acts.append(cancel);
    box.append(head, body, acts);
    backdrop.addEventListener("click", close);
    document.addEventListener("keydown", onKey, true);
    document.body.append(backdrop, box);
    (box.querySelector(".stage-version-row:not(.is-current)") || cancel).focus();
  }

  async function duplicateVersion() {
    const reason = await askBranchReason();
    if (reason === null) return;
    const outgoingWork=activeWorkFolder();
    if(outgoingWork && !(await saveCurrentShow()).ok)return;
    checkpoint();
    const p = state.project;
    const copy = sceneAlternatives ? sceneAlternatives.projectCopy(p) : JSON.parse(JSON.stringify(p));
    copy.id = rid("proj");
    copy.parentVersionId = p.id;
    copy.branchReason = reason.trim();
    copy.createdAt = nowIso();
    copy.versionLabel = nextVersionLabel(p.versionLabel);
    const sceneIds = new Map(copy.scenes.map(scene => [scene.id, rid("scene")]));
    copy.scenes = copy.scenes.map(scene => {
      const oldId = scene.id, result = cloneScene(scene);
      result.id = sceneIds.get(oldId);
      if (result.sceneAlternatives) {
        for (const item of result.sceneAlternatives.items) {
          item.cues.forEach(cue => { cue.sceneId = result.id; });
          if (item.lighting.native) item.lighting.native.id = result.id;
        }
      }
      return result;
    });
    if (copy.runOfShow?.version === 1 && Array.isArray(copy.runOfShow.items)) {
      copy.runOfShow.items.forEach(item => { if(sceneIds.has(item.sceneId)) item.sceneId=sceneIds.get(item.sceneId); });
    }
    for (const cue of copy.cues || []) {
      cue.id = rid("cue");
      if (sceneIds.has(cue.sceneId)) cue.sceneId = sceneIds.get(cue.sceneId);
      if (sceneIds.has(cue.sectionId)) cue.sectionId = sceneIds.get(cue.sectionId);
    }
    for (const row of copy.lightingDesign?.scenes || []) if (sceneIds.has(row.id)) row.id = sceneIds.get(row.id);
    for (const plan of copy.lightingDesign?.plans || []) for (const binding of plan.sceneBindings || [])
      if (sceneIds.has(binding.hostSceneId)) binding.hostSceneId = sceneIds.get(binding.hostSceneId);
    // This copy was derived from modern items; remapped IDs are not legacy edits.
    sceneAlternatives?.restore(copy, { reconcile: false });
    copy.activeSceneId = copy.scenes[0].id;
    let forkedWork=null;
    if(outgoingWork)try{
      const generation=loadedStateGeneration;
      forkedWork=await outgoingWork.fork(JSON.stringify(makeProjectExportDocument(copy,true,state.projectFileEnvelope)),{guard:()=>state.project===p&&generation===loadedStateGeneration&&workFolderEligible()});
    }catch(error){workFolderUi?.failed(error);return;}
    clearAudioEngine();
    state.projectPackageCarry = window.STAGE_PROJECT_FILE.bindCarry(state.projectPackageCarry, copy, state.lastSavedAt);
    state.project = copy;
    fileAutosaveUi?.refresh(true);
    if(typeof invalidateDriveBackup === "function")invalidateDriveBackup();
    if(forkedWork)attachWorkFolder(forkedWork);
    selectedAudioTrackId = copy.audioTracks[0]?.id || null;
    audioPanelSignature = "";
    selectedId = null;
    renderScenes();
    renderVenueControls();
    updateInspector();
    render();
    persistSoon();
    announce(`${copy.versionLabel}として複製しました。元の版は書き出したファイルの中に残ります。`);
  }

  // v1 → v2 のように末尾の数を繰り上げる。数が無ければ「 の改訂」を足す
  /* ---- R-18（2026-09-17 本人要望）: ショーの版名は「v」＋数字だけにする ----
   * 本人の言葉:「規則性を持たせて、必ず v1 などの形に変換する。v は小文字。
   *   v は自動でつけて、プラス1のボタンだけにする。
   *   規則外の場合は、末尾に数字があればそれを引き継ぐ」
   * ★既存のショーには自由入力の版名（"Study A" や、以前の nextVersionLabel が作った
   *   "v1 の改訂" など）が入っている可能性がある。読み込んだときにここで形を揃える。
   *   末尾の数字を拾うので "第2稿" は v2、数字が無ければ v1 になる。 */
  function normalizeVersionLabel(value) {
    const text = String(value == null ? "" : value).trim();
    /* 「末尾に数字があればそれを引き継ぐ」（本人決定）。
       ただし末尾ぴったりに限ると「第2稿」のように後ろへ文字が付く書き方を拾えないので、
       **最後に出てくる数字**を使う。実測: v3→v3 ／ 第2稿→v2 ／ Study A→v1 ／ v1 の改訂→v1。 */
    const all = text.match(/\d+/g);
    const n = all && all.length ? Math.max(1, Math.min(9999, Number(all[all.length - 1]))) : 1;
    return `v${n}`;
  }
  function nextVersionLabel(label) {
    /* R-18: 形が v＋数字に揃っているので、数字を1つ上げるだけでよい。
       以前あった「数字が無ければ『〜 の改訂』を足す」分岐は要らなくなった。 */
    const m = normalizeVersionLabel(label).match(/^v(\d+)$/);
    return `v${Math.min(9999, Number(m[1]) + 1)}`;
  }

