  async function writeProjectExport(
    includeVenue,
    filename = normaliseProjectExportFilename(defaultProjectExportBasename(state.project)),
    options = {},
  ) {
    try {
      if (options.projectPackage) return await exportProjectPackage(includeVenue, filename, options);
      /* かつてこのローカル変数を document と名付けていて、グローバルの document を
         覆い隠していた。document.createElement が落ち、書き出しが無反応になっていた。 */
      const exportDoc = makeProjectExportDocument(state.project, includeVenue, state.projectFileEnvelope);
      const data = JSON.stringify(exportDoc, null, 2);
      const blob = new Blob([data], { type: "application/json" });
      const didChooseDestination = await (options.downloadOnly ? downloadBlob(blob, filename) : saveProjectBlob(blob, filename));
      if (!applyProjectExportOutcome(state, didChooseDestination, nowIso())) {
        announce("書き出しをやめました。");
        return false;
      }
      latestProjectExportComparable = exportedProjectComparisonJson(exportDoc.project);
      // 既存の「ファイルへ書き出す」が実際に保存先まで完了した時刻だけを表示する。
      syncSaveStamps();
      persistSoon();
      updateBackupNote();
      announce(includeVenue || !bundledVenueForProject(state.project)
        ? "このショーをファイルへ書き出しました。チームへ渡せます。"
        : "劇場データを含めず、元の劇場IDを残してショーを書き出しました。");
      return true;
    } catch (error) {
      console.error("stage export: ショーを書き出せませんでした", error);
      exportFailureNotice("ショーを書き出せませんでした。もう一度お試しください。");
    } finally {
      restoreProjectExportFocus();
    }
  }

