  // パネルはクリック元の図から出さない。正面図では姿勢帯の手前、平面図では図の下端まで。
  function gammaFloatingPanelBounds() {
    const canvasEl = floatingInspectorAnchor.view === "plan" ? planCanvas : canvas;
    const rect = canvasEl?.getBoundingClientRect();
    if (!rect) return null;
    const edge = 16;
    const host = document.querySelector(".stage-sketch-grid");
    const hostRect = host?.getBoundingClientRect();
    const centerRect = document.getElementById("stage-col-center")?.getBoundingClientRect();
    const poseStrip = els.poseStrip?.getBoundingClientRect();
    const visualBottom = floatingInspectorAnchor.view === "front" && poseStrip && poseStrip.top > rect.top && poseStrip.top < rect.bottom
      ? poseStrip.top : rect.bottom;
    const left = Math.max(rect.left, hostRect?.left || 0, 0) + edge;
    const right = Math.min(rect.right, hostRect?.right || innerWidth, innerWidth) - edge;
    const headerBottom = document.querySelector(".stage-sketch-head")?.getBoundingClientRect().bottom || 0;
    const top = Math.max(rect.top, centerRect?.top || 0, hostRect?.top || 0, headerBottom, 0) + edge;
    const zoomControls = canvasEl.closest(".stage-canvas-wrap")?.querySelector(".stage-zoom-fab");
    const zoomRect = zoomControls?.getBoundingClientRect();
    // Reserve the visible zoom row as well as the drawing, including after a drag or resize.
    const controlGap = parseFloat(getComputedStyle(canvasEl).getPropertyValue("--gamma-gap")) || 8;
    const controlsTop = zoomRect?.width && zoomRect?.height ? zoomRect.top - controlGap : Infinity;
    const bottom = Math.min(visualBottom - edge, controlsTop, (centerRect?.bottom || innerHeight) - edge, (hostRect?.bottom || innerHeight) - edge, gammaFloatingPanelBottom() - edge);
    return { left, right: Math.max(left, right), top, bottom: Math.max(top, bottom) };
  }

  function clampGammaFloatingPanelPosition(left, top, width, height) {
    const bounds = gammaFloatingPanelBounds();
    if (!bounds) return { left, top };
    return {
      left: Math.max(bounds.left, Math.min(bounds.right - width, left)),
      top: Math.max(bounds.top, Math.min(bounds.bottom - height, top)),
    };
  }

  // 浮動パネルはスクロール列の外、舞台グリッド直下へ置く。
  // 親の境界線とスクロール量を含めて、表示座標を親内の座標へ変換する。
  function setGammaFloatingPanelViewportPosition(panel, left, top) {
    const apply = (nextLeft, nextTop) => {
      const parent = panel.offsetParent || panel.parentElement;
      const parentRect = parent?.getBoundingClientRect();
      panel.style.left = `${nextLeft - (parentRect?.left || 0) - (parent?.clientLeft || 0) + (parent?.scrollLeft || 0)}px`;
      panel.style.top = `${nextTop - (parentRect?.top || 0) - (parent?.clientTop || 0) + (parent?.scrollTop || 0)}px`;
    };
    apply(left, top);
    // 通常列から absolute へ切り替えると親列の高さが変わることがある。
    // 切替後の実座標でもう一度図内へ合わせる。
    const placed = panel.getBoundingClientRect();
    const corrected = clampGammaFloatingPanelPosition(left, top, placed.width, placed.height);
    if (Math.abs(corrected.left - placed.left) > 0.5 || Math.abs(corrected.top - placed.top) > 0.5) {
      apply(corrected.left, corrected.top);
    }
    requestAnimationFrame(() => {
      if (!panel.classList.contains("gamma-selection-floating")) return;
      const settled = panel.getBoundingClientRect();
      const settledPosition = clampGammaFloatingPanelPosition(
        settled.left, settled.top, settled.width, settled.height,
      );
      if (Math.abs(settledPosition.left - settled.left) > 0.5
          || Math.abs(settledPosition.top - settled.top) > 0.5) {
        apply(settledPosition.left, settledPosition.top);
      }
    });
  }

